    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that can't fit the next item's likely needs.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly usable by the lookahead item.
            score -= 10.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: penalize opening new bins when good fits exist,
    // but allow it when post-residual would be highly reusable.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 20.0 * progress; // cheaper to open bins early
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin pairs well with upcoming item
        }
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 12.0; // don't open a new bin worse than the mean state
        }
    }

    // Slightly favor bins below the mean residual (consolidating fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure to use many-open-bin situations efficiently.
    score -= 0.01 * open_bins_count as f64 * (bin_residual - post_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 500.0;
        } else {
            score -= 150.0 / (gap as f64).sqrt();
        }
        // Penalize if next item cannot fit in the post-residual (dead end).
        if post_residual < next_item_size {
            score += 50.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual: prefer tighter (below-mean) bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 100.0 * progress;
    }

    // Slight penalty for wasting large residuals on small items.
    score += (item_size as f64) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 5.0; // roomy leftover is reusable
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 80.0;
    }

    // Reward tight fits generally (post_residual close to 0 relative to item).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits into post_residual, reward leaving that space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover can't host next item; mild penalty proportional to gap
        score += 3.0;
    }

    // Prefer bins whose residual is above mean (keep balanced bins usable).
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 6.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= item_size / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual that cannot fit even the smallest plausible item (or the lookahead item)
    // is "dead space" — penalize quadratically as it approaches the danger zone.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * (dead_threshold as f64) * 2.0;
    }

    // Progressive penalty for residuals that are small relative to typical item sizes,
    // even if not fully dead: superlinear blowup below ~1/4 of capacity.
    let quarter = bin_capacity as f64 / 4.0;
    if (post_residual as f64) < quarter {
        score += (quarter - post_residual as f64) * (quarter - post_residual as f64) / quarter;
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open bins pressure: when many bins are open, discourage spreading; favor filling
    // existing bins (especially this one) over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = 1.0 + progress;
    score += open_bins_count as f64 * 0.6 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward heavily (perfect chain); if next item barely misses, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit — make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.3;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a fresh bin is reasonable — soften the penalty.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates below the mean
    // (more filled-in bins get closed out first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual ----
    // Classify dead space by integer division against capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead space below the smallest plausible item is nearly unusable: heavy penalty.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual < quarter {
        // tiny residue: modulo-based penalty tiers
        let r = post_residual % 5;
        score += 40.0 + (r as f64) * 2.0;
    } else if post_residual < half {
        // mid residue: still usable for many item sizes; mild reward
        score -= 5.0;
        // reward residues that are multiples of common sizes (harmonic alignment)
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
    } else {
        // large residue: flexible bin, strong reward
        score -= 20.0;
    }

    // ---- Lookahead coupling: does the next item fit the post residual? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item chains into this bin: reward, scaled by how tight the chain is
        let tightness = (next_item_size as f64) / (pr + 1.0);
        score -= 15.0 + 10.0 * tightness;
    } else if next_item_size > 0 {
        // next item would strand this residual: penalize proportional to wasted space
        let waste = pr / cap;
        score += 12.0 * waste;
    }

    // ---- Last chance: only one bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when existing bins are fragmented
        // or this is a large item that would leave bad residue elsewhere.
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        let big_item = (item_size as f64) / cap > 0.6;
        let mut new_bin_score = 10.0;
        if fragmentation > 0.5 { new_bin_score -= 8.0; }
        if big_item { new_bin_score -= 6.0; }
        if open_bins_count == 0 { new_bin_score -= 20.0; }
        // early stream: prefer consolidating; late stream: open bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 5.0 * progress;
        score = score.min(new_bin_score + pr) + new_bin_score;
    }

    // ---- Mild pressure against bin proliferation ----
    score += (open_bins_count as f64) * 0.3;

    // ---- Small tie-break toward tighter fits ----
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to how badly it misses
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Penalize tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than average residual (fill crowded bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight bias toward opening new bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fits are golden.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect dead space
    }

    // Modulo classes: residuals that are "harmonic" divisors of capacity
    // (multiples of 25 or 50) leave room for standard-sized future items.
    let r = post_residual;
    if r % 50 == 0 {
        score -= 60.0;
    } else if r % 25 == 0 {
        score -= 35.0;
    } else if r % 10 == 0 {
        score -= 15.0;
    }

    // Penalize awkward tiny leftovers (non-harmonic dead space)
    if r > 0 && r < 20 && r % 10 != 0 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits exactly or harmonically
            if next_item_size == r {
                score -= 300.0;
            } else if r % next_item_size == 0 {
                score -= 120.0;
            } else {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; residual becomes dead space
            score += (next_item_size - r) as f64 * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless post residual would be very wasteful.
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual > bin_capacity / 2 {
            score += 50.0; // don't burn the last bin for a bad fit
        }
    }

    // Prefer fuller bins overall (tightest-fit bias beyond raw residual)
    score -= (item_size as f64 / cap) * 25.0;

    // Slight preference for consolidating into existing bins as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 - (open_bins_count as f64) * 0.1;

    // New-bin candidate: make empty bin mildly unattractive unless
    // residual-based logic above already favors it (handled by baseline).
    if bin_residual == bin_capacity {
        score += 30.0;
        // but attractive late in stream when open bins are fragmented
        if mean_residual < item_size as f64 * 1.2 {
            score -= 70.0;
        }
    }

    score
}

