    // Dead-space penalty: small unusable gaps (1..=12) are toxic.
    if post_residual >= 1 && post_residual <= 12 {
        score += 30.0 * (13.0 - post_residual as f64);
    }
    // Sweet spot: post_residual large enough to host typical small items.
    if post_residual >= 20 && post_residual <= 45 {
        score -= 8.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score -= 35.0 * desperation;
        // Late in stream, prefer reusing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item could use this bin's post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth interaction: residual usefulness decays polynomially with stream progress
    score -= 12.0 * (1.0 - progress) * (pr_norm * (1.0 - pr_norm)) * cap;

    // Penalize dead space that nothing can fill (next item too large or none)
    if next_item_size == 0 {
        score += 4.0 * pr_norm * cap;
    } else {
        let nxt = next_item_size as f64;
        let fits_next = if nxt <= pr { 1.0 } else { 0.0 };
        // smooth reward for leaving room close to the next item size
        let gap = ((pr - nxt).abs()) / cap;
        score -= 10.0 * fits_next * (1.0 - gap) * (1.0 - progress);
        score += 6.0 * (1.0 - fits_next) * pr_norm;
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - pr_norm);

    // Prefer bins near the mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) via non-linear dead-space penalty.
    let frag = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += 40.0 * frag;

    // 2-step lookahead: reward when the next item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fill the bin exactly
        } else if post_residual >= next_item_size {
            // next item fits here: reward, stronger the tighter the two-item fit
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize wasted residual
            score += 8.0 + 0.15 * gap;
        }
    } else {
        // Last item: only tightness matters
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tight bin) preserves slack elsewhere; reward that.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: open a fresh bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64
            || (next_item_size > 0 && post_residual < next_item_size as f64);
        if poor_fit && fitting_bins_count > 0 {
            score -= 45.0; // opening a new bin beats wasting space in a good bin
        } else if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        } else {
            score += 30.0; // an open bin fits acceptably: prefer it
        }
    }

    // Slight preference to fill older/crowded state as stream progresses.
    score += 0.01 * (open_bins_count as f64) - 0.002 * (step_index as f64);

    score
}

