        // reward closeness of post_residual to next_item_size
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));

        // exact match: near-zero dead space after the next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // next item can't fit here but fits tightly elsewhere considerations:
        if next_item_size > post_residual {
            // penalize leaving space too small for the lookahead item
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // last item: prefer minimal residual
        score -= 20.0;
    }

    // Compare against mean residual: placing into bins below-mean residual is efficient
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual).signum() * ((pr - mean_residual).abs() * 0.15);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + (fitting_bins_count as f64) * 3.0;
    }

    // Late in stream: consolidate, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling the bin deeply (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead-space penalty: residual that is very small but nonzero is wasted space
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild reward scaled by fit quality
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 10.0 * next_tight;
        } else {
            // next item would not fit here: penalize slightly, worse if gap is small
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 4.0;
            }
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base reluctance to open new bins grows with number of open bins
        score += 30.0 + 2.5 * open_bins_count as f64;
        // But if current bin fit is poor (large post residual), opening a fresh bin
        // becomes more attractive, especially late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual > 40 {
            score -= (post_residual as f64 - 40.0) * (0.6 + 0.6 * progress);
        }
        // If many bins fit, discourage new bin; if few fit, allow it more readily
        if fitting_bins_count > 2 {
            score += 15.0;
        } else if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Global state coupling: prefer bins whose residual is above mean (keep
    // fragmented bins for small future items), penalize below-mean bins
    let residual_f = bin_residual as f64;
    let diff = residual_f - mean_residual;
    score += 0.08 * diff;

    // Mild preference for using fuller bins early (best-fit style) modulated by time
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - tightness) * 8.0 * (1.0 - progress);

    // Prefer keeping at least one very roomy bin alive for large future items
    if residual_f > 70.0 && !is_new_bin {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: penalize wasted post-residual with a smooth non-linear (quadratic-cubic) coupling
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * cap
        - 20.0 * norm_pr * norm_pr * norm_pr * cap;

    // Stream-progress coupling: early in the stream, waste is more tolerable (favor flexibility);
    // later, strongly punish residual waste since remaining opportunity shrinks.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * 30.0 * norm_pr * norm_pr * cap;

    // Perfect / near-perfect fit reward, smoothly scaled
    let fit_quality = 1.0 - norm_pr;
    score -= 35.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 30.0 * t;
    }

    // Lookahead: if next item fits into post_residual, reward this placement (chaining)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - t * 0.5);
        } else {
            // Next item won't chain here; penalize large dead space mildly more
            score += 10.0 * norm_pr * (1.0 + t);
        }
    }

    // New-bin candidate: prefer it when open bins are tight / mean residual low,
    // penalize it when existing bins could absorb the item well.
    if is_new_bin {
        let mean_norm = mean_residual / cap;
        score += 15.0 - 40.0 * mean_norm * (1.0 + t) + 20.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    } else {
        // Favor bins whose residual is above mean (use the loosest bins first)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 10.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fits are golden.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect dead space
    }

    // Modulo classes: residuals that are "harmonic" divisors of capacity
    // (multiples of 25 or 50) leave room for standard-sized future items.
    let r = post_residual;
    if r % 50 == 0 {
        score -= 60.0;
    } else if r % 25 == 0 {
        score -= 35.0;
    } else if r % 10 == 0 {
        score -= 15.0;
    }

    // Penalize awkward tiny leftovers (non-harmonic dead space)
    if r > 0 && r < 20 && r % 10 != 0 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item fits exactly or harmonically
            if next_item_size == r {
                score -= 300.0;
            } else if r % next_item_size == 0 {
                score -= 120.0;
            } else {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; residual becomes dead space
            score += (next_item_size - r) as f64 * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // unless post residual would be very wasteful.
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual > bin_capacity / 2 {
            score += 50.0; // don't burn the last bin for a bad fit
        }
    }

    // Prefer fuller bins overall (tightest-fit bias beyond raw residual)
    score -= (item_size as f64 / cap) * 25.0;

    // Slight preference for consolidating into existing bins as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 - (open_bins_count as f64) * 0.1;

    // New-bin candidate: make empty bin mildly unattractive unless
    // residual-based logic above already favors it (handled by baseline).
    if bin_residual == bin_capacity {
        score += 30.0;
        // but attractive late in stream when open bins are fragmented
        if mean_residual < item_size as f64 * 1.2 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual > 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }
    // Penalize leaving a gap that next item almost fits (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate handling: make empty bin less attractive unless it enables a large item.
    if bin_residual == bin_capacity {
        score += 40.0 - item_size as f64 * 0.4;
    }

    // Progress: early in stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mean residual coupling: if mean residual is large, discourage wasting space.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 15.0 * (miss / bin_capacity as f64).min(1.0);
    }

    // Dead space penalty: tiny residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect closure of the bin
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Discard brand-new empty bins unless existing bins are hopeless fits.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * (post_residual as f64);
    }

    // Early in stream: be slightly greedy toward filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that can't fit the next item's likely needs.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 18.0 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly usable by the lookahead item.
            score -= 10.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: penalize opening new bins when good fits exist,
    // but allow it when post-residual would be highly reusable.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 - 20.0 * progress; // cheaper to open bins early
        if next_item_size > 0 && next_item_size >= item_size {
