        }
    }

    // Slightly favor bins below the mean residual (consolidating fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild pressure to use many-open-bin situations efficiently.
    score -= 0.01 * open_bins_count as f64 * (bin_residual - post_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Dead-space penalty: residuals too small to hold the smallest plausible item are wasted
    let dead = ((16.0 - post) / 16.0).max(0.0);
    score += 25.0 * dead * dead;

    // Stream progress coupling: as the stream advances, tighten selection (favor small post_residual more)
    score -= 10.0 * progress * norm_post * (1.0 - norm_post);

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * (1.0 - progress);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: penalize spreading residual thin; prefer consolidating into fuller bins
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 6.0 * openness * norm_post;

    // Mean residual context: if this bin's residual is far below mean, it's a good consolidation target
    let dev = (mean_residual - post) / cap;
    score -= 3.0 * dev.max(0.0);

    // New-bin candidate adjustment: make empty bins less attractive unless current fit is poor
    if bin_residual == bin_capacity {
        score += 4.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

