    score += (post_residual as f64 / cap) * 30.0;

    // Harmonic class logic: residuals divisible by common item sizes are reusable.
    // Treat post_residual classes modulo 5 and 10: multiples of 10 are "harmonic".
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // perfectly harmonic residual, likely reusable
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 4.0; // awkward class
        }
        // Small odd residuals are dead space
        if pr < 10 {
            score += 15.0;
        } else if pr < 20 {
            score += 5.0;
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward if next item would leave another harmonic residual
            let next_pr = pr - next_item_size;
            if next_pr % 10 == 0 || next_pr == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 6.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
