        // Reward residuals that exactly accommodate the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // Mild reward for residuals in the "useful small" band (<= ~30).
        if post_residual <= 30 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: prefer opening a new bin only when the stream
    // is early or the fit into existing bins is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in the stream: fresh bins are cheap (exploration).
        score -= 30.0 * (1.0 - progress).min(1.0);
        // Late in the stream: discourage wasting bins.
        score += 25.0 * progress;
        // If many bins are open and mean residual is large, prefer reusing.
        score += 0.25 * open_bins_count as f64 + 0.4 * mean_residual.max(0.0);
        // A big item into an empty bin is fine (full bin utilization later).
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger items (less waste per unit placed).
    score -= 0.1 * item_size as f64;

    // Slight preference for bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    // Time-horizon modulation: as the stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = pr / cap;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    let mut score = pr * (0.5 + 0.9 * progress) + 12.0 * poly * (0.3 + progress);

    // Reward tight fits more strongly as the stream progresses.
    score -= 30.0 * fill * fill * (0.4 + progress);

    // Penalize dead space: post_residual that can't fit the lookahead item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // Reward leaving space that exactly or nearly fits the next item.
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 4.0;

    // Slight preference for bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: keep it neutral-to-slightly-costly, cheaper only late.
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.6 * progress) + 5.0 - 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual is an exact harmonic division of capacity (50, 25, 20, 10)
    // these leftovers are "reusable" classes -> reward (subtract)
    let harmonics = [50u32, 25, 20, 10, 5];
    for h in harmonics.iter() {
        if post_residual == *h {
            score -= 12.0;
        } else if post_residual % h == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item (<= 9)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Integer division threshold: post_residual / 25 quartile classes
    let quartile = post_residual / 25; // 0..4
    match quartile {
        0 => score += 8.0,   // tiny leftover, near-full bin is good actually -> mild penalty removed
        1 => score -= 2.0,   // 25-49 leftover
        2 => score -= 5.0,   // 50-74 leftover, very reusable
        3 => score -= 4.0,   // 75-99 leftover (only when item tiny)
        _ => {}              // new bin case
    }

    // Modulo coupling between post_residual and next_item_size:
    // if next item fits exactly or leaves another harmonic, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 20.0; // perfect two-item fill
            } else if next_post % 10 == 0 {
                score -= 10.0; // decadal leftover, highly reusable
            } else if next_post < 10 {
                score += 5.0;  // next item creates dead space
            } else {
                score -= 1.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for blocking
            score += 2.0;
        }
    } else {
        // last item: just fill fullest bin
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should lose unless leftovers of open bins are bad
    if bin_residual == bin_capacity {
        // neutral-ish baseline: penalize opening new bins early, allow later
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress;
        // allow new bin if mean residual of open bins is tiny (all nearly full)
        if mean_residual < 12.0 {
            score -= 25.0;
        }
        // opening a bin sized well for the next item
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 8.0;
        }
    } else {
        // reward tight fits in existing bins (small post_residual relative to item)
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 10.0 * tightness;
    }

    // Prefer consolidating into fewer bins when many are open with slack
    if open_bins_count > 3 && mean_residual > (item_size as f64) * 1.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post-residual gap is "dead" if it is too small to fit even the
    // smallest plausible item, or too small for the lookahead item.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit: extremely desirable
    } else if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0); // near-dead sliver
    }

    // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward gaps that exactly accommodate the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Reward tight fits: smaller post_residual relative to item size.
    score += 0.5 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: when many bins are open, favor consolidation
    // (filling existing bins) over spreading; when few bins are open,
    // opening a new bin is cheaper.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped"; finishing it off is good.
    let deviation = mean_residual - bin_residual as f64;
    score += 0.1 * deviation;

    // Late-stream consolidation: as the stream progresses, penalize new
    // empty-bin usage more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress; // make new-bin candidate less attractive
        // But allow new bin if no open bin can give a decent fit.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills the leftover space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits in the leftover space: good 2-step chaining.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    }
    // Next item would NOT fit here: leftover is dead space unless tiny.
    else if next_item_size > 0 {
        score += 10.0 + (post_residual.min(next_item_size) as f64) * 0.1;
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize leaving residual far below the mean (fragmenting small holes).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when the item is large
    // and would leave an awkward remainder in an existing bin.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score -= awkward * 30.0 + fill_ratio * 20.0;
        // Slight bias against hoarding bins early in the stream.
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver: wasted bin space
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.05 * post_residual as f64;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: check whether next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chainable placement is good
        } else {
            // Penalize leaving residual that neither fits next item nor is useful
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is a fallback.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; discourage when a decent fit exists.
        score += 20.0;
        // But a fresh bin is attractive if current bin would leave bad residue
        // and the item is large (better in a fresh bin).
        if item_size >= 50 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state: spread load when many bins are open with high mean residual.
    if open_bins_count > 0 {
        let load_pressure = mean_residual / bin_capacity as f64;
        // Prefer bins below the mean residual (tighter bins) mildly.
        score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        // When mean residual is high, encourage consolidation into open bins.
        score -= 3.0 * load_pressure * fit_ratio;
    }

    // Time horizon: early stream, be flexible (keep residuals large);
    // late stream, prioritize filling bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;
    score -= progress * 0.20 * (bin_residual as f64 - post_residual as f64);

    // Small tie-break noise-free deterministic jitter via step parity.
    if step_index % 2 == 0 {
        score -= 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, weighted by smooth polynomial in progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress));

    // Non-linear penalty on very small post-residuals (dead space), amplified with progress
    let dead = (1.0 - norm_pr).powi(3);
    score += dead * (20.0 + 30.0 * progress);

    // Smooth coupling: quadratic interaction of post_residual with mean residual deviation
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Reward tight fits smoothly: cubic reward for small normalized post residual
    score -= 25.0 * (1.0 - norm_pr).powi(2) * (norm_pr + 0.1).exp();

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post residual (smooth decay)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let gap = if fits_next { 0.0 } else { (next_item_size as f64 - pr) / cap };
        score += 30.0 * gap * (1.0 - progress);
        if fits_next {
            score -= 10.0 * (1.0 - norm_pr);
        }
    }

    // Mild preference for consolidating into fewer bins early
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into coarse "waste bands". Leftovers in the lowest
    // band (0..=9) are nearly perfect fits and deserve strong reward.
    let leftover_class = post_residual / 10; // 0..=10 (capacity 100)
    score -= match leftover_class {
        0 => 40.0,                 // near-perfect fill
        1 => 18.0,                 // small usable remainder
        2 => 8.0,                  // medium remainder
        3 => 2.0,                  // moderate remainder
        _ => 0.0,                  // large remainder: no bonus
    };

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common small item sizes (10, 20, 25, 50) remain reusable by future
    // items. Reward exact divisibility.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Pairing logic with lookahead: if the next item fits exactly into the
    // post_residual, this bin is ideal (two items -> perfect closure).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another remainder: mild reward,
            // scaled by how small the chain-remainder is.
            let chain = post_residual - next_item_size;
            score -= (12.0 - (chain as f64) * 0.15).max(0.0);
        } else {
            // Next item cannot use this leftover: penalize proportional to
            // how much dead space is stranded relative to next item's need.
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    } else {
        // Last item of the stream: minimize leftover hard.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large and current leftovers are poor. Penalize opening a
    // new bin unless the item is big (harmonic class of item itself).
    if bin_residual == bin_capacity {
        let item_class = item_size / 10;
        // Large items (>=70) justify fresh bins; small items should use scraps.
        let base_penalty = 55.0 - (item_class as f64) * 4.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += base_penalty + mean_residual * 0.25;
        // Early in the stream, having few bins, fresh bins are cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // If no open bin can fit the item, new bin is forced-ish: soften.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight tie-breaker: prefer bins whose residual deviates favorably
    // from the mean (small residuals are precious, use them first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but strongly punish
    // "unusable" dead space: small gaps that likely cannot host future items.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 30 };
    if post_residual > 0 && post_residual < dead_threshold {
        // Dead space: gap too small for the lookahead item -> heavy penalty.
        let severity = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 40.0 + 60.0 * severity;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward filling a bin nearly completely (residual <= 10 is nearly dead anyway).
    if post_residual <= 10 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item could exactly use the leftover, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement -> this bin becomes dead weight.
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins; stronger early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * (1.0 - progress));

    // New-bin candidate handling: an empty bin is attractive only when the current
    // bin's fit is bad. Penalize the new bin mildly so tight fits into open bins win,
    // but not so much that dead-space placements beat it.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    } else {
        // Slight preference for bins already deviating from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the lookahead item exactly or nearly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a hole relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    } else {
        // Last item: prefer tightest fit, small residuals fine.
        score -= 5.0;
    }

    // Penalize dead space that is too small to ever be useful (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (compact fuller bins) mildly.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in stream, be more greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; favor filling existing ones.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residual that can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + slack);
        } else {
            // Dead space relative to next item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.35;
        }
    } else {
        // Last item: prefer minimal waste overall.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Slightly discourage opening new bins early; allow later when fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * pressure * (1.0 - 0.5 * progress);
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    }

    // Prefer filling bins below the current mean residual (balance / consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Mild bonus for using many open bins efficiently as stream grows.
    if open_bins_count > 4 {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear sharpening
    let mut score = pr as f64;
    score += 30.0 * x * (1.0 - x) * (1.0 - x); // penalize mid-range slack (dead space)
    score -= 25.0 * x * x * x; // reward very tight fits non-linearly

    // Stream progress coupling: early on, be more tolerant of slack (future items may use it);
    // late in the stream, tighten up aggressively.
    let progress_tighten = 1.0 + 0.6 * progress * progress;
    score *= progress_tighten;

    // Interaction: post residual vs mean residual — avoid leaving slack below the mean
    // when the bin is already tighter than average (good packing), reward it.
    let mean_norm = mean_residual / cap;
    let coupling = (x - mean_norm) * (x - mean_norm);
    score += 20.0 * coupling * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement;
    // if next item nearly fits but doesn't, penalize leaving awkward slack.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr as f64 {
            score -= 15.0 * (1.0 - ni / cap);
        } else if ni <= pr as f64 + 10.0 {
            score += 12.0 * (ni - pr as f64);
        }
    }

    // Mild penalty on bin proliferation: discourage opening many bins early
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate handling: empty bin gets a moderate penalty so it's only
    // chosen when open bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) + 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    // Dead-space classes: residuals that few item sizes (1..=100) can exactly fill
    // class 0: pr == 0 (perfect fit) -> strong reward
    if pr == 0 {
        score -= 60.0;
    } else {
        // Usability: number of item sizes in 1..=100 that fit exactly into pr is 1 (pr itself)
        // but practical usability ~ how divisible pr is by common sizes.
        let mut divis = 0u32;
        for d in [2u32, 4, 5, 8, 10, 20, 25, 50] {
            if pr % d == 0 {
                divis += 1;
            }
        }
        score -= 4.0 * divis as f64;

        // Penalize awkward small residuals: pr in (0,10) is nearly dead space
        if pr < 10 {
            score += 25.0 * (10.0 - pr as f64);
        } else if pr <= 15 {
            score += 8.0;
        }

        // Harmonic threshold classes via integer division of post_residual
        let cls = pr / 12; // harmonic bucket of 12
        score += match cls {
            0 => 10.0,             // 0..11: nearly dead
            1 => 4.0,              // 12..23
            2 => 0.0,              // 24..35: sweet zone
            3 => -2.0,             // 36..47
            4 => -4.0,             // 48..59
            5 => -3.0,             // 60..71
            6 => -1.0,             // 72..83
            _ => 0.0,
        };
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // reward proportionally, extra if leaves another harmonic residual
            let pr2 = pr - next_item_size;
            score -= 10.0;
            if pr2 % 10 == 0 || pr2 % 25 == 0 {
                score -= 8.0;
            }
            if pr2 < 10 && pr2 > 0 {
                score += 12.0; // would create dead space for next
            }
        } else {
            // next item cannot fit here: mild penalty for this bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive for huge items or late stream with tight bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = cap - item_size as f64;
        // base penalty so we prefer existing bins generally
        score = waste + 15.0;
        if item_size >= 60 {
            score -= 25.0; // big items deserve fresh bins
        }
        if progress > 0.7 && open_bins_count > 6 {
            score -= 10.0 * progress;
        }
        // if mean residual across open bins is small, opening new bin is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // prefer tighter existing bins slightly more when many bins are open
        score += open_bins_count as f64 * 0.05;
    }

    // Slight tie-break toward bins whose residual is close to item (tight fit)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Zero residual (perfect fit) is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_tightness;

    // Penalize leaving a gap that the lookahead item could still use wastefully large.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap unusable by next item -> mild extra penalty (likely dead space)
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        // gap will become dead space after next item placement
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 20.0 + pressure;
    } else {
        score -= pressure.min(15.0);
    }

    // Prefer bins whose residual deviates from the mean residual (keeps diversity of gap sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // reward proportional to how tight the chained fit is
            score -= 25.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize wasted space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for leaving very small unusable slivers (< 10).
    if post_residual < 10 {
        score += 12.0;
    }

    // Late in stream: prefer tighter packing, discourage new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (0.5 + 0.5 * progress); // penalize new-bin candidate
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    score -= 0.6 * (1.0 - (post_residual as f64) / cap) * (item_size as f64 / cap);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            score += 0.5 * (post_residual as f64 / cap) * (next_item_size as f64 / cap);
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 6.0;
        // Cheaper to open a bin early in the stream or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 2.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.05 * mean_residual.max(0.0);
        // If next item is large and this new bin would be empty, opening is attractive.
        if next_item_size >= item_size && item_size > bin_capacity / 2 {
            score -= 1.5;
        }
    }

    // Prefer filling more-utilized bins (larger item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 1.5 * fill_ratio.min(1.0);

    // Mild preference for bins with below-average residual (consolidate emptier space usage).
    score += 0.02 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize post-residual relative to capacity
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space cost grows quadratically/cubically
    // as it shrinks below the typical item size, and amplifies with stream progress.
    let dead = (pr * pr) * (1.0 + 2.0 * progress);
    score += dead * (bin_capacity as f64) * 0.5;

    // Cubic term: strongly penalize leaving residual that is too small to be useful
    // (below the minimum item size), scaled smoothly by progress.
    let min_item = 1.0f64;
    let useless = (min_item - pr).max(0.0);
    score += useless * useless * useless * (bin_capacity as f64) * 0.25;

    // Reward tight fits: subtract when post_residual is small but non-negative,
    // with a smooth bell-shaped preference around small residuals.
    let tightness = (1.0 - pr).max(0.0);
    score -= tightness * tightness * (bin_capacity as f64) * 0.6;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (smooth polynomial interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt) / bin_capacity as f64;
        if gap >= 0.0 {
            score -= (1.0 - gap) * (1.0 - gap) * (bin_capacity as f64) * 0.35;
        } else {
            // Next item won't fit here; mild penalty growing with the shortfall
            score += (-gap) * (bin_capacity as f64) * 0.1;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin (subtract to favor using it), scaled by progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Penalize the fresh bin smoothly, less as mean residual
    // across open bins grows (their space is fragmented/less usable).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).min(1.0);
        // Base penalty that decays quadratically as open bins become fragmented
        let penalty = 25.0 * (1.0 - fragmentation) * (1.0 - fragmentation);
        score += penalty + open_bins_count as f64 * 0.5;
        // If no open bin fits at all, the new bin is the only option
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild preference to fill bins with larger residuals early on (best-fit
    // counterbalance), smoothly transitioning to tightest-fit as stream ends.
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small divisors) are favored, since future
    // items drawn from a wide range more likely fit round remainders.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -30.0 // perfect fit: excellent
    } else if pr % 10 == 0 {
        -8.0 // round residual, highly reusable
    } else if pr % 5 == 0 {
        -3.0
    } else {
        // penalize awkward remainders; the smaller the class, the worse
        let r = pr % 10;
        (10 - r.min(10 - r)) as f64 * 0.6
    };
    score += class_penalty;

    // Integer-division threshold: residual in [1..=9] is near-dead space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward, scaled by how snugly it fits
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + slack * 0.05;
        } else {
            // next item won't fit: penalize proportionally to overshoot class
            let over = next_item_size - pr;
            score += (over % 20) as f64 * 0.25 + 2.0;
        }
    } else {
        // last item: prefer zero-waste finish
        score += pr as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin is
    // costly; strongly prefer using it unless residual is truly unusable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has perfect round residual,
    // but discourage it when good open bins exist (keep bin count low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread = (mean_residual - (cap - item_size as f64)).abs();
        score += 20.0 + spread * 0.1 + open_bins_count as f64 * 1.5 - progress * 5.0;
    }

    // Mean-residual drift: prefer bins close to the mean (balanced packing),
    // with a modulo-flavored tilt toward residual classes near mean/10 blocks.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;
    let block = (post_residual / 10) as f64;
    score -= block * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small gaps are semi-useless; graded penalty.
        score += 12.0 + (20 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + fit_ratio);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space coupling: penalize if the leftover gap cannot hold the
    // lookahead item (wasting the next opportunity in this bin).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the
    // current bin would leave a truly unusable gap.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to mean residual, a fresh bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (-slack / 20.0).exp(); // decaying bonus for near-match
        } else {
            // next item cannot fit here; penalize dead space that will be stranded
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong penalty for wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 10.0;
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer closing bins tightly over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if no good fit exists
        score += 45.0 * (1.0 - progress) + 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.95;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but with non-linear polynomial shaping over progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth cubic coupling: later in the stream, small residuals become more costly (dead space)
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (0.3 + 0.7 * progress);

    // Penalize near-full waste quadratically as stream progresses
    score += 20.0 * norm_pr * norm_pr * progress;

    // Last-chance bonus: if this is the only fitting bin, reward strongly
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 30.0 * fit_quality * fit_quality;
    }

    // Mild penalty when bin residual deviates from mean residual (keep diversity of residuals)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: penalize opening a new bin mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln();
    }

    // Small tie-breaker: prefer tighter fits
    score += 0.01 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into buckets
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes: 0..10

    // Reward tight fits: lower class => better
    score -= (10 - class.min(10)) as f64 * 6.0;

    // Perfect fit bonus
    if pr == 0 {
        score -= 50.0;
    }

    // Dead space penalty: residuals that are small but unusable (1..=5)
    if pr >= 1 && pr <= 5 {
        score += 40.0;
    }

    // Harmonic coupling with next item: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual; evaluate chained fit
            let chained = pr - next_item_size;
            if chained <= 5 {
                score += 15.0; // creates dead space after next
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; residual becomes potential dead space
            score += (pr as f64) * 0.3;
        }
    }

    // Modulo arithmetic on post_residual vs common item sizes (harmonic alignment)
    let harmony = [10u32, 20, 25, 50];
    let mut aligned = false;
    for h in harmony.iter() {
        if pr % h == 0 && pr > 0 {
            aligned = true;
        }
    }
    if aligned {
        score -= 8.0; // residual divisible by common sizes => likely reusable
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.6 + item_size as f64;
        // prefer new bin late in stream when open bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // new bin can chain next item too, mild bonus
        }
    }

    // Prefer bins whose residual is below mean (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual below the smallest possible item
    // (assumed ~1, but practically below typical item sizes) is wasted space.
    let dead_threshold: u32 = 10; // min item size from the classic regime
    if post_residual > 0 && post_residual < dead_threshold {
        // Fully dead gap: heavy penalty proportional to how much capacity is locked.
        score += 60.0 + 0.5 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Usable residual: mild reward for tightness, scaled by how usable the gap is.
        let usable = (post_residual as f64) / bin_capacity as f64;
        score -= 5.0 * (1.0 - usable);
    }

    // Lookahead: if the next item can fit in the post residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if the next item would leave another near-perfect fit.
        let next_post = post_residual - next_item_size;
        if next_post <= 2 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host the next item: mild penalty for creating awkward residue.
        score += 5.0;
    }

    // Open-bins pressure: discourage scattering across many bins when alternatives exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already the "worst" bin; prefer filling it rather than a roomy one.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 3.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < dead_threshold && post_residual > 0 {
            score += 30.0; // but not if it creates dead space
        }
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward (subtract) when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if post_residual is positive but too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Mild reward if post_residual can still hold the next item (keeps chain alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Perfect fit bonus (no waste at all).
    if post_residual == 0 {
        score -= 80.0;
    }
    // Penalize tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer keeping few open bins (consolidation) early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New empty bin candidate: penalize slightly so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item leaves a huge residual that fits the next item well, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize very small dead space less if it is truly tiny (perfect fit), more if awkward mid-range waste
    let waste = post_residual as f64;
    if waste == 0.0 {
        score -= 50.0; // perfect fit, strongly favored
    } else if waste < 10.0 {
        score -= 20.0; // near-perfect fit
    } else if waste > 40.0 {
        // large leftover is good if another item can use it
        score -= 5.0;
    } else {
        // awkward mid-range dead space
        score += 10.0 + waste * 0.3;
    }

    // Lookahead: reward if the next item fits into the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item chains nicely into this bin
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 + slack_after_next * 0.1;
        } else {
            // next item won't fit here; mild penalty for leaving stranded space
            score += 5.0;
        }
    } else {
        // last item of the stream: minimize leftover, any residual is pure waste
        score += waste * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling bins that are already mostly full (low residual before placement)
    score += (bin_residual as f64) * 0.15;

    // Global pressure: many open bins -> consolidate into existing bins
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Mean residual coupling: if this bin is much emptier than average, mildly deprioritize
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    // New empty bin candidate: neutral baseline, chosen only when all fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; grows with progress (late bins are expensive)
        score = (bin_capacity - item_size) as f64 + 30.0 + 40.0 * progress + open_bins_count as f64 * 0.3;
        // but if the item is large, opening a fresh bin is more attractive
        score -= (item_size as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), with quadratic sharpening.
    let mut score = post + 25.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in the stream, demand tighter fits more strongly.
    score *= 1.0 + 0.8 * progress * (1.0 - norm_post);

    // Penalize bins whose residual deviates from the mean (fragmentation signal).
    score += 0.35 * (post - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 12.0 * (post / cap) * (1.0 - next / cap);
        } else {
            score += 6.0 * (next - post) / cap;
        }
    }

    // Mild penalty for proliferating open bins when a tight fit is available elsewhere.
    score += 0.4 * open_bins_count as f64 * norm_post;

    // Brand-new bin candidate: neutral-ish score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 10.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    // Residuals in the lowest band (0..=10) are near-perfect fits -> strong reward.
    // Residuals in awkward bands (11..=19) are classic dead space -> strong penalty.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 19 {
        score += 30.0; // dead-space band: unusable by most items (min size 1..100)
    } else if pr <= 30 {
        score += 8.0;
    }

    // Harmonic bonus: post_residual divisible into large chunks by the next item
    // (lookahead harmony). If next item fits exactly or with tiny waste, reward.
    if next_item_size > 0 && pr >= next_item_size {
        let waste = pr - next_item_size;
        if waste == 0 {
            score -= 35.0;
        } else if waste <= 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual at all: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.4;
    }

    // Integer-division class of the fill ratio: item_size / capacity bands.
    let fill_class = (item_size * 4) / bin_capacity; // 0..3
    match fill_class {
        3 => score -= 10.0, // huge item: place it anywhere it fits
        2 => score -= 4.0,
        _ => {} // small items should prefer tight residuals, handled above
    }

    // Last-chance bin: if this is the only fitting bin, heavily reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit,
    // i.e. when mean residual is large but this bin (empty) gives full room.
    if bin_residual == bin_capacity {
        // Base penalty so new bins lose to reasonable fits...
        score += 55.0;
        // ...but discount when open bins are crowded or residuals are small.
        score -= (mean_residual - (bin_capacity as f64) * 0.5).max(0.0) * 0.9;
        if fitting_bins_count == 0 {
            score -= 70.0; // nothing fits elsewhere: must open
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fit = fitting_bins_count as f64;

    let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let open_pressure = open.sqrt().min(10.0);
    let is_new_bin = bin_residual == bin_capacity;
    let new_post = (cap - item).max(0.0);
    let new_bin_can_take_next = next > 0.0 && new_post + 0.5 >= next;

    let mut score = post + 0.02 * (residual - mean_res).clamp(-cap, cap);

    if post == 0.0 {
        score -= 30.0 + 4.0 * open_pressure + 15.0 * (1.0 - progress);
    } else {
        if post < 0.05 * cap {
            score += 3.0 * (0.05 * cap - post);
        }

        if next > 0.0 && post < next {
            let deadness = ((cap - post) / cap).clamp(0.0, 1.0);
            let mut dead_penalty = (2.0 * cap - post) * deadness * deadness;

            if new_bin_can_take_next {
                dead_penalty *= 1.25;
            }

            score += dead_penalty;
        } else if next > 0.0 {
            if (post - next).abs() < 0.5 {
                score -= 10.0 + 2.0 * open_pressure + 10.0 * (1.0 - progress);
            } else {
                score -= 0.05 * next;
            }
        }
    }

    if is_new_bin {
        if fit > 0.5 {
            score += 0.35 * cap
                + 0.20 * cap * progress
                + 2.0 * open_pressure
                + 0.10 * item
                + 2.0 * (fit - 1.0).min(8.0)
                + 0.05 * mean_res;
        } else {
            score -= cap;
        }
    } else {
        let mut open_bonus = 0.3 * open_pressure + 0.5 * open_pressure * progress;

        if fit < 1.5 {
            let usability = if next > 0.0 && post < next {
                (post / next).clamp(0.0, 1.0)
            } else {
                1.0
            };

            open_bonus += (8.0 + 6.0 * progress) * usability;
        }

        score -= open_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size && next_item_size > 0 {
            // Great: this placement chains a second item into this bin.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot reuse this bin's leftover: penalize dead space.
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // Extra penalty if the leftover is small and unusable (dead space).
            if post_residual < 10 {
                score += 15.0;
            }
            // If next item would fit perfectly in a fresh bin, prefer opening one.
            if bin_residual == bin_capacity && next_item_size == item_size {
                score -= 8.0;
            }
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it neutral-ish but slightly favored when current
    // bins would leave large unusable leftovers.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 12.0;
    }

    // Penalize dead space: post_residual too small to ever be useful again
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful && post_residual > 0 {
        score += (min_useful - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, tight fits matter more than bin count
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Global state: many open bins with high mean residual -> discourage opening new bins
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 18.0 + pressure * 30.0 + (open_bins_count as f64).sqrt() * 4.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, new bin is fine
        }
    } else {
        // reward using bins whose residual is above average (balance load)
        let diff = bin_residual as f64 - mean_residual;
        score -= diff * 0.2;
    }

    // Slight preference for filling larger-residual bins when few fit options exist
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.6 * (pr / cap).powi(2));

    // Tight fits are strongly favored: quadratic bonus for small post_residual.
    score -= 12.0 * (1.0 - pr / cap).powi(2);

    // Perfect-fit reward (post_residual near zero), smooth cubic.
    score -= 20.0 * (1.0 - pr / cap).powi(3);

    // Last-chance bonus: only fitting bin => strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Penalize bins with residual far above mean (fragmentation hoarding).
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize wasting space, more so early on.
        score += 3.0 * (pr / cap) * (1.0 - progress);
    }

    // Stream progress coupling: later in stream, be more conservative (favor filling).
    score -= 4.0 * progress * (1.0 - pr / cap);

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space quadratically for small residuals (dead space).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dead = if pr < 10.0 { (10.0 - pr) * 6.0 } else { 0.0 };
        score += dead;
    }

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Residuals in "usable" harmonic classes (>= 25, i.e. quarter of capacity)
    // are rewarded; tiny fragments are penalized.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    if post_residual >= quarter {
        score -= 8.0;
    } else if post_residual >= fifth {
        score += 2.0;
    }

    // Modulo-class logic: residuals that are multiples of common small item
    // sizes (10/20/25/50) pair well with typical arrivals.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 3.0;
    }

    // Lookahead: perfect fit with next item is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 {
                score += 5.0; // would create fresh dead space
            } else if nxt_post % 10 == 0 {
                score -= 4.0;
            }
            // pair fit quality scaled by lookahead size class
            if next_item_size >= 50 {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 4.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Crowding pressure: with many open bins, prefer reusing bins (penalize new-bin
    // tendency indirectly by rewarding bins tighter than the mean).
    if (pr < mean_residual - 5.0) && post_residual > 0 {
        score -= 3.0;
    }
    if open_bins_count > 8 {
        score -= 2.0;
    }

    // Progress: early in the stream, be slightly more willing to leave room
    // (favor balanced residuals); late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Exact fit is the best possible outcome.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize candidate empty-bin opening unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 20.0 {
            score -= 20.0; // open bins nearly full: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are penalized heavily (non-linear blow-up).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Residuals in the "awkward" band [10, 25) waste space for mid-size items.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        // But if the dead space created is unusable AND the next item is big,
        // damp the bonus so a fresh bin may win.
        if next_item_size > 0 && post_residual > 0 && post_residual < (next_item_size as u32).min(10) {
            score += 40.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins; more open bins
    // -> stronger preference for filling existing ones (i.e., lower score
    // for real bins relative to a new empty bin).
    if bin_residual != bin_capacity {
        score -= 2.5 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize slightly more as open bins grow,
        // but give it an edge when mean residual across bins is small
        // (existing bins are nearly full anyway).
        score += 15.0 + 1.5 * open_bins_count as f64 - 0.1 * mean_residual;
    }

    // Lookahead: favor bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Stream progression: early on, be a bit more tolerant of spreading;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chaining of next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly fills this bin afterwards -> excellent.
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here; closer fit is better.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: penalize proportionally
            // to how badly it misses, unless post_residual is tiny (dead space).
            let miss = (next_item_size - post_residual) as f64;
            if post_residual > 0 && post_residual < 10 {
                score += 25.0; // creating unusable sliver
            } else {
                score += 5.0 + 0.2 * miss;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins with more residual (larger hole) when
    // post_residual stays usable; avoid wasting the tightest bins.
    if post_residual >= 10 {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score += 20.0; // dead space below min item size
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New empty bin candidate: neutral baseline, opened only when fits are poor.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // If other bins fit, opening new bin is usually worse.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    score += 0.01 * (step_index as f64 / total_items.max(1) as f64) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 0.6 * bin_capacity as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no future item (min size 1) can use badly:
    // small residuals are risky if they don't match the lookahead item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // cannot host the next item
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0; // perfect lookahead match
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins with slack: prefer filling existing bins rather than opening new ones.
    let slack_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when plenty of aggregate slack exists.
        score += slack_pressure * 12.0;
        // Reward opening a new bin early in the stream (investment for future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If the item fits poorly everywhere, new bin becomes attractive.
        if post_residual > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using it when aggregate slack is high.
        score -= slack_pressure * 4.0;
    }

    // Prefer bins whose residual is closest to the item size (best-fit flavor).
    let waste = (bin_residual - item_size) as f64;
    score += waste * waste / (bin_capacity as f64 * 4.0);

    // Time horizon: later in the stream, favor consolidation (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Mild penalty for very large item in nearly full bin leaving unusable sliver.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; later, penalize residual more strongly.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Perfect fit bonus (smooth quadratic decay around zero residual)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: reward residual that can still hold the next item,
    // with a smooth cubic interaction term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score += 12.0 * norm_pr * norm_pr * norm_pr;
        score -= 18.0 * fits_next * (1.0 - gap * gap);
    }

    // Last-chance bin bonus when few bins can fit this item.
    if fitting_bins_count <= 1 {
        score -= 20.0;
    }

    // Mean residual divergence penalty (smooth, quadratic).
    score += 0.15 * (mean_residual - pr) * (mean_residual - pr) / cap;

    // Congestion term: many open bins -> discourage spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division on 10
    let class = post_residual / 10;
    match class {
        0 => score += 25.0,          // dead space < 10: nearly unusable
        1 => score += 12.0,          // 10..19: only tiny items fit
        2 => score += 6.0,
        3 => score += 3.0,
        _ => score -= 2.0,           // large residual: flexible bin
    }

    // Reward exact/near-exact fits
    if post_residual == 0 { score -= 40.0; }
    else if post_residual <= 5 { score -= 20.0; }

    // Modulo arithmetic on residual: residuals that are multiples of common item sizes are reusable
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0) {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 { score -= 30.0; }
        else if slack <= 10 { score -= 10.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; residual becomes dead space for lookahead
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it neutral-ish unless current bin is bad
    if bin_residual == bin_capacity {
        // fresh bin: attractive early, less so when many open bins exist
        score = 30.0 + post_residual as f64 - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: late in stream, be more aggressive about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight preference for bins below mean residual (balance load)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item are nearly worthless — penalize them hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 40.0;
    }
    // General "awkward gap" penalty: gaps in the 1..=15 range are hard to fill.
    if post_residual <= 15 && post_residual > 0 {
        score += (16 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 10 {
        score -= (10 - post_residual) as f64 * 2.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few are open,
    // but encourage using existing bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the current item is large
    // and existing residuals are poor fits, or the next item is huge.
    if bin_residual == bin_capacity {
        let bad_existing = (mean_residual - item_size as f64).abs() > 25.0;
        let big_next = next_item_size >= 70;
        if bad_existing || big_next {
            score -= 20.0;
        } else {
            score += 35.0; // prefer existing bins for normal fits
        }
    }

    // Lookahead: if the next item fits exactly in this bin's post_residual,
    // reward this placement to enable a chain.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 15.0;
    }
    // If next item cannot fit anywhere (larger than post_residual of everything),
    // slightly favor compacting here.
    if next_item_size > bin_capacity - item_size.min(bin_capacity) {
        score += 0.0;
    }

    // Mild tie-break toward bins with residuals close to mean (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // post_residual too small for next item: penalize dead space
            score += (next_item_size as f64) * 0.3;
            if post_residual < 10 {
                score += 50.0; // tiny unusable gap
            }
        }
        // Bonus if post_residual is a tight fit for next item
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap <= 5.0 {
            score -= 120.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins driven below average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced if many bins open or late stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 - progress * 50.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // next item needs a fresh bin anyway
        }
    }

    // Slight preference for tighter bins early (best-fit bias)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor placements that leave little waste.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Penalize dead space relative to smallest possible future item (assume ~1).
    // Squared waste penalty: small residuals are fine, large ones are bad.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but reward proportional to how snugly
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by leftover size
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + mean_residual * 0.4;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 2 {
        score += mean_residual * (open_bins_count as f64).ln() * 0.3;
    }

    // Time horizon: early in stream, be conservative (favor good fits for future);
    // late in stream, just fill anything available.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Reward using bins with large residual when item is large (avoid stranding big items).
    if item_size > bin_capacity / 2 && bin_residual >= item_size {
        score -= (bin_residual as f64 - item_size as f64) * 0.2;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_norm = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Non-linear polynomial coupling: residual squared term penalizes large dead space
    score += 6.0 * residual_norm * residual_norm * cap;

    // Cubic interaction with stream progress: late in stream, dead space is costlier
    score += 10.0 * progress * residual_norm * residual_norm * residual_norm * cap;

    // Smooth coupling with mean residual: prefer bins whose residual deviates from mean
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + mean_residual);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 20.0 * (1.0 - residual_norm) * (1.0 - residual_norm);

    // Last-chance bin: smooth exponential reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - residual_norm);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 5.0 + 4.0 * (nxt - pr) / cap;
        } else {
            score -= 3.0 * (1.0 - ((pr - nxt) / cap));
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod 10 classes
    let class = post_residual % 10;
    // Reward leftovers that sit on "nice" harmonic classes (multiples of 10/5)
    if class == 0 {
        score -= 6.0;
    } else if class == 5 {
        score -= 3.0;
    } else if class >= 8 {
        score += 2.0; // near-full leftover, likely dead space unless tiny
    }

    // Dead space penalty: leftover too small for the smallest plausible item (1..100, min 10 historically)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item (or a harmonic fraction of it)?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual >= next_item_size / 2 {
            score -= 3.0;
        } else {
            score += 4.0; // leftover can't help the next item
        }
        // Harmonic pairing: leftover + next item forms a clean capacity fraction
        let combined = post_residual + next_item_size;
        if combined == bin_capacity {
            score -= 12.0;
        } else if combined % 25 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 20.0 - 10.0 * progress - crowd.min(15.0);
        // Big items prefer fresh bins
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 10.0;
    } else if fill_ratio < 0.3 {
        score += 3.0; // wasteful sprinkle into a large bin
    }

    // Prefer bins with below-average residual (compact usage)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual that cannot fit even the smallest plausible item (or the lookahead item)
    // is "dead space" — penalize quadratically as it approaches the danger zone.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * (dead_threshold as f64) * 2.0;
    }

    // Progressive penalty for residuals that are small relative to typical item sizes,
    // even if not fully dead: superlinear blowup below ~1/4 of capacity.
    let quarter = bin_capacity as f64 / 4.0;
    if (post_residual as f64) < quarter {
        score += (quarter - post_residual as f64) * (quarter - post_residual as f64) / quarter;
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open bins pressure: when many bins are open, discourage spreading; favor filling
    // existing bins (especially this one) over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = 1.0 + progress;
    score += open_bins_count as f64 * 0.6 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward heavily (perfect chain); if next item barely misses, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit — make the empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.3;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a fresh bin is reasonable — soften the penalty.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual deviates below the mean
    // (more filled-in bins get closed out first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward when the next item can fit into the post_residual (chain placement).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains perfectly: reward proportionally to how snugly it fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 20.0 + 25.0 * snug;
        } else {
            // Next item cannot follow here: penalize dead space left behind.
            score += 10.0 + (post_residual as f64 / bin_capacity as f64) * 15.0;
        }
        // Extra bonus if next item fills the bin completely after chaining.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But early in the stream, opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 15.0;
        }
    }

    // Prefer filling already-open bins when many are open (bin count pressure).
    score += open_bins_count as f64 * 0.1;

    // Waste measure: residual below smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small dead space that is hard to reuse (min item size 1, but small slivers waste).
        score += 0.35 * (10.0 - post_residual as f64);
    }

    // Penalize leaving residual that the lookahead item cannot use but could have.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leaving room for the next item is good if it fits snugly.
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the chance to fit the next item here.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: expensive early, cheaper when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // Opening a bin is penalized; penalty shrinks if existing bins are highly fragmented
        // (high mean residual = poor fits available elsewhere).
        let mut new_bin_penalty = 45.0 - 30.0 * fragmentation * progress;
        // If item is large relative to typical residual, new bin is more attractive.
        if open_bins_count > 0 && (item_size as f64) > mean_residual {
            new_bin_penalty -= 15.0;
        }
        // Late in the stream, avoid spreading items thin.
        new_bin_penalty += 20.0 * progress;
        score += new_bin_penalty.max(0.0);
    } else {
        // Mild penalty for using a bin whose residual deviates from mean (preserve balance
        // of small residuals for future small items).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight preference for bins with more residual when many bins are open
        // (keeps fewer, emptier bins around for large future items).
        score += 0.03 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;

    // Base: minimize post residual, smoothly warped
    let mut score = pr * (1.0 + 0.5 * progress * (pr / cap));

    // Smooth polynomial coupling: prefer tight fits, penalize mid-range waste
    let tightness = (it / br).clamp(0.0, 1.0);
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual) * (1.0 - progress);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (nx / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (nx / cap) * (pr / cap);
        }
    }

    // New-bin candidate: penalize opening bins, less so late in stream
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - 0.4 * progress) + 0.5 * open_bins_count as f64;
    }

    // Mild preference for reusing bins when many are open
    score += 0.05 * (open_bins_count as f64).powi(2) * (pr / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: harmonic classes of post_residual via integer division thresholds
    let tightness = match post_residual {
        0 => 40.0,                       // perfect fit
        1..=5 => 30.0,
        6..=10 => 22.0,
        11..=20 => 14.0,
        21..=30 => 7.0,
        _ => 0.0,
    };
    score -= tightness;

    // Harmonic class of item size (capacity fractions): big items are hard to place later,
    // so placing them now in a decent fit is extra valuable.
    let item_class = item_size / 20; // 0..4
    let item_bonus = match item_class {
        3 | 4 => 8.0,
        2 => 4.0,
        _ => 0.0,
    };
    score -= item_bonus;

    // Modulo coupling: residuals in awkward classes (e.g. 31..=49 mod 100) create dead space
    let awkward = (post_residual % 25 == 11 || post_residual % 25 == 12) && post_residual > 10;
    if awkward {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space unusable by the next item
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    // (i.e. this call has full residual) and the stream is early/many bins open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with reasonable fits win.
        score += 25.0;
        // But if the item is huge and mean residual is small, opening fresh is fine.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins (waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Mild preference for filling bins with low mean residual first (keeps big residuals flexible).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Slight preference for fewer open bins (encourage closing out nearly-full bins).
    if post_residual <= 10 {
        score -= open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Mean residual coupling: if the mean residual across open bins is small,
    // the stream is packing tightly -> further discourage new bins / waste.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large (would leave small dead space elsewhere) or no real bin
    // fits well. Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large_item && fitting_bins_count > 1 {
            score += 20.0;
        }
        // Lookahead: if next item is small, it can fill leftover gaps later,
        // so opening a new bin now is less harmful.
        if next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 8.0;
        } else if next_item_size > 0 && next_item_size > post_residual as u32 && post_residual < next_item_size as u32 {
            score += 10.0;
        }
    } else {
        // Lookahead: favor bins whose post residual can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 6.0;
        }
    }

    // Prefer bins with residual close to the item (snug fit) over very loose bins.
    let looseness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += looseness * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving exactly the next item's size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 60.0;
        } else {
            score += gap as f64 * 0.5;
        }
        // If next item fits after this placement, reward it.
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: minimize waste directly.
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad waste
    // or no open bins fit well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 20.0;
        }
    }

    // Slightly prefer tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of residual usefulness.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size.max(10) && next_item_size > 0 {
        score += 8.0;
    }

    // Lookahead: strongly reward bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Lookahead trap: this bin fits item but next item would then be stranded.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is high but unusable (large mean, few fits)
        score += 15.0;
        score -= 20.0 * fragmentation * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives; new bin is wasteful
        }
        if item_size >= 60 {
            score -= 10.0; // big items start fresh bins happily
        }
    }

    // Late stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual near mean (keep balance) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: small post-residuals are good, especially early.
    let pr_norm = pr / cap;
    score -= (1.0 - pr_norm).powi(3) * cap * (1.2 - 0.6 * progress);

    // Penalize dead space that can't fit typical future items (mid-range residuals).
    let dead = (pr_norm * (1.0 - pr_norm)).powi(2) * cap;
    score += dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 2.0;
    }

    // Lookahead: if next item fits the post-residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= (next_item_size as f64 / cap) * cap * 0.35;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 / cap) * 10.0;
    }

    // Prefer bins below mean residual slightly (tighter bins first).
    score += (pr - mean_residual) * 0.15;

    // Mild penalty for opening new bins as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        score += cap * (0.25 + 0.35 * progress) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space ---
    // Class 0: perfect fit -> strong reward
    // Class 1: tiny dead space (1..=5) -> strong penalty
    // Class 2: medium leftover (6..=20) -> mild penalty
    // Class 3: large leftover (>20) -> mild reward
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score += 25.0;
    } else if pr <= 20 {
        score += 6.0;
    } else {
        score -= 3.0;
    }

    // Harmonic residue classes on post_residual (mod 10):
    // leftover in {10, 20, 30, ...} is a "harmonic" slot likely reusable by
    // common item sizes; leftover in awkward classes is penalized.
    let m = pr % 10;
    match m {
        0 => score -= 8.0,
        1 | 9 => score += 5.0,
        5 => score -= 2.0,
        _ => {}
    }

    // Integer-division thresholds: can the leftover host a small item (<= pr)?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits here: reward proportionally to tightness.
            let tight = next_item_size as f64 / pr as f64;
            score -= 10.0 + 12.0 * tight;
        } else {
            // Lookahead cannot use this bin: penalize dead space creation.
            score += 8.0;
        }
        // Harmonic pairing: item + next fills capacity exactly?
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: perfect fit maximally desirable.
        if pr == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening fresh is good only for big items
    // or when the stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early on; penalize when stream is late
        // or item is small (better to squeeze into open bins).
        score -= 18.0 * big_item;
        score += 14.0 * progress;
        score += 0.15 * open_bins_count as f64;
    }

    // Coupling with mean residual: if this bin is far below the mean residual
    // (i.e., unusually full), using it is efficient -> reward.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 120.0; // unusable sliver -> heavy penalty
    } else if post_residual <= 20 {
        // Marginal gap: likely dead unless a tiny item arrives.
        score += 25.0;
    } else {
        // Usable residual: reward proportionally (subtract).
        score -= 0.35 * post_residual as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += 1.2 * open_bins_count as f64;

    // Coupling with mean residual: if the average residual is small,
    // conserve tight bins; if it is large, prefer filling a loose bin.
    score += 0.25 * (mean_residual - post_residual as f64);

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0; // dead space confirmed by lookahead
        }
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 90.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if post_residual as f64 > mean_residual + 30.0 {
            score -= 40.0; // poor fits elsewhere -> fresh bin is fine
        }
    }

    // Mild stream progression: early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size,
    // penalize when post_residual is unusable (too small for any item).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 500.0; // chain fit: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 0.5 * next; // mild reward: next item can still go here
        } else {
            score += 0.3 * next; // dead space relative to lookahead item
        }
        // Penalize leaving gaps that neither current nor next item can use
        if post_residual < next_item_size && post_residual > 0 {
            score += 2.0 * (post_residual as f64).sqrt();
        }
    } else {
        // Last item: prefer minimal post_residual strongly.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight";
    // filling them is valuable, wasting them is costly.
    let tightness = mean_residual - post_residual as f64;
    score += 0.2 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 50.0 + 30.0 * progress;
        // If item fits a tight existing bin well, discourage new bin even more.
        if post_residual < 20 {
            score += 100.0;
        }
    }

    // Slight preference to fill bins with large current residual (avoid fragmentation).
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Penalize dead space that cannot fit typical future items (half capacity threshold).
    if post_residual < 10 {
        score += 15.0; // nearly full bin is fine actually — perfect fit
        score -= 20.0;
    } else if post_residual < 25 {
        score += 6.0; // risky dead zone
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack);
        } else {
            score += 4.0; // next item won't chain here
        }
    } else {
        // Last item: just minimize post residual.
        score += 5.0;
    }

    // Global state: when mean residual is low, conserve open bins (avoid opening new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream.
        score += 8.0 + 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing space could hold the item
        }
    } else {
        // Reward using existing bins more when open bin count is high.
        score -= 0.3 * open_bins_count as f64;
        // Slight time-dependent preference: late in stream, prefer tighter packing.
        score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild normalization against residual magnitude relative to mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - pr / cap; // fill ratio after placement

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 0.6 + 1.2 * p2 + 0.8 * p3;

    let mut score = pr * poly;

    // Reward tight fits more strongly as stream progresses (smooth cubic weighting)
    score -= tight * tight * (30.0 + 70.0 * p3);

    // Penalize large dead space non-linearly (quartic in wasted space)
    let waste = pr / cap;
    score += 25.0 * waste * waste * waste * waste * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (smooth decay)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 + 25.0 * snug * snug;
    } else if next_item_size > 0 {
        // penalize if next item cannot use this bin's residual
        score += 8.0 * (1.0 - progress);
    }

    // Mild preference toward consolidating bins when many are open
    score += open_bins_count as f64 * 0.5 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins with residual near/below mean
    score += (pr - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize opening a bin unless item is large or stream is early
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 20.0 - 45.0 * big * big - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes (10, 20, 25, 50) are more reusable dead space.
    let reusable = (post_residual % 10 == 0) as f64 * 6.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 5.0;
    score -= reusable;

    // Penalize tiny dead-space classes (< 10) that no item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item exactly matches the post-residual,
    // strongly reward; if it cannot fit post-residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
        // Harmonic class match with next item size.
        if post_residual >= next_item_size && post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        // Base new-bin cost; small items justify fresh bins less.
        score += 20.0 + (item_size as f64 / 10.0) * 2.0;
        // In early stream, opening bins is cheap (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If many bins already open and mean residual is high, avoid new bin.
        if mean_residual > item_size as f64 + 10.0 {
            score += 25.0;
        }
    }

    // Mild preference for tighter bins when many are open.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Fraction-of-capacity class of the item: big items prefer emptier bins.
    let item_frac = item_size as f64 / bin_capacity as f64;
    score += item_frac * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit a
    // typical future item (<= 10) are wasted space -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with open_bins_count: pressure to consolidate when many bins open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is close to mean
    // (avoid fragmenting outlier bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad
    // dead gap and the next item could use a fresh bin.
    if bin_residual == bin_capacity {
        let gap_risk = if post_residual < 10 { 1.0 } else { 0.0 };
        score -= 10.0 + 40.0 * gap_risk;
        if next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Lookahead: reward if the post residual can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 8.0;
        }
    }

    // Early stream: mild consolidation bias; late stream: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + slack * 0.3;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Penalize leaving residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: mildly penalize unless current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host current + next cleanly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.06;
    } else {
        // Perfect fill is excellent.
        score -= 25.0;
    }

    // Small dead space (< 10, unusable for smallest items) is very bad.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving mid-range residual.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into open bins
    // (keep flexibility); late in the stream, tight packing matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Many open bins: discourage spreading; favor bins below mean residual
    // (tighter bins) to concentrate fill.
    if open_bins_count > 3 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when item is large or
    // no good fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for filling bins that are already mostly full.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, quadratically for small residuals (dead space)
    let mut score = pr as f64 + 40.0 * (1.0 - x) * (1.0 - x) * pr;

    // Smooth stream-progress coupling: late in the stream, tight fits matter more
    let late = progress * progress;
    score -= 30.0 * late * (1.0 - x) * x * cap; // reward medium-tight fits late
    score += 25.0 * late * x * x * cap;         // penalize large leftover late

    // Lookahead coupling: reward bins whose post residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr >= nx) as i32 as f64;
        let snug = 1.0 - ((pr - nx).abs() / cap);
        score -= 20.0 * fits * snug * snug;
        score += 10.0 * (1.0 - fits) * late;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0 + 30.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    let mr = mean_residual / cap;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (15.0 + 40.0 * mr * (open_bins_count as f64).ln_1p() * 0.2);

    // Smooth anti-fragmentation: penalize post residuals below typical next sizes
    score += 12.0 * (1.0 - x) * (1.0 - x) * (1.0 - late);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 and mod 25.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;

    // Penalize awkward residuals (small non-zero dead space).
    if pr > 0 {
        if pr < 10 {
            score += 30.0 - (pr as f64) * 2.0; // tiny dead space is worst
        } else {
            // Prefer residuals that are "harmonic": divisible by 10 or 25.
            if pr % 10 == 0 { score -= 8.0; }
            if pr % 25 == 0 { score -= 6.0; }
            if pr % 50 == 0 { score -= 5.0; }
            score += class10 * 0.6 + class25 * 0.4;
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    if fill > 0.8 { score -= 15.0; }
    else if fill > 0.6 { score -= 7.0; }

    // Lookahead coupling: does the residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic pair: post_residual divisible by next size class.
            let nxt = next_item_size as f64;
            if (pr as u32 % next_item_size.max(1)) == 0 {
                score -= 10.0;
            } else if pr - next_item_size < 10 {
                score += 5.0; // leaves another dead sliver
            }
            score -= 4.0; // generally good to keep a usable slot
        } else {
            // Residual cannot fit next item; dead space unless next is small.
            score += 6.0;
            if next_item_size > 60 && pr > 0 { score += 4.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; subtract when stream is early and bins few.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 && open_bins_count < 4 { score -= 5.0; }
        if item_size as f64 / cap > 0.75 { score -= 3.0; }
        // Penalize new bin if mean residual of open bins is large.
        score += mean_residual * 0.15;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A gap is "unusable" if it's smaller than the smallest plausible item (1..100).
        // Treat gaps < 20 as near-waste; gaps that cannot fit the next item are worse.
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 4.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.5 + 30.0;
        score += pressure;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Slight preference for bins tighter than the current mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be a bit more willing to fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // perfect 2-chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            let slack = post - nxt;
            // tighter residual after the hypothetical next placement is better
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space relative to mean residual
            score += 60.0 + (nxt - post).min(40.0);
        }
        // Coupling with mean residual: bins far below mean residual are precious, prefer them
        let mean = mean_residual;
        if (post as f64) < mean {
            score -= (mean - post as f64) * 0.5;
        } else {
            score += (post as f64 - mean) * 0.3;
        }
    } else {
        // Last item: just prefer tightest fit
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit; make the empty bin unattractive unless item is huge relative
    // to typical residuals.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / bin_capacity as f64;
        let mean_fit = mean_residual - item_size as f64;
        if next_item_size > 0 && mean_fit > (next_item_size as f64) * 0.5 {
            score += 400.0; // open bins still look useful, avoid opening new bin
        } else if pressure > 0.6 {
            score -= 100.0; // big item, fresh bin is fine
        } else {
            score += 150.0 * (1.0 - pressure);
        }
    }

    // Slight stream-progression damping: early on, keep options open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin mildly, so equal-fit existing bins win;
    // but relax the penalty late in the stream (consolidation phase).
    if is_new_bin {
        score += 3.0 * (1.0 - 0.5 * progress);
    } else {
        // Reward tight fits in existing bins: squash post_residual advantage.
        score = score.powf(1.15);
    }

    // Last-chance bin: strongly favor using it to avoid wasting its uniqueness.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly or well in the post-residual,
    // reward this placement (chain-friendly). If the next item would leave
    // this bin's remainder useless anyway, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 3.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize creating small dead space
            // that likely becomes waste, scaled by how dead it is.
            let deadness = post_residual as f64 / bin_capacity as f64;
            if deadness < 0.10 {
                score += 2.0 * (0.10 - deadness) * 10.0;
            }
        }
    }

    // Global state coupling: prefer placing into bins whose residual is far
    // above the mean only when the mean is high (many loose bins); prefer
    // below-mean bins when the mean is low (tight packing regime).
    let dev = bin_residual as f64 - mean_residual;
    if mean_residual > bin_capacity as f64 * 0.4 {
        score += 0.05 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr_norm * (1.0 + 0.6 * progress * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (0.8 + 0.7 * progress);

    // Penalize dead space: cubic term in post_residual.
    score += 0.35 * pr_norm * pr_norm * pr_norm;

    // Lookahead coupling: reward residual that fits the next item smoothly.
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        let match_term = 1.0 - ((pr_norm - nx) / cap).abs().min(1.0);
        score -= 1.2 * match_term * match_term;
    } else {
        score += 0.5 * pr_norm;
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5 * (1.0 - fit_ratio);
    }

    // Mild penalty for spreading across many open bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins close to mean (balanced packing).
    let mean_norm = mean_residual / cap;
    score += 0.3 * (pr_norm - mean_norm) * (pr_norm - mean_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity quantized into 10-unit classes.
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 25.0,          // perfect fit: zero waste
        1 => score -= 12.0,          // near-perfect
        2 => score -= 6.0,
        3 => score -= 2.0,
        4 => score += 3.0,           // awkward dead zone
        5 => score += 6.0,
        6 => score += 8.0,
        7 => score += 10.0,
        _ => score += 12.0,          // large leftovers: bin was barely used
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic pair: leftover matches the next demand
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
            // leftover cannot serve next item: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.25;
        }
        // Modular check: next item lands on a compatible residue class
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening fresh bins is expensive; make empty bin less attractive
    // unless current placement would waste a lot (post_residual too small OR too fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - progress * 10.0; // slightly cheaper to open early in stream
        if post_residual <= 10 && post_residual > 0 {
            score -= 20.0; // item nearly fills a bin alone: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // next item can join the fresh bin
        }
    }

    // Prefer filling bins below the mean residual (reduces variance of open space).
    score += (mean_residual - post_residual as f64) * 0.10;

    // Mild pressure when many bins are open: consolidate.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 25 {
        // moderately hard-to-fill gap: partial penalty, scaled by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (0.5 + 0.5 * progress);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if item_size as f64 / bin_capacity as f64 > 0.8 && post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with open bins count.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the current bin is a bad host (item barely fits or leaves dead space),
        // make new bin more attractive.
        if item_size > bin_residual {
            score -= 60.0; // shouldn't happen (bin fits), safety
        }
        if post_residual < 10 {
            score -= 30.0;
        }
        // Lookahead: if next item could combine with leftover in a fresh bin, favor new bin.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        }
    } else {
        // Existing bin: reward leaving room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize placing into bins whose residual deviates from mean (fragmentation control).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: match post_residual against next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect slot for the next item: strongly reward.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: proportional reward for tight follow-up fit.
            let slack = post_residual as f64 - nxt;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit: dead space penalty, worse the closer we came
            // (near-miss wastes more potential than a far miss).
            let miss = nxt - post_residual as f64;
            score += 8.0 + 10.0 * (1.0 - miss / nxt.max(1.0));
        }
    }

    // Penalize creating tiny unusable slivers (< 10 min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual deviates favorably from mean residual:
    // using a tighter-than-average bin keeps loose bins flexible.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // Allow new bin if the item would leave a large, next-item-compatible hole.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Late in the stream: consolidate, discourage new bins further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post-residual that likely can't fit future items).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 18.0 * (10.0 - dead) / 10.0; // tiny slivers are wasted
        }
    } else {
        score -= 15.0; // perfect closure is excellent
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily;
    // if the next item cannot fit post-residual but fits elsewhere, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // discourage fragmenting; consolidate into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual > mean_residual + 5.0 && open_bins_count > 2 {
        score += 6.0 * progress;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., residual is large relative to item) or late in the stream with few options.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 0.9;
        if decent_fit_exists {
            score += 30.0; // strongly discourage wasting a fresh bin
        } else {
            score -= 5.0 + 10.0 * progress; // fresh bin becomes more attractive over time
        }
    }

    // Mild preference for using fuller bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth interaction: residual usefulness decays polynomially with stream progress
    score -= 12.0 * (1.0 - progress) * (pr_norm * (1.0 - pr_norm)) * cap;

    // Penalize dead space that nothing can fill (next item too large or none)
    if next_item_size == 0 {
        score += 4.0 * pr_norm * cap;
    } else {
        let nxt = next_item_size as f64;
        let fits_next = if nxt <= pr { 1.0 } else { 0.0 };
        // smooth reward for leaving room close to the next item size
        let gap = ((pr - nxt).abs()) / cap;
        score -= 10.0 * fits_next * (1.0 - gap) * (1.0 - progress);
        score += 6.0 * (1.0 - fits_next) * pr_norm;
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - pr_norm);

    // Prefer bins near the mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: residuals that are multiples
    // of small common item sizes (10, 20, 25, 50) stay reusable.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 12.0; // harmonic residual: reusable by many item sizes
    } else {
        score += 6.0 + cls as f64; // odd dead space penalty
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Integer-division thresholds: classify residual into usability tiers.
    let tier = post_residual / 10; // how many 10-sized items could still fit
    score -= tier as f64 * 3.0;

    // Lookahead coupling: penalize residuals that cannot host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // bonus if post_residual - next_item_size is also harmonic
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 20.0; // dead space for the known next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            25.0
        } else {
            0.0
        };
        score += 30.0 - pressure + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Slight preference for fuller bins relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream urgency: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize post_residual quadratically in the "dead zone" band (10..=25),
    // where leftovers are hard to reuse for typical items.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.9 * (25.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 2.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Open-bin pressure: penalize when many bins are already open,
    // discouraging proliferation; reward consolidation otherwise.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it mildly unattractive unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // Penalize if post residual cannot host the lookahead item but is close.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.4 * (next_item_size - post_residual) as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Stream progression: early on, be more conservative about spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fits the post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how well it fills
            score -= 0.3 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot fit here: penalize small post_residual (dead space)
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 20.0 + gap as f64;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins with above-average residual used well
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Mild penalty for opening new bins when stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization core).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 * (6.0 - post_residual as f64);
    }

    // Penalize dead space relative to capacity, non-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * frac * frac * (bin_capacity as f64);

    // Tight-fit bonus: item fills a large share of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use leftover: penalize large leftovers a bit more.
            score += 8.0 * (1.0 - (next_item_size as f64 / (post_residual as f64 + next_item_size as f64)));
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate, avoid new bins.
    if bin_residual != bin_capacity {
        let spread = mean_residual - bin_residual as f64;
        score -= 3.0 * spread; // prefer bins below mean residual (tighter bins)
        if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
            score -= 10.0; // consolidation pressure when many bins are open
        }
    } else {
        // New-bin candidate: penalize opening bins when existing bins fit well.
        if fitting_bins_count > 0 {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        }
        // Early in stream, opening a fresh bin is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large and this bin is fresh, opening is attractive.
        if next_item_size > post_residual.max(1) as u32 {
            score -= 12.0;
        }
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fills (low post_residual); late stream: tolerate residual
    let coupling = 30.0 * (1.0 - progress) * norm_pr * norm_pr
                 - 12.0 * p2 * norm_pr
                 + 8.0 * p3 * norm_pr * norm_pr;
    score += coupling;

    // Penalize large post_residual when lookahead item cannot use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 15.0 * (1.0 - pr / nxt.max(1.0));
        } else {
            score -= 10.0 * (nxt / (pr + 1.0));
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for scattering across many open bins with high mean residual
    score += 0.3 * (open_bins_count as f64).ln() * (1.0 - norm_pr);

    // Prefer bins whose residual is close to the mean (balanced filling)
    score += 0.05 * (pr - mean_residual).abs();

    // Strongly discourage opening a new bin when existing bins fit well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0 * (1.0 - norm_pr.abs() * 0.0) + 20.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;

    // Reward post_residuals that sit in "harmonic" residue classes (multiples of 10/20)
    if r % 10 == 0 {
        score -= 6.0;
    }
    if r % 20 == 0 {
        score -= 4.0;
    }
    // Penalize awkward odd residues that waste space
    score += 0.6 * m4 + 0.4 * m5 + 0.3 * m10;

    // Integer-division class: post_residual bucket by 10s
    let bucket = r / 10;
    score -= (bucket as f64) * 0.8; // larger usable leftover preferred, mildly

    // Perfect fit is excellent
    if r == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if r > 0 && r < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0;
        } else if next_item_size < r {
            score -= 2.0;
        } else {
            score += 3.0; // next item won't fit here -> this bin is a dead end
        }
        // Harmonic class match: post_residual and next_item share a divisor class
        if r > 0 && next_item_size % 10 == r % 10 && next_item_size < r {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New empty bin candidate: penalize unless no open bin can fit the item
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // forced new bin
        } else {
            score += 12.0 + 2.0 * (open_bins_count as f64).sqrt(); // prefer reusing open bins
        }
    }

    // Mean-residual coupling: placing in a bin far from mean residual balances load
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (r as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever be useful are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(20)) {
        score += 40.0;
    }
    // Penalize gaps that cannot fit the lookahead item when one exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * next_item_size as f64;
    }

    // Reward very tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins; discourage spreading.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Opening a new bin is more attractive early in the stream / many open bins.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild attraction to bins with residuals close to the item (good match).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item size (two-step perfect fill).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact two-step fill is gold: penalize anything else.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // If next item cannot fit anywhere after this placement,
        // penalize leaving a large stranded residual.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Penalize creating unusable dead space relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Discourage leaving residuals that are too small to be useful
    // (below the minimum plausible item size) unless nearly full.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for keeping fewer open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Reward tight fits: post_residual near 0 is good, so scale it down.
    score *= 0.6 + 0.4 * (post_residual as f64 / cap);

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 8.0 * (1.0 - next_item_size as f64 / cap);
        } else {
            // Penalize leaving a gap that the next item cannot use (dead space).
            score += (post_residual as f64) * 0.35 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    // when mean residual is large (lots of slack available overall).
    score += 0.6 * (open_bins_count as f64).ln().max(0.0);
    score -= 0.4 * (mean_residual - post_residual as f64);

    // New-bin candidate: opening a new bin wastes the residual of existing bins.
    if bin_residual == bin_capacity {
        let waste: f64 = mean_residual * (open_bins_count as f64);
        // Only open a new bin if existing bins are very full (low mean residual)
        // or this is a poor-fit situation (large post_residual elsewhere anyway).
        let threshold = 6.0 + 10.0 * (1.0 - progress) + 0.05 * waste;
        score += threshold;
        // If no other bin can fit the item, opening a new bin is forced.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight late-stream bias toward filling existing bins tighter.
    score -= 3.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    // Smooth interaction: dead-space penalty grows super-linearly as stream advances
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * bin_capacity as f64;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit well, especially early
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        let penalty = 15.0 + 30.0 * (1.0 - progress) + mean_fit_gap * 0.2;
        score += penalty;
        // If next item could co-fit nicely in this fresh bin, soften penalty
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr && !is_new_bin {
        let fill = next_item_size as f64 / bin_capacity as f64;
        score -= 6.0 + 10.0 * fill * (1.0 - progress);
    } else if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        // Penalize leaving a sliver that the next item cannot use
        let sliver = pr / (next_item_size as f64);
        score += 4.0 * (1.0 - sliver.min(1.0));
    }

    // Mild diversity pressure: many open bins -> favor consolidating into fuller bins
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 0.5 * bin_pressure * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "waste classes" of 10.
    let waste_class = (post_residual / 10) as f64;
    score += waste_class * waste_class * 2.0;

    // Perfect fit: post_residual exactly divisible by 10 -> highly desirable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Exact zero residual is the ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic coupling with next item: if next item can exactly fill post_residual,
    // reward strongly; if next item leaves a tiny unusable gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // gap in (1..10) is the worst dead-space class
            if gap < 10 {
                score += 8.0;
            } else if gap % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here: residual below next_item_size is semi-dead
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current bin's post-residual is a bad harmonic class (small odd remainder).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        let rem = post_residual % 10;
        // If this bin would leave a tiny remainder (1..9), opening a new bin is better.
        if rem > 0 && rem < 10 && post_residual > 0 {
            score -= 18.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Prefer bins whose residual is far below the mean (tight packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Many open bins: discourage spreading into high-residual bins.
    if open_bins_count > 4 {
        score += (post_residual as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // conceivable item are wasted space; punish them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: zero waste, reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight-fit reward relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize leaving a gap that exactly invites a bad split later:
    // if post_residual is just barely above the next item, fine; if far above,
    // encourage it; if just below next item, it is dead space for lookahead.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size as f64 - post_residual as f64) * 4.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += bin_pressure * (1.0 - fit_ratio);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin residuals are poor
    // (large mean residual means open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - fragmentation.min(30.0);
        score += open_bins_count as f64 * 0.5;
        // A new bin is fine if the item is large (would leave small gap anyway).
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is an ideal chained placement — heavily reward it.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            score -= (bin_capacity as f64) * (1.0 - diff / bin_capacity as f64) * 0.9;
        } else {
            // Next item won't fit here: penalize dead space relative to mean residual.
            score += diff * 0.6;
        }
        // Coupling with mean residual: leaving residuals far below the mean
        // fragments the bin pool; penalize when post_residual << mean_residual.
        if post < mean_residual * 0.5 {
            score += (mean_residual - post) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, tighten: avoid opening new bins with lots of space left.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 30.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty proportional to open bins to discourage bin proliferation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = 1.0 - (post / cap);
    score -= 40.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    if post > 0.0 && post < 10.0 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let leftover = post - nxt;
            score -= 30.0 * (1.0 - leftover / cap);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 6.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, prefer tight fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    if mean_residual > item_size as f64 {
        score -= 8.0 * (mean_residual / cap);
    }
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a well-shaped residual, or no good open option exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 20.0;
        // Large items are fine to start a new bin with.
        score -= 0.25 * item_size as f64;
        // If next item is also large, new bin may host a pair.
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            score -= 15.0;
        }
        // Late in stream, avoid opening bins for small items.
        score += 30.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    score -= 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);
    score += 40.0 * norm_pr * norm_pr * progress;
    // penalize tight fits less as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * progress;
    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs() / cap;
        score += 10.0 * gap * gap;
        if ni <= pr {
            score -= 8.0 * (ni / cap);
        }
    }
    // last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // mild penalty for scattering across many bins vs mean residual
    score += 0.05 * ((pr - mean_residual) / cap) * (open_bins_count as f64);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead space classes".
    let post = post_residual as i64;
    let dead = post % 10; // residue class of leftover
    // Penalize awkward residues (1,2,3 tiny slivers; 4..6 medium dead zones)
    let dead_penalty = match dead {
        0 => 0.0,
        1..=3 => 12.0,
        4..=6 => 6.0,
        7..=9 => 2.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Perfect fit reward: post_residual in {0} or a harmonic half/quarter class
    if post == 0 {
        score -= 40.0;
    } else if post == bin_capacity as i64 / 2 || post == bin_capacity as i64 / 4 || post == bin_capacity as i64 / 3 {
        score -= 8.0;
    }

    // Integer-division threshold: how many size-10 units remain; prefer multiples of 10
    let units = post / 10;
    let rem = post % 10;
    if units >= 3 {
        score -= 4.0; // still reusable for mid items
    }
    if rem != 0 && units == 0 {
        score += 8.0; // pure dead space below smallest item class
    }

    // Lookahead coupling: harmonic compatibility of next item with post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next fits here: reward proportional to tightness of that future fit
            let future_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 - (future_fit / 10.0).min(8.0);
            // harmonic match: next item's residue class complements post residual
            if (post % 10) == (next_item_size as i64 % 10) {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize if leftover small
            if post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it competitive only when current fit is bad
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a decent fit, below a terrible fit
        score += 25.0;
        // early stream: allow opening bins more freely
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if many open bins have high mean residual, discourage new bin
        score += (mean_residual - 40.0).max(0.0) * 0.3;
    }

    // Prefer fuller bins: scale by fraction of bin used
    let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * used_frac;

    // Mild pressure to consolidate when too many bins open
    if open_bins_count > 8 {
        score -= (open_bins_count as f64 - 8.0).min(10.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small gaps that likely cannot host future items (min item ~1..10, be conservative)
    let dead_threshold = 9.0;
    if post > 0.0 && post <= dead_threshold {
        score += 40.0 * (dead_threshold - post) / dead_threshold;
    } else if post == 0.0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward tight fits relative to bin fill
    let fill_ratio = (bin_residual as f64 - post) / cap;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
        // But allow new bin if no open bin fits well (post_residual here would be cap - item)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: keep balance across bins
    score += 0.05 * (post - mean_residual).abs();

    // Late-stream pressure: consolidate toward end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits within a small tolerance
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: next item cannot use the leftover
    else if next_item_size > 0 && post_residual > 0 {
        let dead = (next_item_size - post_residual) as f64;
        score += 6.0 * dead / 100.0;
    }

    // Relative residual vs mean: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize the new-bin candidate unless nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 10.0; // opening a bin for a run of same-size items is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 0.10 * (pr - nxt).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins when open bins fit well,
    // but allow it when post_residual would be small and mean residual is low.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 10.0; // pairing items in a fresh bin is attractive
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global state: if mean residual is high, prefer bins that reduce it.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Encourage using bins with many open bins (consolidation pressure).
    if open_bins_count > 3 {
        score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p_norm = post / cap;
    let poly = p_norm * p_norm * (1.0 - progress) + p_norm * progress * (1.0 - p_norm);
    score += 20.0 * poly - 10.0 * p_norm * progress;

    // Penalize dead space that can't fit typical items, smoothed by progress
    let dead = (post - next_item_size as f64).max(0.0);
    score += 0.5 * dead * dead / cap * (0.5 + progress);

    // Reward tight fits (small post_residual) more as stream progresses
    score -= 15.0 * (1.0 - p_norm).powi(2) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins below mean residual (keep bins balanced) with smooth coupling
    score += 0.3 * (post - mean_residual) * (1.0 - progress);

    // Lookahead: reward leaving space exactly for next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).powi(2);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual as f64 == cap {
        score += 12.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity-fraction band does the
    // post-residual fall into? Small post-residuals (tight fits) are prized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residual below smallest item class (<=10) is waste.
    if post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo classes: residuals that are "friendly" (divisible-ish bands)
    // combine well with common item sizes. Reward post_residual in
    // [10, 30] band (fits small/medium items exactly).
    if post_residual >= 10 && post_residual <= 30 {
        score -= 12.0;
    }
    // Harmonic mid band [31, 50]: still useful.
    if post_residual > 30 && post_residual <= 50 {
        score -= 5.0;
    }
    // Large leftover band: mild penalty relative to baseline (already high).
    if post_residual > 50 && post_residual <= 80 {
        score += 4.0;
    }

    // Integer-division threshold: post_residual / 10 class.
    let class = post_residual / 10;
    score -= (class as f64) * 1.5; // prefer smaller classes slightly beyond raw value

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current
    // bin fits are all poor. Penalize the empty-bin call moderately, but
    // relax when the stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64) * 3.0;
        score += 18.0 + 20.0 * (1.0 - progress) + openness;
        // But if the item is huge relative to capacity, new bin is natural.
        if (item_size as f64) > 0.8 * cap {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is a perfect chain — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits into post_residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item cannot fit in post_residual but could fit a fresh bin,
    // slight penalty for leaving a stranded residual.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the emptiest-feeling bins less wastefully).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Exact fit is the ultimate harmonic class.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's smaller than the smallest plausible item (1..100, min item = 1),
    // but practically gaps below ~10 are nearly unusable; weight them heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0 * (10 - post_residual) as f64; // small unusable slivers
        } else if post_residual < 20 {
            score += 8.0 * (20 - post_residual) as f64; // awkward gaps
        }
    } else {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating a gap the next item cannot use.
        score += 4.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: discourage unless current bin fits are desperate.
        score += 15.0 + 2.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            // Last-chance fit exists: strongly discourage opening a new bin.
            score += 30.0;
        }
        // If the next item is large and this item leaves a bad gap, opening a fresh bin
        // can be attractive: soften the penalty when mean residual is high.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    } else {
        // Fitting into an existing bin is generally good; extra reward when it's
        // the only fitting bin (avoid wasted alternative).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Prefer filling bins with small residuals (tight packing pressure).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Mild progression term: later in the stream, be more conservative about
    // opening new bins (fewer chances to consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Exact match for next item is highly desirable.
        if gap == 0 {
            score -= 60.0;
        } else {
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover; penalize proportionally to wasted lookahead.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare post_residual against mean residual: avoid leaving bins far below average utility.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow a new bin if no open bin fits well (post_residual would be tiny waste).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, dead space is bad.
    // Penalize super-linearly as post_residual falls into "unusable" range.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 25.0; // perfect-ish fit, tiny leftover
        } else if post_residual < 20 {
            score -= 8.0;
        } else {
            // large leftovers are less attractive the bigger they get
            score += (post_residual as f64 - 20.0) * 0.35;
        }
    } else {
        score -= 40.0; // exact fill
    }

    // Lookahead: if the next item fits in post_residual, this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(20.0) * 0.3; // prefer chains with small slack
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; leaving large dead space is worse
        score += post_residual as f64 * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 30.0;
        } else {
            score -= 5.0; // weak last-chance still mildly preferred
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize opening a new bin, more so when good open options exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 35.0 + 15.0 * (1.0 - progress); // early stream: avoid new bins
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += base_penalty + fit_pressure;

        // If mean residual across open bins is high, opening new bins is wasteful.
        score += (mean_residual / bin_capacity as f64).min(1.0) * 25.0;
    }

    // Fragmentation guard: avoid splitting a bin in a way that leaves a residual
    // that is unlikely to fit typical future items (mid-range dead space).
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 6.0;
    }

    // Mild tie-break: prefer fuller bins (smaller residual) when scores are close.
    score += bin_residual as f64 * 0.02;

    // Prefer distributing across bins when many are open (avoid extreme imbalance).
    score += (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_pr;
    score += 30.0 * progress * tightness * tightness * (1.0 - progress);

    // Penalize large post residual relative to mean residual (dead-space waste)
    score += 0.5 * (pr - mean_residual).abs();

    // Reward filling bins nearly exactly: cubic smooth reward
    score -= 40.0 * (1.0 - norm_pr).powi(3) * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let next_fit = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - next_fit) * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalty if next item cannot use the leftover smoothly
        score += 5.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Mild pressure against hoarding many open bins early
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when post residual would be very small waste
    if bin_residual == bin_capacity {
        score = pr + 8.0 - 10.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
