    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use the leftover: penalize proportional waste
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // new bin baseline: slightly worse than a good existing fit
        score = cap_f * 0.55;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: favor tightening existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap_f - post_residual as f64) * 0.05;

    // Mean residual coupling: if this bin is far below mean residual, using it balances waste.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Small usable gap: mild penalty to prefer leaving roomier gaps.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual can't host next item: dead space risk, penalize.
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; a new bin (residual == capacity) gets a rising penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 1.2;
        // New bin is attractive only if item is large and few fitting bins exist.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: avoid opening a new bin for this item.
        score -= 18.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (filling the emptier-feeling bins keeps many small-gap bins in play).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Reward if next item fits in the post residual
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize leaving dead space that the next item cannot use
    else if next_item_size > 0 && post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.5 * dead;
    }

    // Compare post residual to mean residual: tighter-than-average packing is good
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the current bin is very full already
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Slight preference for filling bins more completely as the stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space: residuals too small for the smallest item (1..100, min 1)
    // Use a soft "waste" curve on post_residual.
    let waste = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 {
        score += 6.0 * waste * (1.0 - waste);
    } else {
        score -= 5.0; // perfect fill bonus
    }

    // Lookahead coupling: if the next item fits exactly-ish in the post residual,
    // this bin remains useful; otherwise penalize hoarding space the next item can't use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * next_tightness; // chain potential
        } else {
            // Next item can't use this leftover: leftover is dead weight
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it heavily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // With many options, be picky: penalize loose fits more.
        score += 2.0 * (fitting_bins_count as f64).ln() * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current fit is poor (large post_residual) or the stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are rarely chosen over decent fits.
        score += 15.0;
        // But if this item would leave a very large hole in any existing bin,
        // a fresh bin is cleaner. Compare against mean residual pressure.
        if post_residual as f64 > mean_residual * 0.6 {
            score -= 18.0; // existing bins are all fairly full anyway -> open new
        }
        // Early in the stream, having many bins is cheap insurance.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 6.0;
        }
        // Lookahead: if next item is large, a fresh bin gives room to pair.
        if next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 3.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate,
    // favor filling existing bins rather than spreading.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Late in stream: closing out bins matters more; reward near-perfect fills harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 7.0 * fit_ratio;
        score += 2.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Small tie-breaker against fragmenting bins with mid-range residuals.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // tiny leftovers are nearly useless, but a near-exact fit is good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling: base on post_residual, shaped by progress and fit
    let mut score = pr;

    // Reward tight fits more strongly as the stream progresses (smooth cubic in progress)
    let tightness = fill * fill;
    score -= tightness * (1.0 + 3.0 * progress) * 30.0;

    // Penalize small post-residuals that are too small for typical future items
    // (smooth quadratic dead-space penalty around mid residuals)
    let dead = (pr / cap - 0.35).powi(2);
    score += dead * 25.0;

    // Lookahead coupling: reward if next item fits smoothly in post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        let gap = (pr - nx).abs() / cap;
        score -= fits_next * 20.0 * (1.0 - progress * 0.5);
        score += gap * gap * 15.0;
    }

    // Last-chance bonus: only fitting bin -> strongly favor it (smooth, scaled by fit quality)
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + 0.5 * fill);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 5.0 * progress);

    // Mean residual alignment: prefer bins near mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate: penalize slightly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 - 25.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space smaller than the
    // smallest possible item (1) is perfect; residuals in awkward bands
    // (just above small-item sizes) are penalized.
    let cap = bin_capacity as f64;

    // Base: strongly prefer tight fills.
    score = post_residual as f64 * 1.0;

    // Reward near-perfect fills (post_residual in {0,1,2}).
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize post-residuals that fall into "awkward" harmonic classes:
    // residuals just above a typical small item cannot be reused well.
    let pr = post_residual;
    let class = pr % 10;
    if class == 1 || class == 2 {
        // awkward sliver classes -> dead space risk
        score += 6.0;
    } else if class == 0 {
        // round residuals are reusable by many size classes
        score -= 3.0;
    }

    // Integer-division thresholds: residual >= 2*next_item_size is good
    // (can still host the lookahead item plus slack).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= 2.0 * n {
            score -= 8.0;
        } else if (post_residual as f64) >= n {
            score -= 3.0;
        } else {
            // this bin cannot host the next item: dead space
            score += 10.0;
        }
        // modulo coupling: exact division means perfect pairing
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: make it attractive only when the current item is
    // large relative to capacity (harmonic class of item_size) or the
    // stream is early and bins are few.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_score = cap * 0.55; // baseline penalty for a fresh bin
        if frac > 0.5 { new_score -= 18.0; }        // big items pair poorly
        if open_bins_count == 0 { new_score -= 40.0; }
        if progress < 0.15 { new_score -= 5.0; }
        if mean_residual < 15.0 && open_bins_count > 0 { new_score -= 10.0; }
        score = new_score;
    }

    // Mild global pressure: many open bins with high mean residual ->
    // encourage consolidating into existing bins.
    if bin_residual < bin_capacity {
        score -= (mean_residual / cap) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (quadratic in the "wasted" zone).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 0.35 * (20 - post_residual) as f64 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else or open-bin pressure is high; otherwise discourage spreading out.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_penalty = 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        score += spread_penalty;
        if post_residual > 30 {
            score -= 10.0; // a fresh bin leaves a large useful residual
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Lookahead: favor bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // dead space relative to the lookahead item
    }

    // Mild pressure from many open bins: prefer bins below mean residual
    // (i.e., fuller bins) to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already captured by base score).

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item cannot fit post_residual, penalize proportionally to wasted residual.
    else if next_item_size > 0 && next_item_size <= bin_residual {
        score += 0.5 * post_residual as f64;
    }

    // Penalize leaving dead space that no plausible item (min size 1..) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless this bin is unusable.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // penalize dead space that next item cannot use
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs().max(0.0);
        }
    } else {
        // last item: prefer exact fill
        score += 0.1 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize creating very small unusable slivers (<10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Relative tightness term: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Global state coupling: when many bins are open and mean residual is high,
    // discourage wasting space in already fragmented bins
    if open_bins_count > 0 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.3 * frag;
    }

    // Time horizon: early in the stream, be more liberal opening bins (favor spreading);
    // late in the stream, prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 80.0 * progress * fill_ratio;

    // New empty bin candidate: make it attractive only when current fit is bad
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, discounted early in the stream
        score = 100.0 + post_residual as f64 - 120.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // new bin keeps room for similar/larger items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tight = (cap - pr) / cap; // fraction filled after placement
    score -= (1.0 + progress) * 20.0 * tight * tight;

    // Penalize dead space that can't fit typical next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap;
        } else {
            score -= 4.0 * (pr - ns) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of bins fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * fitting_bins_count as f64;
    }

    // Mild dispersion penalty: prefer bins near the mean residual.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep residual in "usable" harmonic classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    }

    // Harmonic class of post_residual: residuals divisible by common item
    // sizes (or their complements) are reusable dead space.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that lie on harmonic lattice points of capacity.
        let lattice = [0u32, 10, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90];
        if lattice.iter().any(|&l| l == pr) {
            score -= 12.0;
        }
        // Penalize residuals in dead zones: 1..9 and 81..99 minus nice values
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64; // tiny slivers are worthless
        } else if pr > 80 {
            score -= 8.0; // big residual is nearly a fresh bin
        }
        // Modulo-5 / modulo-10 smoothness: residuals matching multiples of 5
        // pair well with typical item sizes.
        if pr % 5 == 0 {
            score -= 4.0;
        }
        if pr % 10 == 0 {
            score -= 3.0;
        }
        // Integer-division banding on residual: mid-band residuals (30..70)
        // are the most flexible for unknown future items.
        let band = pr / 20; // 0..5
        score -= match band {
            1 | 2 => 6.0,
            3 => 4.0,
            4 => 2.0,
            _ => 0.0,
        };
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.5;
        } else {
            // Next item cannot follow here; slight penalty scaled by gap.
            let gap = next_item_size - post_residual;
            score += (gap as f64).min(40.0) * 0.3;
        }
        // Harmonic: next item shares a divisor class with item_size
        if next_item_size % 10 == item_size % 10 && next_item_size > 0 {
            score -= 3.0;
        }
    } else {
        // Last item: prefer closing bins out (zero residual).
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin is a fallback. Make it mildly
    // attractive when open bins are fragmented, otherwise unattractive.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a decent fit.
        score = 55.0;
        // If existing bins are fragmented (high mean residual spread), allow
        // opening a new bin more readily.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        if open_bins_count > 8 {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Mild penalty for hoarding many open bins with poor average residual.
    if mean_residual < 15.0 && open_bins_count > 3 && bin_residual != bin_capacity {
        score += 6.0;
    }

    // Progress-scaled tightness pressure: as stream advances, demand tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the smallest possible item (1) are impossible, but gaps
    // below ~10 are nearly dead for typical streams; scale penalty smoothly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Wasted-capacity ratio penalty (non-linear, quadratic in fill fraction)
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score += 30.0 * (1.0 - fill) * (1.0 - fill);

    // Reward tight fits strongly (post_residual small but nonzero)
    if post_residual > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; mild penalty for stranding space
        score += 5.0;
    }

    // Slight preference for using bins early in the stream (fewer bins later)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — prefer finishing it off.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits exactly into this bin after placement: strong reward.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 0.8 * gap;
        }
    }

    // Compare post residual against mean residual across open bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only prefer when residuals of open bins are tight.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * mean_residual;
    }

    // Late in the stream, consolidate: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that is still unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(15.0) / 15.0;
        } else {
            // Next item cannot use this bin's remainder; slight penalty unless remainder tiny.
            score += 3.0;
        }
    }

    // Prefer using bins with smaller residuals among equals (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // When many bins are open, encourage filling them rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity and open bins are quite full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let penalty = 40.0 - 30.0 * avg_fill - 15.0 * fit_ratio;
        score += penalty.max(2.0);
    }

    // Late in the stream, be more aggressive about closing gaps.
    if progress > 0.8 {
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr_norm.powf(1.0 + 1.5 * progress);

    // Dead-space penalty: small post-residuals that are hard to fill
    let dead = if pr > 0.0 && pr < 10.0 { 0.5 + 0.5 * (10.0 - pr as f64) / 10.0 } else { 0.0 };

    // Fit quality: how snugly the item fits
    let fit = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);

    // Lookahead: reward bins whose post-residual can host the next item
    let lookahead = if next_item_size > 0 && post_residual >= next_item_size {
        -0.3 * (next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        0.2
    } else {
        0.0
    };

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -0.4 } else { 0.0 };

    // New-bin candidate: penalize mildly so tight fits are preferred,
    // but reward it late in the stream or when residuals are large
    let new_bin = if bin_residual == bin_capacity {
        0.6 - 0.4 * progress - 0.3 * (mean_residual / cap).clamp(0.0, 2.0)
    } else {
        0.0
    };

    // Scattered-residual penalty: discourage worsening an already fragmented state
    let frag = 0.15 * ((pr_norm - mean_residual / cap).abs());

    let mut score = base + dead + fit * (0.5 + 0.5 * progress) + lookahead + last_chance + new_bin + frag;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes (0, and small residues) strongly rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class: residual too small for the minimum item size (1..=100 interface).
    // Harmonic thresholds via integer division on post_residual.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // sealed bin, no dead space penalty
    } else if post_residual <= 10 {
        score -= 30.0; // near-perfect class
    } else if post_residual <= 25 {
        score -= 10.0; // usable small class
    } else if post_residual > 50 {
        score += 15.0; // wasteful large leftover when item was small
    }

    // Modulo-arithmetic harmonic classes on post_residual.
    let class = post_residual % 10;
    if class == 0 {
        score -= 5.0; // round residual, likely reusable by common item sizes
    } else if class >= 8 {
        score += 3.0; // awkward residue just above a round number
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            }
            // harmonic class: next item leaves a round residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize leaving mid-size dead space
            score += pr * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count == 0 { 0.0 } else {
            let best_gap = (bin_residual as f64 - item_size as f64).abs();
            best_gap
        };
        // Penalize new bins generally; discount when few bins fit or mean residual is low.
        let mut new_penalty = 120.0;
        if fitting_bins_count == 1 {
            new_penalty -= 70.0;
        }
        if mean_residual < 20.0 {
            new_penalty -= 40.0;
        }
        // Late in stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_penalty += 40.0 * progress;
        score += new_penalty;
        // Empty-bin residual baseline (full capacity) shouldn't look artificially good.
        score += 0.0;
    }

    // Mild preference for tighter existing bins relative to mean residual.
    if bin_residual < bin_capacity {
        score += (mean_residual - pr) * 0.3;
    }

    // Slight pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using existing bins when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 7.0;
    }
    // If next item cannot use the dead space created, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 4.0;
    }

    // Mean residual coupling: bins far from mean residual get mild normalization.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when item is large and no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty so open bins are preferred unless fit is terrible.
        score += 10.0;
        if item_size >= 60 && (fitting_bins_count == 0 || bin_residual - item_size < 5) {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin better serves large upcoming items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect chaining of two items in one bin).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 20.0;
    }

    // Penalize dead space: small post-residual that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates
    // favorably (tighter bins first to consolidate space).
    score += 0.3 * (post_residual as f64 - mean_residual).abs().signum()
        * (post_residual as f64 - mean_residual).abs().min(40.0) * 0.0
        + 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let tight_fit = (bin_capacity - item_size) <= 20;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 30.0;
        if fitting_bins_count <= 1 { penalty -= 22.0; }
        if tight_fit { penalty -= 10.0; }
        if pressure > 0.5 { penalty -= 5.0; }
        score += penalty.max(0.0);
    }

    // Slight preference for bins with larger residual when item is small.
    if item_size <= 30 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (small residuals are fine, big ones are wasted capacity)
    let post = post_residual as f64;
    score += 0.6 * (post / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin strongly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize proportionally to how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
        // If next item is huge, prefer conserving large residuals elsewhere
        if next > 60.0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many fitting bins: slight penalty for wasting choice on a loose fit
    if fitting_bins_count > 3 {
        score += 0.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: when mean residual is high, prefer tightening tight bins
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * (2.0 + mean_residual / 20.0);

    // Time horizon: late in the stream, avoid opening new bins; early, allow exploration
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (10.0 + 40.0 * progress);

    // Slight penalty for opening bins when many are already open
    score += new_bin * 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Early on, prefer tight packing (low post_residual); late, tolerate larger residuals less.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty on very small post-residuals (dead space), smoothed via cubic.
    let dead = norm_pr * norm_pr * norm_pr;
    score += 60.0 * dead * (1.0 - progress);

    // Reward near-perfect fits with a smooth quadratic dip.
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Slight penalty when bin is far below average residual (keep bins balanced).
    let mean_pr = mean_residual - item_size as f64;
    let dev = (pr - mean_pr) / cap;
    score += 10.0 * dev * dev;

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 15.0 * snug * snug;
    }

    // Mild pressure to consolidate as open bins grow.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful" residue classes
    // (multiples of 10 / small values) are more likely to be filled later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual strongly (tight fit).
    score -= (cap - pr.min(cap)) * 0.5;

    // Modulo-10 harmonic class: leftover in {0, 10, 20, ...} aligns with typical item sizes.
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 6.0;
    } else if cls <= 3 || cls >= 7 {
        score += 4.0; // awkward dead space
    }

    // Dead-space penalty: leftover too small for the minimum item (1..100 interface => min 1,
    // but treat < 8 as near-dead since typical min sizes are larger).
    if post_residual < 8 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact harmonic match: post_residual == next_item_size closes bin next step
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit badly.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize when good fitting bins exist
        if fitting_bins_count > 0 && next_item_size > 0 {
            score += 10.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Spread-awareness: avoid over-fragmenting when mean residual is already high.
    if (mean_residual - pr).abs() < 5.0 && open_bins_count > 3 {
        score -= 3.0;
    }

    // Integer-division threshold: bins with residual in [50, 100) are "half-full" workhorses;
    // keep them flexible, slight penalty for dumping large items into them.
    if bin_residual / 2 >= item_size && item_size > 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

