    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit; make the empty bin moderately costly
    // so it wins only when open bins score poorly (large dead-space penalties).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, slightly discourage proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin gets filled again
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * usage;
        } else {
            // next item won't fit here; penalize large dead space relative to next item
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
        // if next item is huge, prefer keeping residual large enough for it
        if next_item_size > post_residual && post_residual < 10 {
            score += 25.0; // tiny dead space is worthless
        }
    }

    // Compare residual against mean residual of open bins
    if post_residual as f64 > mean_residual * 1.5 && open_bins_count > 2 {
        score += 8.0; // avoid leaving this bin far above average residual
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0; // consolidating residual is good
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 35.0 + 25.0 * (1.0 - progress);
        score += penalty;
        // allow new bin if item is big and no open bin fits well
        if item_size > 70 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for filling bins that are already fairly full
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness * tightness;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space that is too small to be useful later
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving a sliver that the next item cannot use
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (item_size as f64) / bin_capacity as f64;
        // Opening a new bin is more acceptable early and for large items
        score += 18.0 * (1.0 - 0.5 * progress) - 10.0 * pressure;
        // If many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean (fill fuller bins)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Mild preference for bins with moderate residual as stream progresses
    let phase = step_index as f64 / (total_items as f64).max(1.0);
    score += phase * (post_residual as f64) * 0.1;

    // Slight penalty for accumulating too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits via non-linear post-residual penalty
    let mut score = (pr * pr) / cap;

    // Smooth polynomial coupling of fit quality with stream progress:
    // early on, waste matters less; later, tight packing dominates.
    let tightness = 1.0 - norm_pr;
    let progress_coupling = tightness * tightness * (0.5 + 2.0 * progress);
    score -= progress_coupling * cap * 0.3;

    // Reward filling bins deeply (large item fraction) with smooth interaction
    score -= norm_item * norm_item * cap * (1.0 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 2.0;
    } else if fitting_bins_count > 1 {
        // mild preference among many candidates toward better fits (already in base)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: reward leaving space compatible with the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        // gaussian-like smooth kernel centered at perfect next-fit
        let kernel = (-diff * diff * 8.0).exp();
        score -= kernel * cap * 0.6 * (1.0 + progress);
        // penalize leaving space that can't hold next item at all
        if pr < ns {
            score += (ns - pr) * 0.2;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * tightness * 3.0;

    // New-bin candidate: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        score = cap * (1.2 - 0.6 * progress) + pr;
        // discount new bin if item is large (hard to place later)
        score -= norm_item * cap * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on coarse
    // capacity fractions are more reusable, reward them.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let eighth = bin_capacity / 8;

    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 15.0; // nearly full, tiny dead space
    } else if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0; // residual on a harmonic class (25/50/75)
    } else if post_residual % fifth == 0 && post_residual > 0 {
        score -= 5.0;
    } else {
        // Penalize residuals in awkward mid-range dead zones
        if post_residual > eighth && post_residual < quarter {
            score += 6.0;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward when next item also lands on a harmonic class with this bin
            if (post_residual - next_item_size) % quarter == 0 {
                score -= 10.0;
            } else if (post_residual - next_item_size) % fifth == 0 {
                score -= 6.0;
            }
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual; penalize proportionally
            let waste = next_item_size as f64 - post_residual as f64;
            score += 3.0 * (waste / cap);
            // If residual is small enough that many items still fit, soften
            if post_residual <= 20 {
                score -= 5.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are fragmented (harmonic mismatch) or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 45.0; // nothing fits, must open
        } else if mean_residual < 15.0 {
            score -= 25.0; // open bins nearly exhausted anyway
        } else if post_residual % quarter == 0 {
            score -= 10.0; // fresh bin starts on harmonic grid
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Mild penalty for residual far from mean (fragmentation avoidance)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small to hold even a minimal item (1..10).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 18.0; // very likely dead space
        } else if post_residual < 30 {
            score += 6.0; // risky gap
        }
    } else {
        score -= 15.0; // perfect fill rewarded
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap blocks the next item: penalize proportionally to how close it is
        score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / next_item_size as f64);
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate more strongly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild tie-break: prefer larger items placed into tighter bins.
    score += 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with the next item is gold ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly fills this bin afterwards: ideal chain.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here too; reward tightness of the pair.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(40.0) * 0.4;
        } else {
            // Next item cannot use this leftover: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(80.0) * 0.45;
        }
    } else {
        // Last item: only current fit matters.
        score -= 10.0;
    }

    // --- Tight fit now is good ---
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // --- Penalize unusable dead space (< 10, the min item size) ---
    if post_residual < 10 {
        score += 8.0;
    }

    // --- Last-chance bin: strongly prefer using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate: only attractive when current bin fits are poor ---
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent fit, better than a terrible one.
        score += 15.0;
        // Fewer open bins -> opening is cheaper; many open bins -> discourage.
        score += open_bins_count as f64 * 0.5;
        // If mean residual of open bins is large, prefer using them.
        score += (mean_residual - 30.0).max(0.0) * 0.4;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 12.0;
        // If next item is huge, a fresh bin is more valuable.
        score -= (next_item_size as f64 / 100.0) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that is too small to be useful later
    // (items are 1..=100, but residual < ~15 is nearly unusable).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for awkward leftovers
            score += 4.0;
        }
    }

    // New-bin candidate logic: only attractive when this bin is a last chance
    // or the fit is bad. Otherwise penalize opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 10.0; // must open a new bin anyway
        } else if post_residual as f64 > mean_residual * 0.6 {
            // current bins have decent room; discourage new bin
            score += 15.0;
        } else {
            score += 5.0;
        }
    } else {
        // Reward using existing bins, more so when bins are scarce relative to need.
        score -= 3.0;
        if fitting_bins_count == 1 {
            // last chance bin: strong incentive to use it
            score -= 20.0;
        }
    }

    // Global state coupling: when mean residual across bins is large,
    // prefer bins that consume more of the surplus.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let residual_pressure = mean_residual / bin_capacity as f64;
    score -= 6.0 * residual_pressure * (1.0 - progress);

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by how many alternatives exist.
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 10.0 * waste_ratio * (fitting_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
