    // Perfect-fit reward via smooth polynomial bump around zero post-residual
    let bump = (-norm_pr * 6.0).exp();
    score -= bump * 25.0;

    // Smooth interaction: post_residual x stream progress (later items prefer tight fits more)
    score += norm_pr * progress * 40.0;

    // Last-chance bonus: smooth sigmoid on fitting_bins_count == 1
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0f64.max(0.0)).abs() * 3.0);
    score -= last_chance * 20.0 * (1.0 - progress);

    // Penalize opening new bins when many bins are open and residual is large
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += openness * norm_pr * 15.0;

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        if diff >= 0.0 {
            score -= (1.0 - diff * diff) * 12.0;
        } else {
            score += diff.abs() * 30.0;
        }
    }

    // Mild penalty for deviating from mean residual (balance bin fullness)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate handling: make empty bin slightly less attractive unless item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 8.0 - large * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

