    } else {
        score -= 10.0; // large gap still useful for future items
    }

    // Modulo arithmetic on post_residual: gaps that match common item-size
    // residue classes (multiples of 10) are more likely reusable.
    if post_residual >= 10 {
        let r = post_residual % 10;
        if r == 0 {
            score -= 25.0; // aligns with typical size granularity
        } else if r <= 2 {
            score += 8.0;  // awkward sliver atop a usable core
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
