        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 40.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small gaps that strand it
            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: slightly worse than a perfect fit,
        // better than a wasteful partial fit.
        score = 60.0 + (post_residual as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin is fine if stream is early and bins are congested
            let progress = step_index as f64 / (total_items.max(1) as f64);
            if progress < 0.3 && open_bins_count > 2 {
