    // Mild preference to fill already-open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "dense" — favor consolidating into it.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
