    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement is ideal — heavily reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tight the chain is
            let chain_waste = post_residual - next_item_size;
            score -= (30.0 - chain_waste as f64).max(0.0);
        } else {
            // Next item won't fit here: penalize leaving a gap that traps it
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 2.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (packing into nearly-full bins), penalize using roomy bins.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave big dead space elsewhere.
    if bin_residual == bin_capacity {
        let waste_avoided = if post_residual > 0 { 0.0 } else { 50.0 };
        score += 80.0 - waste_avoided - (item_size as f64 * 0.5);
    }

    // Early in stream: be slightly more willing to open bins for diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
    score -= 2.0 * mean_tight * (open_bins_count as f64).ln().max(1.0);

    // Penalize opening a new bin when open bins could fit, unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - tightness);
        if fitting_bins_count >= 1 {
            score += 5.0 * (1.0 - tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 1.0 + t * (1.0 - t) * 4.0; // peaks mid-stream
    score *= 0.5 + 0.5 * poly;

    // Penalize dead space more strongly as the stream advances.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 30.0 * (0.3 + t);

    // Reward tight fits.
    score -= (1.0 - dead) * (1.0 - dead) * 12.0;

    // Last-chance bin bonus (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Slight penalty when this bin deviates from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: keep neutral-ish baseline with mild penalty
    // so it only wins when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t);
        score -= 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse granularity of dead space.
    // Classes of width 10 mirror item granularity; dead space below 10 is nearly worthless.
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,          // post_residual < 10: bin is "closed", perfect packing
        1 => score -= 10.0,          // 10..19: can host smallest items
        2 => score -= 6.0,           // 20..29
        3 => score -= 3.0,           // 30..39
        4 => score -= 1.0,           // 40..49
        _ => {}
    }

    // Exact-fit harmonic classes: post_residual that divides cleanly into
    // common item sizes (10/20/25/50 classes) is more reusable.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 8.0; }
        else if post_residual % 25 == 0 { score -= 5.0; }
        else if post_residual % 10 == 0 { score -= 3.0; }
        else if post_residual % 5 == 0 { score -= 1.0; }
    }

    // Coupling with lookahead: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains: exact match is a harmonic-class hit.
            if post_residual == next_item_size { score -= 12.0; }
            else if post_residual - next_item_size < 10 { score -= 6.0; }
            else { score -= 2.0; }
        } else {
            // Post residual cannot host next item: penalize proportionally
            // to how much dead space is stranded.
            let stranded = post_residual as f64 / bin_capacity as f64;
            score += 4.0 * stranded;
        }
    } else {
        // Last item: only exact closure matters.
        if post_residual == 0 { score -= 20.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the stream is early and bin count is low (still worth consolidating).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // A fresh bin is attractive only when no open bin fits well,
        // or when open bins are already crowded (low mean residual).
        score += 12.0 + 10.0 * fit_quality - 8.0 * (1.0 - progress);
        if mean_residual < 15.0 { score -= 6.0; }  // open bins nearly full -> new bin OK
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: if the lookahead item cannot use the leftover gap,
    // this residual is likely wasted -> penalize proportionally to its smallness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 50.0 + 3.0 * waste;
    }

    // Gaps too small for the minimum item size (1) can't occur, but very tiny
    // gaps are still fragile: mild penalty for 1..=5 leftover.
    if post_residual > 0 && post_residual <= 5 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists elsewhere.
    score += 2.0 * open_bins_count as f64;

    // Slight pull toward bins whose residual is close to the mean (avoid
    // fragmenting one big bin while many small ones linger).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: make the empty bin attractive only when the item is
    // large relative to capacity (existing fits would leave big unusable gaps).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * tightness;
        // But if an existing bin is a near-perfect fit, keep using it.
        if post_residual <= 5 && bin_residual == bin_capacity {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match bonus: post_residual close to next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff <= 10.0 {
            score -= 0.8 * (10.0 - diff);
        }
        // Penalize dead space: post_residual nonzero but too small for next item.
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight packing relative to mean residual of open bins.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for filling bins more completely as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: make it mildly unattractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
        // If many open bins but few can fit, allow new bin more readily.
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post residual (wasted space) super-linearly
    let post = post_residual as f64;
    score += 0.35 * (post / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // Reward tight fits strongly
    score -= 12.0 * (1.0 - post / bin_capacity as f64).powi(3);

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward for near-exact chain fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins below mean residual (keep some bins tight, others roomy)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more conservative about filling bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Many open bins: prefer consolidating into existing ones
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless it's a large item
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 60 {
            score -= 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate larger waste slightly; later, punish dead space harder.
    let progress_w = 1.0 + 2.0 * t * t;
    score += 30.0 * x * x * progress_w;

    // Reward near-perfect fits smoothly (small post residual gets extra bonus)
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: if the next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - t);
    } else if next_item_size > 0 {
        // penalize leaving a gap the next item cannot use, scaled by gap size
        score += 10.0 * x * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score that
    // decreases over time only if many bins are already open
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 10.0 * (1.0 - t) - (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild coupling with mean residual: bins deviating from mean residual are
    // slightly penalized (smooth quadratic divergence)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Near-perfect fits (harmonic class r in {1..3}) are excellent
    else if post_residual <= 3 {
        score -= 25.0;
    }
    // Small but awkward dead space (4..9): penalize creating unusable slivers
    else if post_residual < 10 {
        score += 6.0;
    }

    // Harmonic modulo-10 classes on post_residual
    let r = (post_residual % 10) as f64;
    match post_residual % 10 {
        0 => score -= 4.0,          // round residual: reusable
        5 => score -= 2.0,          // half-class
        1 | 2 | 3 => score -= 1.5,  // tight class
        8 | 9 => score += 2.0,      // almost-full but wasteful
        _ => {}
    }
    let _ = r;

    // Lookahead: reward bins that can also host the next item (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 7.0;
            // extra reward if post_residual is a near-multiple of next item
            if post_residual % next_item_size.max(1) <= 2 {
                score -= 3.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Integer-division threshold: bins whose residual is in the top quartile
    // of capacity are "loose" — mildly deprioritize unless nothing else fits
    if bin_residual * 4 >= bin_capacity * 3 && !is_new_bin {
        score += 2.0;
    }

    // New-bin candidate: base penalty grows with number of open bins,
    // but relax it late in the stream when consolidation matters less
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 0.6 * open_bins_count as f64 - 10.0 * progress;
        // if this item cannot fit anywhere else, opening is mandatory
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild capacity-fraction normalization
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that is too small for
    // typical items (1..10) is wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Gaps that can't fit even the lookahead item are also suspect.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward filling bins deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> mild penalty on the empty
    // new-bin candidate so we consolidate into existing bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
        // But if the item fits poorly everywhere, allow a new bin.
        if post_residual < 10 && next_item_size > 0 {
            score -= 20.0;
        }
    } else {
        // Slight preference for tighter existing bins when few are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Early in the stream, be a bit more willing to consolidate (fewer bins);
    // late in the stream, exploit tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0; // next item can still fit here
        } else {
            // dead space relative to next item: penalize small unusable leftovers
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 40.0;
            } else if post_residual < 10 {
                score -= 30.0; // very small dead space is fine (unusable anyway)
            }
        }
    }

    // Prefer tight fits: penalize large post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            score += 150.0; // prefer existing bins when they can fit
        }
    }

    // Early stream: be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..=100; residual smaller than 1 is impossible, but small
    // residuals are hard to fill — add convex penalty as post_residual -> 0
    // only when it's nonzero (perfect fit is ideal).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 8.0 * (10.0 - pr); // tiny slivers are wasted space
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open
    // (consolidation pressure grows with open_bins_count).
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score -= 1.5 * consolidation * tightness;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already "small" — filling it further keeps large residuals free
    // for large future items. Reward using low-residual bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 2.0 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 1.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, avoid opening new bins at all costs;
    // early on, allow exploration of new bins for better long-run packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base attractiveness of a fresh bin.
        let mut new_bin_score = 45.0;
        // Early stream: new bins are cheap to explore.
        new_bin_score -= 20.0 * (1.0 - progress);
        // Many open bins: discourage more bins.
        new_bin_score += 2.0 * (open_bins_count as f64);
        // If the item is large relative to capacity, a fresh bin is fine.
        new_bin_score -= 0.1 * item_size as f64;
        // If nothing else fits well (large post_residual elsewhere), new bin wins.
        score = score.min(new_bin_score);
        score = new_bin_score;
    } else {
        // Existing bins get progressively better relative to new bins over time.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: post residual (lower waste preferred)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let g = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prn * prn * (1.0 + g) - 6.0 * prn * g;

    // Penalize tight fits that leave dead space unusable for typical items
    let dead = (prn * 10.0).tanh();
    score += 8.0 * dead * dead;

    // Reward near-full packing strongly (smooth cubic)
    score -= 20.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0);
        score -= 10.0 * (1.0 - fits / cap) * (1.0 - fits / cap);
        // Penalize if next item barely misses
        if nxt > pr && nxt > 0.0 {
            score += 5.0 * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - g);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap - prn).abs();

    // New-bin candidate: make it moderately attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score = 55.0 - 25.0 * g + 0.3 * it;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod capacity fractions
    let pr = post_residual as i64;
    let q = cap as i64;
    // class 0: perfect fit -> strong reward
    if pr == 0 {
        score -= 60.0;
    } else {
        // dead-space class: residual below min item size (1..=10) is nearly dead
        if pr < 10 {
            score += 25.0;
        }
        // harmonic bucket: how many "typical" item sizes (10..80) could still fit
        let usable = if pr >= 80 { 4 } else if pr >= 50 { 3 } else if pr >= 30 { 2 } else if pr >= 10 { 1 } else { 0 };
        score -= 6.0 * usable as f64;

        // modulo structure: residuals divisible by common item sizes pair well
        let div_bonus = |d: i64| if d > 0 && pr % d == 0 { 4.0 } else { 0.0 };
        score -= div_bonus(10) + div_bonus(20) + div_bonus(25) + div_bonus(50);
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 40.0; // perfect chaining
        } else if ni <= pr {
            score -= 10.0; // chainable
            // integer-division harmony: post_residual / next_item_size >= 2
            if pr / ni.max(1) >= 2 {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here; penalize leaving residual just under it
            if pr > 0 && pr >= ni - 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is huge relative to residuals
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score += 18.0 * (1.0 - tight); // new bins penalized when open bins are roomy
        if item_size >= 60 {
            score -= 8.0; // big items may warrant fresh bins
        }
        if next_item_size > 0 && (next_item_size as i64) == q {
            score -= 20.0; // next item is full-capacity: keep bins clean
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // by any plausible future item are heavily penalized.
    let dead_threshold = 12u32; // smallest realistic item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fill is maximally rewarded.
        score -= 150.0;
    }

    // Reward tight fits: item consuming a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_threshold {
            score -= 40.0;
        } else {
            score += 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this bin's leftover; leftover is likely dead space.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mildly discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 2.0 * progress);

    // New-bin candidate: make the empty bin attractive only when the item
    // would leave a large unusable gap in an existing bin, or when the item
    // is huge and mean residual is small.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < dead_threshold;
        let huge_item = item_size as f64 > mean_residual * 0.95 && mean_residual > 0.0;
        if bad_fit || (huge_item && fitting_bins_count <= 2) {
            score -= 120.0;
        } else {
            score += 30.0 + mean_residual * 0.3;
        }
    }

    // Mild penalty for leaving large leftovers that exceed typical item sizes
    // less often usable (fragmentation coupling with mean residual).
    if post_residual as f64 > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual - 20.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chaining), scaled by lookahead size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match: big bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits too but with small slack: mild bonus
        else if post_residual >= next_item_size {
            score -= 8.0;
        }
        // Next item cannot fit here: penalize leaving large dead space
        else {
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit only
        score += 0.1 * post_residual as f64;
    }

    // Reward tight fits relative to mean residual across open bins
    if (post_residual as f64) < mean_residual {
        score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current item creates
    // an exact chain with the next item or all open fits are terrible.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && post_residual == next_item_size { 20.0 } else { 0.0 };
        score += 30.0 - chain_bonus;
    }

    // Slight preference for consolidating into fewer bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: scale post_residual by fill fraction.
    let fill = item_size as f64 / cap;
    score -= 0.6 * (cap - post) * fill;

    // Penalize small unusable dead space (< 10) strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Prefer bins with residual below mean residual (tighter bins first).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when current bin fits are loose
    // or few bins fit the item; discourage opening bins when a good fit exists.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            let best_gap = (bin_residual - item_size) as f64;
            best_gap / cap
        } else {
            1.0
        };
        let horizon = step_index as f64 / total_items.max(1) as f64;
        // Open new bin if item is large (leaves little residual anyway)
        // and early in stream; penalize later since open bins suffice.
        score -= 12.0 * fill * (1.0 - horizon);
        score += 10.0 * (1.0 - tightness);
        if fitting_bins_count <= 2 {
            score -= 5.0;
        }
        score += 0.2 * open_bins_count as f64;
    }

    // Mild time pressure: later in stream, prefer filling existing bins.
    score += 4.0 * (step_index as f64 / total_items.max(1) as f64) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, moderate leftovers are acceptable (bins stay flexible);
    // late in the stream, dead space becomes costly.
    let mut score = post * (1.0 + 2.0 * progress) + 0.012 * post * post;

    // Cubic smoothing term: strongly penalize large unusable gaps,
    // mildly reward tight fits.
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * norm_post;

    // Dead-space trap: residual that no plausible item (1..=100) can use well.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 1.5; // tiny crumbs are wasted capacity
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin (subtract to reward).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving a residual that exactly invites a bad
    // next-item fit; reward residuals that can host the next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 4.0 - 0.05 * slack; // next item fits: good
        } else {
            score += 2.0; // next item won't fit here: mild penalty
        }
    }

    // New-bin candidate handling: an empty bin has huge post_residual,
    // so the quadratic core already discourages it, but give it an
    // explicit penalty that shrinks as the stream progresses (opening
    // fresh bins is more acceptable late when open bins are fragmented).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.6 * progress);
    }

    // Fragmentation pressure: many open bins with high mean residual ->
    // prefer consolidating into existing bins (penalize new-bin spread).
    let mean_res_norm = mean_residual / cap;
    score += 5.0 * mean_res_norm * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fit classes are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect packing
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 20.0;
    }

    // Dead space penalty: leftover that no plausible item can use.
    if pr > 0 && pr < 10 {
        score += 90.0; // unusable sliver
    }

    // Modulo-10 harmonic coupling: leftover divisible by 10 pairs well with
    // item sizes drawn on a 10-grid; reward alignment, penalize misalignment.
    let leftover_class = pr % 10;
    if leftover_class == 0 {
        score -= 25.0;
    } else if leftover_class >= 8 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= (30.0 * (1.0 - slack / 50.0)).max(-30.0).min(0.0);
            if slack <= 10.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: leftover is dead for the lookahead
            score += (next_item_size - pr) as f64 * 0.6;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
        if pr <= 15 {
            score -= 40.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when stream is early and
    // open bins are scarce; allow it late when consolidation is done.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        if open_bins_count > 0 && pr >= 50 {
            score -= 20.0; // fresh bin still useful as long-term reservoir
        }
        if next_item_size > 0 && next_item_size >= 70 && item_size >= 70 {
            score -= 35.0; // two big items coming: fresh bin justified
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // packing into below-mean-residual bins preserves larger spaces.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 60.0;

    // Mild tightness reward relative to capacity fractions.
    let frac = item_size as f64 / bin_capacity as f64;
    score -= frac * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 35.0;
        } else if post_residual <= 40 {
            score += 15.0;
        }
    } else {
        score -= 50.0; // perfect fill, highly rewarded
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Pressure from number of open bins: discourage proliferation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item could use the post residual, soften the penalty.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // residual becomes dead space for the known next item
    }

    // New-bin candidate: neutral baseline, slightly penalized so real bins
    // are preferred unless they create severe dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: prefer closing bins out (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Mean residual coupling: if average residual is already large,
    // avoid adding to fragmented space.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
    } else {
        // Last item: pure tightest-fit
        score -= 20.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Slight preference for filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize unless residual would be well-used by lookahead
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space that nothing (size >= 1) can ever use well: tiny post_residual is fine,
    // but mid-range post_residual is wasted unless next item fits.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            // next item fits exactly into the leftover: strong reward
            score -= 12.0;
            score -= 0.15 * (next_item_size as f64);
        } else {
            // leftover unusable by next item: penalize proportionally to waste
            score += 0.35 * post_residual as f64;
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating into
    // bins that are already relatively full (low residual).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins (penalize
    // cramming); late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * (bin_residual as f64 - post_residual as f64);
    score -= progress * 8.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual;
        if poor_fit || fitting_bins_count <= 1 {
            score -= 6.0 + 0.1 * item_size as f64;
        } else {
            // opening new bins wastefully is bad
            score += 10.0 + 0.2 * mean_residual;
        }
    }

    // Mild preference for bins whose residual is closest to item size (perfect fill).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    // Non-linear coupling: exponential penalty for leaving residuals in the awkward
    // 1..=9 zone (few item sizes can use them).
    if post_residual >= 1 && post_residual <= 9 {
        score += 9.0_f64.powf(post_residual as f64 / 9.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: quadratic in post_residual (waste grows superlinearly).
    let mut score = post * post / cap;

    // Smooth coupling: waste penalized more as stream progresses.
    score *= 0.5 + progress;

    // Reward tight fits (small post_residual) with a saturating bonus.
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * cap * 0.35;

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= (1.0 - slack_after_next / cap) * 12.0;
        } else {
            // Penalize leaving a residual that barely misses the next item.
            let miss = (nxt - post) / cap;
            score += miss * miss * 30.0;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins are open
    // and mean residual is high (existing space should be used).
    if is_new_bin {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln().max(0.0);
        score += 18.0 + 0.6 * mean_residual * (0.5 + progress) + 4.0 * crowding;
        // Late in the stream, consolidating is even more important.
        score += 10.0 * progress;
    } else {
        // Slight preference for bins below mean residual (balance residuals).
        score += ((bin_residual as f64 - mean_residual) / cap) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead classes" (cannot fit the minimum item 1..=10 comfortably) are
    // penalized less if they are already small; large stranded residuals hurt.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score -= 20.0; // tiny dead space is acceptable waste
    } else if post_residual >= dead_threshold && post_residual < 2 * dead_threshold {
        score += 5.0; // awkward mid class
    }

    // Modulo-class coupling: residual divisible by common item sizes (10/20/25/50)
    // is more reusable — reward such harmonic residuals.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize leftover size
            score += post_residual as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is huge
    // relative to current residuals (i.e., all open bins would be badly split).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        // open a new bin only when mean residual is small and item is large
        let bias = 30.0 + 50.0 * (1.0 - tightness) - 40.0 * mean_tight;
        score += bias.max(0.0);
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Prefer bins below mean residual (consolidating emptier bins)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 10.0; // next item can't use this bin's leftover
        }
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins
    // (penalize opening new bins or spreading out).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64).max(0.001);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins moderately unattractive unless
    // the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // allow new bin when item is large relative to capacity
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.1;

    // Mild stream-progression term: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fill bonus: perfect fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // --- 2-step lookahead matching ---
    // Does the NEXT item fit perfectly into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            // Perfect 2-chain: this placement sets up an exact next fit.
            score -= 400.0;
        } else if gap <= 10.0 {
            score -= 150.0 - gap * 8.0;
        } else {
            // Next item fits but leaves another gap: mild reward, decaying.
            score -= (60.0 / (1.0 + gap * 0.15)).max(0.0);
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow into this bin: penalize proportionally
        // to how "wasted" the post-residual is relative to the next item.
        let waste = (post_residual as f64) / (next_item_size as f64);
        score += 30.0 * (1.0 - waste.min(1.0));
    }

    // Small post-residuals are dead space unless they enable a chain.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && next_item_size == post_residual) {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Prefer fuller bins overall (low residual = high priority).
    score += (bin_residual as f64) * 0.3;

    // Late in the stream, avoid opening new bins: penalize the new-bin
    // candidate (residual == capacity) increasingly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 + 80.0 * progress;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
        // Extra reward for near-exact pairing.
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - pair_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual unusable by next item: penalize proportionally.
        score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Time horizon: early in the stream, prefer consolidation; late, be flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * tight;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild penalty for opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But allow new bin if it would create a perfect fit for the next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins that leave residuals divisible into useful chunks.
    if post_residual >= 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic in post-residual fraction, modulated by progress
    score += 6.0 * fit_ratio * fit_ratio * (1.0 - progress) - 4.0 * fit_ratio * progress;

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        score += 10.0 * gap * gap;
        // Reward exact-ish fit for the lookahead
        let tight = 1.0 - (pr - nx).abs() / cap;
        score -= 8.0 * tight * tight * tight;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize mildly, less so when residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (mean_residual / cap).min(1.0);
    }

    // Coupling with mean residual: prefer bins deviating from mean late in stream
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * progress - 2.0 * dev * (1.0 - progress);

    // Small smooth reward for larger fill fraction
    score -= 2.0 * (item_size as f64 / cap) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes on post_residual
    let pr = post_residual;
    let class = pr % 10; // dead-space granularity class
    // Penalize awkward leftover classes (1,2,3 are nearly dead space)
    let class_penalty = match class {
        0 => -12.0,           // perfect fit class
        1 | 2 => 14.0,        // unusable slivers
        3 | 4 => 8.0,
        5 => -4.0,            // half-slots still useful
        6 | 7 => 2.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Reward tight fits: fraction of bin consumed
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 20.0 * fill * fill; // quadratic preference for fuller bins

    // Lookahead coupling: harmonic relation between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as u32;
        if nxt > pr {
            // next item won't fit here: this bin becomes dead space
            score += 10.0 + 0.15 * (pr as f64);
        } else {
            // exact modular resonance: next item leaves another perfect class
            if (pr - nxt) % 10 == 0 {
                score -= 10.0;
            }
            score -= 0.1 * (nxt as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item is huge relative to mean residual, opening fresh may be right
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 35.0;
        }
    }

    // Stream progression: early on, be conservative about dead space; later, pack aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are toxic.
    if post_residual >= 1 && post_residual <= 12 {
        score += 30.0 * (13.0 - post_residual as f64);
    }
    // Sweet spot: post_residual large enough to host typical small items.
    if post_residual >= 20 && post_residual <= 45 {
        score -= 8.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score -= 35.0 * desperation;
        // Late in stream, prefer reusing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item could use this bin's post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Next item won't fit here; penalize wasted space relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize large post residuals (dead space) relative to mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Slight preference for tighter bins when many bins are open.
    score += (bin_residual as f64) * (0.05 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that is too small to fit typical future items
    // (dead space < 10 is unusable; < next_item_size is unusable for the next item).
    if post_residual > 0 {
        let min_future = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
        if (post_residual as u64) < (min_future as u64) {
            score += 18.0;
        } else if (post_residual as u64) < (next_item_size as u64) && next_item_size > 0 {
            score += 8.0;
        }
    }

    // Lookahead synergy: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = if next_item_size == post_residual { 20.0 } else { 6.0 };
        score -= perfect;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; slight penalty unless residual is large.
        score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.05;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // existing bins would leave large unusable residuals or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin grows slightly with stream progress.
        score += 14.0 + 10.0 * progress;
        // If many bins are open with scattered residuals, a fresh bin is more valuable.
        score -= (open_bins_count as f64).sqrt() * 1.5;
        // If the item perfectly splits the bin, a new bin is fine.
        if item_size * 2 == bin_capacity {
            score -= 10.0;
        }
        // If next item pairs with the leftover of a fresh bin, encourage it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    // Global residual dispersion: if mean residual is high, prefer consolidating
    // into existing bins (avoid fragmenting space across many bins).
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= mean_gap * 0.10;
    } else {
        score += (-mean_gap) * 0.05;
    }

    // Mild preference for bins with residuals close to item_size (best-fit flavor).
    let fit_gap = (bin_residual - item_size) as f64;
    score += (fit_gap * fit_gap) / (bin_capacity as f64 * bin_capacity as f64) * 8.0;

    // Late-stream pressure: as the stream nears its end, avoid opening bins
    // that will likely remain nearly empty.
    let remaining = total_items.saturating_sub(step_index);
    if remaining < 5 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, quadratically (dead space is worse than linear).
    let mut score = pr + 40.0 * x * x * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits less aggressively (keep bins flexible);
    // late in the stream, push hard toward minimal residuals.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= (1.0 + progress_weight * (1.0 - x) * (1.0 - x));

    // Reward filling a bin nearly exactly, smoothly via a gaussian-like bump around x≈0.
    let tight_fit_bonus = 60.0 * (-(x * x) / 0.02_f64.max(x * x + 1e-9)).exp();
    score -= tight_fit_bonus * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins (penalize new-bin tendency).
    let open_norm = open_bins_count as f64;
    score += 0.15 * open_norm * (1.0 - progress);

    // Mean residual coupling: if average residual is large, tolerate looser fits
    // (bins are fragmented anyway); if small, demand tight packing.
    let mr = mean_residual / cap;
    score *= 0.85 + 0.3 * mr * (1.0 - x);

    // Lookahead: if next item fits snugly into post_residual, reward this placement.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let gap = (pr - ns) / cap;
            score -= 30.0 * (-(gap * gap) / 0.01).exp() * (0.5 + progress);
        } else {
            // next item won't fit here: mild penalty scaled by overflow amount
            score += 8.0 * ((ns - pr) / cap);
        }
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space buckets in quarters of capacity.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4
    // Penalize mid-size dead space classes (hard to fill later), reward near-full bins.
    match class {
        0 => score -= 8.0,                       // perfect fit, nearly no waste
        1 => score -= 4.0,                       // small usable gap
        2 => score += 6.0,                       // awkward half-ish gap
        3 => score += 3.0,                       // moderate gap
        _ => {}                                  // large residual, bin still flexible
    }

    // Modular coupling: if post_residual aligns with typical item sizes, gap is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap == 0 {
            score -= 15.0;
        } else if next_gap <= 10 {
            score -= 8.0;
        } else {
            score -= (next_gap.min(bin_capacity)) as f64 * 0.05;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize slightly, more if it's large.
        score += (next_item_size.min(bin_capacity)) as f64 * 0.08;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if next_item_size > 0 { (bin_capacity - item_size).saturating_sub(next_item_size) } else { bin_capacity - item_size };
        score += 5.0 + (open_bins_count.min(20) as f64) * 0.2;
        if best_possible <= 10 {
            score -= 12.0; // new bin would be nearly perfectly packed with the lookahead
        }
    }

    // Progress-based mild pressure to consolidate late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual * 0.05);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead-space gaps (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bins mildly,
    // but allow it if this bin would leave a bad gap
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if post_residual < 20 && post_residual > 0 {
            score -= 50.0; // actually a new bin here avoids dead space elsewhere? no: new bin leaves full residual
            score += 50.0;
        }
    }

    // Open-bins pressure: more open bins -> prefer consolidating into existing bins
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 10.0;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 25.0;
    }

    // If post residual exactly matches next item, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Late in stream: avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    // Prefer bins whose residual is close to mean (balanced usage)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match with the next item: heavily reward (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    }

    // Post-residual large enough for next item: mild reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
    }

    // Dead space: small nonzero post_residual that cannot fit next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 15.0 * deadness;
    }

    // Reward exact fill (waste-free bin)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize tiny unusable leftovers generally
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin before opening a new bin: reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if lookahead matches a fresh bin well, allow it
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
        // Late in the stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual waste).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64 / bin_capacity as f64) * 20.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys room for the next item: penalize proportionally.
        score += 15.0;
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating small unusable dead space (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // New-bin candidate: penalize opening a new bin when decent open bins exist,
    // but allow it when mean residual is large (open bins are fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score += 20.0 + 25.0 * (1.0 - progress) - fragmentation.min(40.0);
        // Late in the stream, prefer consolidating into open bins.
        if progress > 0.8 {
            score += 25.0;
        }
        // If no open bin fits (this call is the fallback), make new bin attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mildly prefer bins whose residual deviates favorably from the mean
    // (pack into already-small bins to consolidate large residuals elsewhere).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Slight preference for more-filled bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let x = (pr / cap).clamp(0.0, 1.0);
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes large residuals smoothly
    let mut score = pr * (1.0 + 0.35 * progress) + 18.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - x).powi(3) * (8.0 + 22.0 * progress);

    // Penalize dead space relative to mean residual of open bins.
    score += ((pr as f64 - mean_residual) / cap).clamp(-1.0, 1.0) * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= (1.0 - gap) * 25.0;
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // New empty bin candidate: penalize mildly, more so early when open bins exist.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score += 30.0 * (1.0 + early * (open_bins_count as f64).min(10.0) * 0.15);
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic class logic: classify post_residual into dead-space classes
    // via integer division thresholds. Residuals that cannot host the
    // smallest plausible item (<=10) are dead space; penalize heavily.
    let dead_class = post_residual / 10; // integer division: 0 => dead space
    score += (10 - dead_class.min(10)) as f64 * 4.0;

    // Modulo coupling: residuals that are near-capacity fractions
    // (25/50/75) are reusable "harmonic" slots; reward proximity.
    for h in [25u32, 50, 75].iter() {
        let d = (post_residual as i64 - *h as i64).abs();
        if d <= 8 {
            score -= 12.0 - d as f64;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 5 {
            score -= 18.0;
        }
        // Harmonic pairing: next item leaves another harmonic residual
        for h in [10u32, 20, 25, 50].iter() {
            if slack == *h {
                score -= 10.0;
            }
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: mild penalty for
        // creating stranded space, scaled by how stranded it is.
        score += (next_item_size.min(post_residual.max(1)) as f64) * 0.05 + 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open
    // bin offers a decent fit. Base new-bin score near mean residual,
    // penalized when open bins exist with good fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count > 0 {
            score += 15.0 + (post_residual as f64 - mean_residual).abs() * 0.1;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // Prefer fuller bins slightly: normalize by mean residual.
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Many open bins: encourage closing out nearly-full bins.
    if open_bins_count > 4 && post_residual <= 15 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 && post_residual < 25 {
        score += 20.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 6.0;

    // Open-bin pressure: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 22.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space confirmed by lookahead
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 18.0 + pressure * 0.8;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    }

    // Slight preference for bins below mean residual (less-filled bins get used).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    }

    // Next item cannot follow: penalize proportionally to wasted potential.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals relative to min item size (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Early in stream, be more willing to open new bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full usage nonlinearly
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to hold typical items (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly or well in the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty for wasting a large residual
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // and would leave a very tight residual in existing bins is impossible to judge,
    // so penalize opening a new bin mildly, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // but if item is huge (>70% capacity), a fresh bin is often good
        if fill > 0.7 {
            score -= 45.0;
        }
    }

    // Coupling with global state: prefer bins whose residual is below the mean
    // (concentrate filling in already-partially-used bins)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Early in the stream, be slightly more willing to spread out (keep residuals flexible);
    // late in the stream, pack tightly.
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Quadratic penalty on wasted space, amplified by stream progress
    score += (post / cap) * (post / cap) * cap * (0.5 + progress);

    // Reward tight fits
    score -= item_size as f64 * (1.0 - post / cap) * 0.3;

    // Penalize creating dead space below smallest plausible item when many bins exist
    let tiny = post / cap * (1.0 - progress);
    score += tiny * 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post-residual fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= nxt * (0.4 + 0.4 * progress);
        } else {
            score += (nxt - post) * 0.2;
        }
    }

    // Mild preference for bins below mean residual (balancing)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Smooth new-bin bias: opening a bin early is cheap, later costly
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * progress * progress - open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size in 1..=100 mean
    // residuals divisible by common item sizes (5,10,20,25,50) are reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus -= 60.0; // perfect fit
    } else if pr % 50 == 0 {
        bonus -= 40.0;
    } else if pr % 25 == 0 {
        bonus -= 30.0;
    } else if pr % 20 == 0 || pr % 10 == 0 {
        bonus -= 22.0;
    } else if pr % 5 == 0 {
        bonus -= 12.0;
    }
    score += bonus;

    // Dead-space penalty: small odd residuals are hard to fill.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact or near-exact chain fit is gold
            let gap = pr - next_item_size;
            if gap == 0 { score -= 55.0; }
            else if gap <= 10 { score -= 30.0; }
            else { score -= 10.0 * (1.0 - gap as f64 / 100.0); }
        } else {
            score += 12.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter fits (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: neutral baseline, penalize opening new bins
    // unless the current stream is early or residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open a new bin when existing mean residual is small (fragmented)
        // or very late in the stream with many bins (avoid churn)
        let mut nb = 45.0;
        if fragmentation < 0.15 { nb -= 55.0; }
        if fragmentation > 0.5 { nb += 30.0; }
        if progress < 0.1 { nb -= 10.0; }
        if open_bins_count > 50 { nb += 15.0; }
        score += nb;
    }

    // Mild tie-break: prefer bins whose residual is close to mean (balance).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for fuller bins overall (tight packing).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Dead space relative to capacity: penalize large leftover proportionally.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize if next item cannot use the leftover gap (dead space for the future).
    if next_item_size > post_residual && post_residual > 0 {
        score += 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins, but only mildly
    // so tight fits still win.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: prefer bins with residual below mean (tighter bins),
    // pushing consolidation toward emptier bins when appropriate.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: neutral base so it wins only when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening a new bin is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 500.0;
        } else {
            score -= 150.0 / (gap as f64).sqrt();
        }
        // Penalize if next item cannot fit in the post-residual (dead end).
        if post_residual < next_item_size {
            score += 50.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual: prefer tighter (below-mean) bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 100.0 * progress;
    }

    // Slight penalty for wasting large residuals on small items.
    score += (item_size as f64) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is nearly dead space
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 10.0; // residual that can still host small items
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty if we waste space it could use elsewhere
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fit_ratio;

    // Many open bins: encourage closing them out (use bins with small residuals).
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good "filler" target.
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // New empty bin candidate: only attractive when nothing fits well
    // (item is large relative to typical residuals or no tight fit exists).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual;
        let desperate = fitting_bins_count <= 1;
        if large_item || desperate {
            score -= 10.0 + 0.2 * item_size as f64;
        } else {
            score += 60.0; // discourage opening bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters more (long horizon ahead); later, mild waste is acceptable.
    let horizon_weight = 1.0 + 2.0 * (1.0 - progress) * (1.0 - progress);
    score *= horizon_weight;

    // Penalize dead space quadratically when it can't fit the next item (smooth term)
    let next_fits = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += 60.0 * next_fits;

    // Reward post-residual matching next item size (smooth Gaussian-like coupling)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (-20.0 * diff * diff).exp();
    }

    // Smooth dead-space penalty: unusable small residuals penalized super-linearly
    let unusable = (norm_pr - 0.1).max(0.0);
    score += 40.0 * unusable * unusable;

    // Last-chance bonus: only one bin fits, strongly encourage using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    // Slight pull toward mean residual to balance load across bins
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening new bins unless current residuals are poor
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 30.0 * (1.0 - mean_norm) * (1.0 - mean_norm);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue bucket does the leftover fall into?
    let pr = post_residual;
    let class = pr / 10; // integer-division threshold classes: 0..10

    // Small leftovers (< 10) are dead space: strong penalty.
    if class == 0 && pr > 0 {
        score += 25.0;
    }
    // Perfect fit: big reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Class-based dead-space weighting: leftovers in awkward bands get graded penalties.
    match class {
        1 | 2 => score += 6.0,           // 10..29: hard to fill with typical items
        3 | 4 => score += 1.0,           // 30..49: moderate
        5 | 6 => score -= 3.0,           // 50..69: good future capacity
        7 | 8 => score -= 5.0,           // 70..89: very reusable
        _ => {}
    }

    // Lookahead coupling: does post_residual accommodate the next item's harmonic class?
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            // Reward a residual that exactly chains into the next item (mod-10 class match).
            if (post_residual % 10) == (next_item_size % 10) && post_residual == next_item_size {
                score -= 20.0;
            }
            score -= 8.0;
        } else {
            // Next item cannot fit here; penalize slightly to prefer bins that chain.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it neutral-ish; only prefer it when residuals
    // across open bins are already tight (mean residual low) and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // Prefer opening a fresh bin for large items late in the stream when open bins are fragmented.
        if item_frac > 0.6 && mean_residual < item_size as f64 {
            score -= 10.0;
        } else {
            score += 12.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild preference to keep mean residual spread balanced: avoid dumping into the
    // largest-residual bin when many bins are open.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual * 1.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are tiny relative to the item
    // size distribution are effectively unusable -> extra penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0; // near-full but wasted slivers
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: mildly discourage scattering across many bins,
    // pushing consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item would fit into the resulting residual,
    // reward this placement (keeps bins chain-fillable).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Slight preference to fill bins below mean residual (balance avoidance
    // of many half-empty bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate (empty bin) should only win when existing fits are bad:
    // its large post_residual already raises score; add a mild extra tax.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use leftover space: penalize dead space growth
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Relative to mean residual: placing into a bin with residual below mean
    // is good (keeps big holes available); above mean is worse.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // Last-chance bonus: only one bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mild preference for consolidating into few bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good, but avoid tiny dead space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here after placement; mild penalty scaled by waste
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 2.0 * pressure * (1.0 - progress);

    // Prefer bins below mean residual (keeps residuals balanced).
    score += 0.5 * (bin_residual as f64 - mean_residual).signum()
        * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);

    // New-bin candidate: penalize unless current fit is poor or bin is nearly full elsewhere.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && open_bins_count > 0 {
            score -= 10.0;
        } else {
            score += 8.0 + 5.0 * (1.0 - progress);
        }
    }

    // Slight bonus for placing large items early (first-fit-decreasing flavor).
    score -= 0.05 * item_size as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;
    let item_frac = item_size as f64 / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // for leaving dead space that is hard to reuse.
    let mut score = post + 30.0 * post_frac * post_frac;

    // Smooth coupling: dead space matters more as the stream progresses
    // (fewer future items to fill it), realized as a smooth multiplicative term.
    score += 20.0 * post_frac * progress * (1.0 - progress + 0.5);

    // Reward tight fits: small post_residual relative to item size.
    score -= 15.0 * item_frac * (1.0 - post_frac);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, but reward it when
    // the item fits poorly everywhere (large post_residual in existing bins)
    // or when open bins are already crowded on average.
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).max(0.0).min(1.0);
        score += 12.0 - 8.0 * crowding - 5.0 * (1.0 - progress);
        // If the item would leave a big residual in existing bins, new bin is fine.
        score -= 10.0 * (1.0 - post_frac.min(1.0));
    } else {
        // Slight preference for reusing bins over opening new ones.
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 20.0);
    }

    // Mild normalization by number of open bins to discourage bin proliferation.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into coarse "harmonic" bands of capacity (quarters / thirds / eighths).
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;
    let eighth = (bin_capacity / 8) as f64;

    // Perfect fit: zero or tiny post-residual gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 45.0;
    }

    // Reward when the leftover falls into a "useful" harmonic class:
    // leftover that is at least an eighth of capacity can still host small items.
    if post_residual >= bin_capacity / 8 {
        score -= 10.0 + (pr / cap) * 10.0;
    } else {
        // Dead-space penalty for unusable slivers.
        score += 15.0;
    }

    // Modulo-arithmetic class logic: leftover that is a multiple of common
    // small item sizes (or divides capacity cleanly) is more reusable.
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 12.0; // exact divisor of capacity: harmonic class A
        } else if post_residual % 10 == 0 {
            score -= 8.0;  // multiple of the typical item quantum
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0;  // awkward leftover
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 20.0 - (slack_after_next as f64) * 0.15;
            // Harmonic match: next item leaves another divisor-class leftover
            if slack_after_next > 0 && bin_capacity % slack_after_next == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover; mildly penalize.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + (item_size as f64 / bin_residual as f64) * 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when the current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / cap;
        // A new bin is good for large items (good fill ratio) especially early on.
        score = 40.0 - fit_quality * 55.0 + progress * 20.0 + (open_bins_count as f64) * 1.5;
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if post_residual > 0 && post_residual < bin_capacity / 8 {
            score += 10.0; // new bin would be left with a sliver after this item
        }
    }

    // Mild pressure against accumulating many half-empty bins.
    if mean_residual > cap * 0.5 && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..~10)
    // are worthless; gaps that can't fit the known next item are also suspect.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // can't host the lookahead item
        } else {
            // Reward leaving a gap that exactly or nearly fits the next item
            if next_item_size > 0 && post_residual >= next_item_size {
                let slack = (post_residual - next_item_size) as f64;
                score -= (10.0 / (1.0 + slack)).min(8.0);
            }
            // Reward tight fits overall
            score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spawning new bins when the stream is early/mid
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure that grows with open bins
        score += 25.0 + 8.0 * (open_bins_count as f64) * (1.0 - progress * 0.5);
        // But allow opening if all existing fits would leave tiny dead gaps
        if post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins
        score -= 2.0 + (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates favorably from the mean (larger residual = easier to fill)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 800.0; // next item fits perfectly in the leftover space
        } else {
            score += diff * 1.5;
        }
        // Penalize leaving residual slightly larger than next item (dead space trap)
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0;
        }
        // Reward residuals that can still host typical future items
        if post_residual >= next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 200.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New empty bin candidate: penalize unless nothing fits well
    if bin_residual == bin_capacity {
        score += 300.0;
        // Allow new bin when lookahead item is large and residual would be tiny
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 350.0;
        }
    }

    // Prefer consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
