pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 + t) - 0.5 * x * t + 0.25 * x * x * x * (1.0 - t);
    score += 40.0 * poly;
    // reward tight fits more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * t);
    // penalize dead space relative to mean residual
    score += 0.3 * (pr as f64 - mean_residual).max(0.0);
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size { (post_residual - next_item_size) as f64 } else { 0.0 };
        score -= 0.2 * gap / cap;
    } else {
        score += 5.0 * x;
    }
    // slight pressure against proliferating bins
    score += 0.05 * open_bins_count as f64 * x;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual mod small integers reveal "nice" leftover sizes
    let pr = post_residual;
    let m4 = (pr % 4) as f64;
    let m5 = (pr % 5) as f64;
    let m10 = (pr % 10) as f64;
    let m20 = (pr % 20) as f64;

    // Reward residuals that are multiples of common item sizes (divisible leftovers)
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    } else {
        // Perfect fit is best
        score -= 25.0;
    }

    // Penalize awkward tiny dead space (unusable remnants)
    if pr > 0 && pr < 10 {
        score += 8.0;
    }
    // Modulo-based penalty: leftover far from any harmonic class
    score += (m4 * m4 + m5 * m5 + m10 * m10) * 0.05;

    // Integer-division thresholds on post_residual
    let q = pr / 25; // quarter classes
    match q {
        0 => score += 2.0,   // <25: nearly dead
        1 => score -= 1.0,   // 25..49
        2 => score -= 2.0,   // 50..74
        _ => score -= 3.0,   // >=75: very reusable
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 5.0;
            // Harmonic bonus: next item lands exactly on a class boundary
            if (pr - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer opening fresh bin only if all open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 { next_item_size > pr } else { true };
        if pr < 10 && poor_fit {
            score -= 10.0 + 5.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild pressure to close bins when many are open
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 5.0; // roomy leftover is reusable
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 80.0;
    }

    // Reward tight fits generally (post_residual close to 0 relative to item).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits into post_residual, reward leaving that space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover can't host next item; mild penalty proportional to gap
        score += 3.0;
    }

    // Prefer bins whose residual is above mean (keep balanced bins usable).
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 6.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins
    // score poorly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= item_size / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 25.0 - chain_waste as f64;
            } else {
                score += chain_waste as f64 * 0.3;
            }
        } else {
            // next item won't fit here: penalize dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for filling bins as stream progresses (reduce bin count late)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual waste, especially unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with least waste.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
            // Extra reward if next item nearly fills the leftover space.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize leaving large stranded space.
            score += 0.15 * (post_residual as f64 - next_item_size as f64);
        }
    } else {
        // Last item of stream: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Global state: if mean residual is high, encourage filling existing bins
    // rather than spreading; if low, opening fresh bins is less costly.
    let mr = mean_residual;
    if mr > 40.0 {
        score -= 5.0;
    } else if mr < 15.0 {
        score += 4.0;
    }

    // Many open bins: discourage adding waste to any of them, favor consolidation.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more tolerant of imperfect fits
    // (keep flexibility); late in stream, prioritize minimizing waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * progress * tightness;

    // New-bin candidate: prefer it only when no open bin fits well
    // (handled implicitly by penalties above), but add a mild opening cost.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Exception: early stream with few bins — opening is cheap.
        if open_bins_count < 3 && progress < 0.3 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: post residual, normalized and polynomially shaped.
    let x = (pr / cap).clamp(0.0, 1.0);
    let mut score = 100.0 * (x * x * (3.0 - 2.0 * x)); // smoothstep: reward tight fits

    // Non-linear coupling of fill fraction with stream progress:
    // later in stream, favor packing into existing bins more aggressively.
    let fill = 1.0 - x;
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Penalty if residual becomes a "dead zone" relative to plausible item sizes.
    let dead = (x / (0.5 + 0.5 * progress)).clamp(0.0, 1.0);
    score += 25.0 * dead * dead * dead;

    // Lookahead coupling: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let g = (gap / cap).clamp(0.0, 1.0);
            score -= 30.0 * g * (1.0 - progress);
        } else {
            score += 10.0 * nx * fit_frac;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: empty bin gets a moderate baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that cannot pair with typical items
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in "awkward" harmonic bands (small primes / odd classes)
    let class = post_residual % 10;
    let awkward = match class {
        1 | 2 | 3 | 6 | 7 => 1.0,
        _ => 0.0,
    };
    score += awkward * 6.0;

    // Reward tight fits: post_residual small relative to capacity
    if post_residual <= bin_capacity / 10 {
        score -= 12.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward leaving room usable by the next item, scaled by leftover quality
            let rem = post_residual - next_item_size;
            score -= 8.0 - (rem as f64).min(20.0) * 0.2;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr / cap) * 6.0;
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, slightly worse than a decent fit
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (pr / cap) * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // prefer fresh bin for large upcoming items
        }
        if fitting_bins_count <= 1 {
            score -= 10.0; // opening new bin beats forcing a bad single fit
        }
    }

    // Stream-phase modulation: later in the stream, consolidate more aggressively
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 3.0 * (1.0 - pr / cap);

    // Prefer filling bins below mean residual (balance avoidance of fragmentation)
    if (pr < mean_residual) && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Integer-division threshold: post_residual divisible by common item sizes is reusable
    if post_residual > 0 {
        let reusable = (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 30 == 0);
        if reusable {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
