pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect two-step chain
        } else if post >= nxt {
            // next item fits here: prefer small leftover gap
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // next item will NOT fit here: penalize dead space
            score += 12.0 + 0.25 * diff;
        }
    }

    // Compare against mean residual: bins with residual far above mean are
    // "odd" bins; placing here keeps the fleet homogeneous.
    let post_f = post_residual as f64;
    let mean_gap = post_f - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    // (post_residual of empty bin = capacity - item; large residual waste
    // on an open bin makes opening fresh space reasonable).
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).max(0.0);
        score -= 5.0 + waste * 0.3;
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // if many bins already fit the item, new bin is wasteful
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Tight packing reward: nearly full bin is great.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits into post_residual, reward this bin;
    // otherwise penalize wasted space that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Dead space unusable by the next item is penalized proportionally.
            let dead = post_residual as f64;
            score += 0.08 * dead;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to prefer bins with fewest options elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Global state: when many bins are open with large mean residual, discourage
    // leaving more fragmentation; when mean residual is small, prefer new space.
    let mr = mean_residual;
    if mr > 0.0 {
        let frag = (post_residual as f64 - mr).abs();
        score += 0.05 * frag;
    }

    // Time horizon: early in the stream, be more conservative (favor new bins for
    // flexibility); late in the stream, squeeze everything into open bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * t;
    score += 4.0 * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless it is genuinely useful
    // (large item leaving a well-shaped residual).
    if bin_residual == bin_capacity {
        let base = 30.0;
        let bonus = if next_item_size > 0 && next_item_size <= post_residual { -10.0 } else { 6.0 };
        score = base + bonus + post_residual as f64 * 0.1 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: tight fits matter more as the stream progresses
    score *= 1.0 + 0.6 * progress * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual of open bins
    score += 0.25 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let mismatch = (pr - nx) / cap;
        score -= 12.0 * (-40.0 * mismatch * mismatch);
        score += 6.0 * mismatch * mismatch;
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score = pr + 30.0 + 50.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residuals that are "usable" residue classes.
    // Post-residual divisible into common small-item chunks is valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr <= 10 {
        score -= 18.0; // near-perfect, dead space negligible
    } else {
        // class by modulo 10: residues that pair well with future items
        let m = (pr % 10) as f64;
        score += m * 0.4; // penalize awkward residues
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // integer-division threshold: large leftover is wasteful unless reusable
        if pr > 50 { score += 5.0; }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item can fit exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
        } else {
            // next item won't fit here; leftover is more likely dead space
            score += (next_item_size as f64) * 0.05;
        }
    }

    // New-bin candidate handling: empty bin should lose unless open bins are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // but if mean residual across open bins is small, new bin is attractive
        score -= (cap - mean_residual) * 0.1;
    }

    // Tight fit reward: filling most of the current residual is good.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // Slight penalty for proliferating bins.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // the smallest item (1..=100 range, but treat < 12 as near-dead) are wasted.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < 25 {
        // small-but-usable gap: mild penalty to prefer roomier leftovers
        score += 8.0;
    }

    // Perfect fills are gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this bin strongly (chains two good placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate detection and open_bins_count pressure:
    // opening yet another bin while many are open fragments capacity.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, be even more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Reward keeping existing bins busy: slight pull toward the fullest bin.
        score -= 0.05 * (bin_residual as f64);
    }

    // Mild global balance: bins far below the mean residual are slightly
    // deprioritized to spread load evenly among open bins.
    score += 0.02 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly what next item needs
        } else if post_residual >= next_item_size {
            // next item fits too; reward tightness of the two-item chain
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * chain_waste;
            // extra bonus if chain leaves nothing after next item
            if post_residual == next_item_size * 2 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize by the shortfall (dead space risk)
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.35 * shortfall;
        }
    }

    // Penalize small unusable dead space (< 10 can never fit a new item)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild preference for keeping open-bin count low early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly better.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (future items unknown).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If few bins fit the item, a new bin is more attractive.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Next item large: a fresh bin may serve it well.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Last-chance bin: strong bonus to use it before it becomes dead space.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Lookahead synergy: if the next item fits the post-residual exactly or well,
        // favor this placement (chain packing).
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if post_residual >= next_item_size {
                score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            } else {
                // Next item cannot fit: leftover may become dead space, mild penalty.
                score += 5.0 * gap / bin_capacity as f64;
            }
        }
        // Prefer bins whose residual is already small relative to the mean
        // (consolidate waste in few bins).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 15.0 * dev;
    }

    // Global state: many open bins -> discourage spreading, favor tight reuse.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Late in the stream: prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Tight-fit reward: quadratic coupling of post_residual with stream progress.
    // Later in the stream, small dead space is penalized more (we want near-exact fills).
    score -= (1.0 - norm_post) * (1.0 + 3.0 * progress) * 25.0;
    score -= norm_post * norm_post * 60.0 * (0.5 + progress);

    // Non-linear interaction: item size relative to capacity shapes the reward.
    let item_frac = item / cap;
    score -= item_frac * item_frac * 20.0 * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth exponential urgency).
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    } else {
        // Slight preference for bins among many candidates that fit well.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (smooth sigmoid-like gate).
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-8.0 * (item_frac - 0.55)).exp());
        score += 45.0 * (1.0 - gate) + 15.0;
    }

    // Lookahead coupling: if the next item would fit the post residual,
    // reward leaving a useful gap; otherwise penalize dead space sized for nothing.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 18.0 * (1.0 - (next / (post + 1.0) - 1.0).abs()) * (1.0 + progress);
        } else {
            score += (next - post) * 0.25;
        }
    }

    // Mean-residual context: when open bins are already loose, prefer tight placements.
    let mean_norm = mean_residual / cap;
    score += mean_norm * mean_norm * 10.0 * (1.0 - norm_post);

    // Mild penalty for bin sprawl: discourage opening many bins early.
    score += (open_bins_count as f64).sqrt() * 1.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes define "usable" dead space.
    // Residuals that are multiples of small harmonics (fit likely future items) are cheap.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: residual divisible by 10 (harmonic with typical item sizes) -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class 2: residual divisible by 20 or 25 -> strong reward (very reusable).
    if post_residual % 20 == 0 || post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Class 3: awkward residuals (prime-ish / small odd leftovers) -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly unusable dead space
    }
    if post_residual > 0 && post_residual % 2 == 1 && post_residual < 15 {
        score += 3.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect harmonic chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 5.0 - (leftover as f64) * 0.15;
            if leftover % 10 == 0 {
                score -= 3.0; // chain continues harmonically
            }
        } else {
            // next item cannot use this residual: dead space likely permanent
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tightest fit: post_residual already dominates.
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate: penalize opening a bin unless residuals are all tight.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).min(1.0);
        score += 30.0 - tightness * 25.0 + (open_bins_count as f64) * 1.5;
        // Late in stream, reusing bins matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for filling bins deeply (low residual fraction).
    score += (post / cap) * 2.0;

    // Mean residual context: if open bins are very loose, prefer tighter consolidation.
    if (mean_residual - post).abs() < 5.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can no longer fit the next item
    // (or any plausible item) are dead space; punish them hard.
    let can_fit_next = next_item_size > 0 && post_residual >= next_item_size;
    if !can_fit_next && post_residual > 0 {
        // dead gap: penalize proportionally to how much is wasted
        score += 40.0 + 0.5 * post_residual as f64;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Reward keeping the next item fittable in this bin (chained fit).
    if can_fit_next {
        score -= 8.0;
        // extra bonus if next item fills the bin nearly exactly after this placement
        let gap_after_next = post_residual as f64 - next_item_size as f64;
        if gap_after_next <= 10.0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: only fitting bin -> strongly prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // (poor fit everywhere) or bin pressure is high.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        score += 45.0;
        if big_item {
            score -= 35.0;
        }
        if pressure > 8.0 {
            score -= 10.0;
        }
        // late in the stream, avoid sprawl
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bin pressure: mildly discourage accumulating many open bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits snugly (small leftover)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Penalize leaving dead space that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward tighter fits generally (relative to capacity)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation toward mean residual
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 15.0 / (1.0 + dev);
    }

    // New-bin candidate: only attractive when this bin would be a near-perfect
    // fresh start relative to the next item, otherwise penalize opening new bins
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) <= post_residual as f64 {
            score += 5.0;
        } else {
            score += 20.0 + open_bins_count as f64;
        }
    }

    // Late in the stream: prefer filling existing bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that is too small to be useful later (below min item size 10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // Waste penalty scaled by how badly the next item misses.
            score += (next_item_size - post_residual).min(40) as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, encouraging competition.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins with residual below the mean (consolidate small spaces).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early in the stream, be more willing to open new bins (keep options);
    // later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early openings.
        score += 20.0 + progress * 40.0 + (open_bins_count as f64) * 1.5;
    } else {
        score -= progress * 6.0;
    }

    // Avoid spreading across too many open bins when item is large.
    if item_size > 60 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Reward tight fits: quadratic coupling of item size with fill ratio.
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill * (item / cap);

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in the stream, dead space becomes increasingly costly.
    let waste_frac = post / cap;
    score += 18.0 * waste_frac * waste_frac * (1.0 + 2.0 * progress);

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64;
        let snug = 1.0 - ((post - nx) / cap);
        score -= 8.0 + 10.0 * snug * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a residual just barely below the next item.
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 6.0 * gap * gap;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more when many bins are open early
    // (avoid bin proliferation), smooth in progress and open-bin count.
    if bin_residual == bin_capacity {
        let proliferation = (open_bins_count as f64 / (1.0 + total_items as f64)).sqrt();
        score += 4.0 + 10.0 * proliferation * (1.0 - progress);
    }

    // Mild global balance: prefer bins near the mean residual.
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let quarter = bin_capacity / 4;
    let residue_class = post_residual % quarter;

    // Penalize dead space in the lowest harmonic class (tiny unusable gaps)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < quarter / 2 {
        score += 8.0;
    }

    // Reward post-residuals that form "nice" fractions of capacity
    if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Modulo coupling: residue class near quarter boundaries is bad
    if residue_class < 5 && post_residual >= quarter {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual < 20 {
        // dead space can't serve next item
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Prefer tight fits overall: relative waste term
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 20.0;

    // Late in stream, be more aggressive about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size).min(bin_residual) as f64 * 0.05;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward post_residual that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        score += 10.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit,
    // or when this is the last fitting bin (avoid stranding capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        } else {
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless tight fit.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins below mean residual (keep residuals balanced).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits exactly-ish: strong reward
            score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
            if diff == 0.0 {
                score -= 200.0;
            }
        } else {
            // next item would not fit here: mild penalty scaled by gap
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins with above-average residual (keep tight bins for tight fits)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize creating small dead space (< smallest plausible item) that is unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current item is large relative to capacity
    // or stream is early and few bins are open (better to spread)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64
            + 100.0 * (1.0 - size_frac)
            + 50.0 * progress
            - 20.0 * (open_bins_count as f64).min(10.0);
        // discourage new bin when next item is small (could share current bin)
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good, but reward perfect fits extra.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity, nonlinearly.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits too: mild bonus scaled by how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * snug;
        } else {
            // next item won't fit here; penalize bins that strand too little space
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduced late in the stream or when few bins fit.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 120.0 - 40.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_cost -= 150.0; // no alternative
        } else if fitting_bins_count == 1 {
            new_bin_cost += 100.0; // an existing bin is the last chance
        }
        // If open bins have large mean residual, opening a new bin is wasteful.
        new_bin_cost += 0.5 * mean_residual;
        score += new_bin_cost;
    }

    // Mild preference for filling bins that are already mostly full (fragmentation control).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Slight tie-break toward fewer open bins to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual (fraction of bin wasted)
    let x = post_residual as f64 / cap;
    let x2 = x * x;
    let x3 = x2 * x;

    // Non-linear waste penalty: small dead spaces hurt more as stream progresses
    score += cap * (x2 * (0.6 + 0.8 * progress) - x3 * (0.4 + 0.6 * prog2));

    // Reward tight fits (small post_residual) more strongly early, less late
    score -= (1.0 - x) * (1.0 - x) * (2.5 - 1.2 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins close to the mean residual (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 + progress);

    // Lookahead: penalize leaving a residual that fits next item poorly but not exactly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            let slack = (post_residual as f64 - n) / cap;
            score += 0.8 * slack * slack * (1.0 + prog3);
        } else {
            score += 0.5; // next item won't fit here anyway
        }
    }

    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 1.2 + 2.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space severity by modulo classes
    let pr = post_residual;
    let class4 = (pr % 4) as f64;
    let class5 = (pr % 5) as f64;
    score += 2.0 * class4 + 1.5 * class5;

    // Integer-division thresholds: small non-zero residuals are dead space
    let small = (pr / 10) as f64; // decades
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr >= 10 && pr < 20 {
        score += 8.0 * (1.0 - small / 2.0);
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual accommodate next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 12.0 - (slack as f64).min(20.0) * 0.3;
            if pr % next_item_size == 0 {
                score -= 10.0; // harmonic divisibility bonus
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        score -= 5.0; // last item: just fill anything
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening unless current residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0;
        let late = step_index as f64 / total_items.max(1) as f64;
        if tight {
            score -= 10.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - late);
        }
        // opening is fine if item is huge relative to typical residual
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Prefer fuller bins among open bins (residual closeness to item)
    let tightness = (bin_residual - item_size) as f64;
    score += 0.1 * tightness;

    // Mild pressure when many bins are open: encourage consolidation
    score += 0.3 * open_bins_count as f64 * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: small gaps (< 10) are unusable for future items -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium-dead zone: gaps that only fit the smallest items
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last fitting bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, favor tight packing
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 3.0 * open_pressure;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits (small miss), mild penalty for near-miss gap
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if stream is late and many bins open, opening new bins is cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits in the leftover; reward proportional to tightness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap / 10.0);
        } else {
            // Next item cannot fit in the leftover; penalize wasted capacity.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + waste * 0.15;
        }
    }

    // Penalize small unusable dead space (fragmentation) relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare residual against mean residual of open bins: prefer bins that
    // tighten the spread (avoid leaving one very empty bin among full ones).
    let diff = post_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, be more willing to open new bins (keep flexibility);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as stream progresses (prefer reuse),
        // unless current open bins are quite full (high mean residual).
        score += 20.0 + 25.0 * progress - 0.05 * mean_residual;
    } else {
        // Reward reusing existing bins more strongly late in the stream.
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins where the item fills most of the residual.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - residual_frac) * (1.0 - residual_frac) * 12.0;

    // Penalize dead space that is too small for the smallest plausible item (<=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if next item would be wasted here, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if next_item_size > bin_residual {
            // next item needs a new bin anyway; residual size matters less
            score += 2.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residuals are high (fragmented state) or item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut nb = 8.0; // base cost of opening a new bin
        // reward opening when existing bins are very fragmented
        nb -= (mean_residual / bin_capacity as f64) * 6.0;
        // large items prefer fresh bins
        nb -= (item_size as f64 / bin_capacity as f64) * 5.0;
        // late in stream, prefer packing into existing bins
        nb += progress * 6.0;
        // many open bins: discourage further sprawl
        nb += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // if no other bin fits (fitting_bins_count==0 among open bins),
        // the new-bin call is effectively the only choice
        if fitting_bins_count == 0 {
            nb -= 20.0;
        }
        score += nb;
        score += fragmentation * 0.05;
    }

    // Mild preference for bins with below-average residual (consolidate fullness).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress (smooth, in [0,1])
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, small residuals are fine (bins can still be filled);
    // late in the stream, dead space becomes costly, so penalize quadratically.
    let progress_coupling = post_norm * post_norm * (0.5 + progress) * cap;

    // Cubic term: strongly penalize mid-range residuals as stream advances
    // (mid-range residuals are hard to fill with future items).
    let mid_penalty = 4.0 * post_norm * (1.0 - post_norm) * post_norm * (0.3 + 0.7 * progress) * cap;

    // Reward tight fits: small post_residual relative to capacity gets a discount
    let tight_fit_bonus = -8.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 + 0.5 * progress);
        } else {
            // next item won't fit; penalize proportionally to wasted potential
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // (converge residuals to reduce fragmentation across open bins)
    let dev = (post - mean_residual).abs();
    score += 0.5 * dev * (1.0 - progress);

    // Many open bins: mild penalty to discourage bin proliferation
    score += 0.05 * open_bins_count as f64 * post_norm;

    score += progress_coupling + mid_penalty + tight_fit_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact quarter/eighth fills are golden.
    let q = post_residual % 25;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if q == 0 {
        score -= 25.0; // multiple of 25 residual stays usable
    } else if post_residual < 10 {
        score += 60.0; // dead space below min item size
    } else {
        // penalize residuals that waste capacity modulo harmonic classes
        score += (q as f64) * 0.4;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 10.0;
            // next item exactly fills a harmonic class with post_residual + slack elsewhere
            if next_item_size % 25 == 0 && post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer any fit, prefer emptier bins
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would fragment badly.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        let early_bonus = 20.0 * (1.0 - t);
        // open new bin if best existing fit leaves tiny unusable residual
        let poor_fit = (post_residual > 0 && post_residual < 10) || next_item_size > post_residual && post_residual < 20;
        if poor_fit { score -= early_bonus + 10.0; }
        else { score += 15.0 + early_bonus; }
    }

    // Prefer filling bins whose residual deviates from mean (converge residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: bins with residual in [50,75] are prime targets.
    if post_residual / 25 == 2 {
        score -= 10.0;
    } else if post_residual / 25 >= 3 {
        score += 5.0; // too empty, spread usage elsewhere
    }

    // Mild pressure to close bins as stream progresses.
    score -= (open_bins_count.min(20) as f64) * 0.2 * (post_residual == 0) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Mid-range dead space (unlikely to fit min-size items later) gets a milder bump.
    if post_residual > 10 && post_residual < 20 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.25;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (penalize the empty-bin candidate relatively).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // Early stream: keep bins consolidated.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the dead space left behind, penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) relative to capacity scale.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: strongly reward bins where the next item fits the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += 8.0 + 0.5 * gap as f64;
        }
    } else {
        // Last item: pure tightness is fine, small bonus.
        score -= 5.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should win only when no open bin offers
    // a decent fit. Make the fresh bin moderately attractive but not dominant.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If many bins are open, prefer consolidating into them.
        score += 0.5 * open_bins_count as f64;
    }

    // Early in the stream, allow more new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.5 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // next item can't use this bin's leftover; penalize large leftovers slightly more.
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: as stream progresses, be more conservative — prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64) / (bin_capacity as f64);

    // Global state coupling: if mean residual across open bins is high, opening new bins is bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many open bins with slack exist.
        score += 15.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // But if item is huge and nothing else fits well, allow new bin.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        // Reward using bins whose residual deviates below mean (consolidating slack).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.1 * dev.min(30.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred, with non-linear (quadratic/cubic) shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: tighten more aggressively later
    let coupling = norm_pr * norm_pr * (1.0 - progress) + 3.0 * norm_pr * progress;
    score += coupling;

    // Penalize bins whose residual deviates from mean residual (dead-space balancing)
    score += ((pr - mean_residual) / cap).powi(2) * (0.5 + progress);

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize creating residual too small for the next item
        score += (post_residual as f64 / cap) * 0.5;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless residual is full capacity
    // and few alternatives exist; allow early opening when fit would be poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (item_size as f64 / cap) < 0.5;
        score += 3.0 - 2.0 * progress + if poor_fit && progress < 0.5 { 0.0 } else { 2.0 * (1.0 - progress) };
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the residual?
    // Residuals that are multiples of common item-size classes (multiples of 10/20)
    // are more likely to be filled later; odd/prime-ish residuals are dead space.
    let post = post_residual as u32;
    let harmonic_bonus = if post == 0 {
        -30.0 // perfect fit, best possible outcome
    } else if post % 20 == 0 {
        -12.0
    } else if post % 10 == 0 {
        -8.0
    } else if post % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Dead-space penalty grows quadratically once residual falls below the
    // minimum plausible item size (small leftovers are likely wasted).
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else
    // or the stream is early and we expect many future items to consolidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / cap) > 0.6; // item small relative to bin
        if poor_fit && progress < 0.7 {
            score -= 6.0; // fresh bin keeps large residual for future big items
        } else {
            score += 15.0; // discourage opening new bins when fits exist
        }
    }

    // Lookahead coupling: if next item would fit exactly into the post-residual
    // (harmonic match), reward this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 2.0; // next item cannot use this bin's leftover
        }
    }

    // Prefer filling bins with below-average residual (consolidate tight bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.4;

    // Late in the stream, be greedy: minimize waste now, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Tight fit reward scaled by how close post_residual is to zero.
        score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Penalize bins whose leftover is far below the mean residual (fragmented bins).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins.
    score += 0.3 * open_bins_count as f64;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is stranded by this placement (small gap just below next size), penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a decent fit in an open bin beats opening a new bin.
        score += 40.0 + 0.2 * open_bins_count as f64;
        // But if current item leaves a dead gap in every bin (unusable small gap),
        // opening a fresh bin becomes attractive: relax the penalty.
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating: raise new-bin cost.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: tighten thresholds as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Two-step lookahead: reward if the next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item exactly fills the bin -> strong reward.
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how well the next item matches the leftover.
                let match_ratio = next_item_size as f64 / post_residual as f64;
                score -= 40.0 * match_ratio;
                // Bonus for leaving a "usable" residual (>= 10) after the next item.
                if slack >= 10.0 {
                    score -= 5.0;
                } else {
                    // Tiny dead space after next placement is penalized.
                    score += 8.0 * (10.0 - slack) / 10.0;
                }
            }
        } else {
            // Next item cannot follow into this bin: penalize, scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * miss.min(50.0);
        }
    }

    // Penalize leaving awkward small residuals now (dead space hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    // early on, but allow spreading later.
    let diff = mean_residual - post_residual as f64;
    score -= diff * (0.5 - 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are large/wasteful
    // or many bins are open with poor fit prospects.
    if bin_residual == bin_capacity {
        // Baseline penalty: prefer filling existing bins.
        score += 30.0;
        // But if existing bins are loose relative to the item, a fresh bin is fine.
        if mean_residual > 60.0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        // Late in the stream, consolidation matters more.
        score += 20.0 * progress;
    }

    // Mild preference for bins already committed (fewer open bins is better).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 && (post_residual as f64) < 0.5 * (item_size as f64) {
        score += 6.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * (next_item_size as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // but attractive when current bins have poor fit quality.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_state = mean_residual / (bin_capacity as f64);
        score += 20.0 - 15.0 * progress;
        if poor_state < 0.25 && fitting_bins_count > 0 {
            score -= 6.0; // open fresh bin when open bins are nearly full
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 2.0;
        }
    }

    // Global congestion: many open bins with large mean residual -> favor consolidation.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let consolidation = (mean_residual - bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * consolidation.max(0.0);
    }

    // Late-stream horizon: as stream ends, favor using existing space aggressively.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: reward tight fits via smooth non-linear post-residual coupling
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next_fits = (next_item_size as f64) <= pr;
    let waste = if next_item_size == 0 {
        0.0
    } else if next_fits {
        -8.0 * (1.0 - (pr - next_item_size as f64) / cap)
    } else {
        12.0 * (1.0 - progress)
    };
    score += waste;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // unless the item is huge relative to current residuals
    if bin_residual == bin_capacity {
        score += 40.0 + 60.0 * progress - 20.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild diversity pressure: many open bins with low mean residual -> favor filling
    score -= 5.0 * (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // Smooth progress-coupled tightness reward
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: dead space that no future item (min 1..=100,
    // but effectively >= 10 in classic streams) can use is worse.
    let dead_threshold = 9.0;
    if !is_new_bin && pr > 0.0 && pr <= dead_threshold {
        score += 25.0; // tiny unusable sliver — penalize strongly
    }

    // Modulo classes on post_residual: residuals divisible by 10 are "harmonic"
    // with typical item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd primes / coprime-ish residuals are harder to fill: mild penalty.
    if post_residual % 10 != 0 && post_residual % 5 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward smooth chains: next residual again harmonic (multiple of 10)
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_post as f64) * 0.15;
        } else {
            // next item cannot fit here; if this is the only fitting bin, still place
            if fitting_bins_count == 1 {
                score -= 8.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin logic: if only one bin fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline; encourage early in stream (many items
    // remain to fill it), discourage late.
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 + 18.0 * progress;
        // If current item leaves a harmonic residual in a fresh bin, slightly better.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
        // If no open bin fits well (large waste otherwise), allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with above-average residual (balance open bins),
    // keeping some bins tight for small items.
    if !is_new_bin {
        let diff = (bin_residual as f64) - mean_residual;
        score += diff * 0.05;
    }

    // Waste normalization: penalize proportional waste.
    score += (pr / cap) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit bonus: reward exact fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight fit bonus: reward placements that consume most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (subtracted reward), scaled by how full it gets.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins and penalize opening yet another one.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 10.0 * open_pressure;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless the item is
        // large and would leave a well-shaped residual in an open bin.
        score += 15.0 + 5.0 * open_pressure;
        if post_residual >= 30 && post_residual <= 60 {
            score -= 10.0; // new bin would leave a usable gap
        }
    }

    // Lookahead coupling: if the next item can exactly use the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
        score -= 25.0;
    }
    // Penalize leaving a residual the next item cannot use at all.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps residual distribution homogeneous and packable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early-stream: allow more bins early (future items unknown), relax later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // sliver waste
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize more when next item is large.
        score += (next_item_size as f64) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: encourage consolidation, penalize spreading thin.
    score += (open_bins_count as f64) * 1.5;

    // Compare residual to mean residual: prefer bins below mean (tighter bins)
    // to keep loose bins available for future items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (fresh bins useful later); late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 30.0 * (1.0 - progress) - 20.0 * progress;
        // But if no open bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // New bin great if item is huge and next item also large.
        if item_size > 60 && next_item_size > 50 {
            score -= 30.0;
        }
    } else if progress > 0.7 {
        // Late stream: reward filling existing bins hard.
        score -= 15.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    score += 0.6 * pr_norm * pr_norm * (1.0 + 2.0 * progress) * cap * 0.05;

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits post_residual smoothly
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let n = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - (n - pr_norm).abs());
    }

    // New-bin candidate: penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * (mean_residual / cap);
        score += 4.0 * (1.0 - progress);
    }

    // Mild penalty proportional to open bins count to encourage consolidation
    score += 0.15 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 classify dead-space quality.
    let pr = post_residual as i64;
    let residue = pr % 10;
    // Residue 0 => perfectly harmonic residual, strong reward.
    score -= if residue == 0 { 12.0 } else { 0.0 };
    // Small odd residues (1,3) leave nearly unusable slivers for items >=10.
    if residue == 1 || residue == 3 {
        score += 4.0;
    }
    // Quarter-capacity harmonic classes: post_residual in {25,50,75} are useful anchors.
    if pr == 25 || pr == 50 || pr == 75 {
        score -= 6.0;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 25.0; // perfect chain
        } else if ni <= pr {
            // Fraction of next item covered; reward high coverage, penalize tiny leftovers.
            let leftover = pr - ni;
            score -= 15.0 * (ni as f64 / pr.max(1) as f64);
            if leftover % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize proportional to wasted potential,
            // heavier when post residual is in a "dead" class (< 10 unusable anyway).
            if pr < 10 {
                score -= 2.0; // dead space regardless, mild
            } else {
                score += 6.0;
            }
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate calibration: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win; reduced when many open bins
        // exist with fragmented residuals (mean residual low relative to item).
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        score = cap - fragmentation * 0.5;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 5.0; // new bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits elsewhere: must open
        }
    }

    // Slight preference to consolidate across few open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (never leave dead space)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: residual gaps too small to be useful
    // (below the minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderately small gaps are mildly penalized (unlikely to fit typical items).
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the next item fits snugly (tight chain of placements).
        if post_residual - next_item_size < 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating a gap the next item cannot use.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the dead-space penalty dominates).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly favor reusing existing bins as the pool grows.
    if bin_residual < bin_capacity {
        score -= 2.0 + open_bins_count as f64 * 0.3;
    }

    // New-bin candidate (bin_residual == bin_capacity) keeps its raw post_residual,
    // so it only wins when existing fits are poor (large or dead-space residuals).

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tightness = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 200.0 * tightness;
        } else {
            // next item won't fit in leftover: penalize dead space
            score += 50.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
    }

    // Small bonus for larger bins being filled (tighter packing overall)
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight_fit * tight_fit;

    // Penalize dead space that cannot fit the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // hard-to-fill gap
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when next item exactly chains into this bin's future.
        let chain_waste = post_residual - next_item_size;
        score -= 6.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is worse late in the stream (fewer future items to fill them).
        let open_penalty = 15.0 + 35.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        let crowd_penalty = 4.0 * fitting_bins_count as f64;
        // If mean residual is large, existing bins have room; discourage new bin.
        let mean_bonus = 0.3 * mean_residual;
        score += open_penalty + crowd_penalty + mean_bonus;
        // But if the item nearly fills a fresh bin, a new bin is fine/great.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 40.0;
        }
    } else {
        // Slight preference for filling bins that are already well-used.
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * used_frac;
        // Mild pressure toward consolidating: fewer open bins is better.
        score += 0.05 * open_bins_count as f64;
    }

    // Time-horizon modulation: early in stream, be conservative with tight fits
    // (keep flexibility); late in stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let aggression = 0.5 + progress;
    score = score * aggression - 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Smooth non-linear coupling: post_residual scaled by progress-shaped factor.
    // Early on, waste matters less; late, waste is heavily penalized.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score *= progress_weight;

    // Quadratic penalty on large post_residual, modulated by progress
    score += 0.01 * post * post * (0.25 + progress);

    // Reward filling most of the bin: subtract normalized fill, stronger with progress
    let fill = (cap - post) / cap;
    score -= fill * (2.0 + 3.0 * progress);

    // Interaction: small post_residual relative to mean residual is especially valuable
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        score -= (1.0 - rel) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let next_fit_quality = next_item_size as f64 / cap;
        score -= 1.0 + 2.0 * next_fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the next item
        score += 0.5 * post / cap;
    }

    // Prefer reusing existing bins over opening new ones when many bins are open
    if bin_residual < bin_capacity {
        score -= 0.75 + 0.25 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New bin candidate: mild penalty so it only wins when fits are poor
        score += 1.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual by integer division thresholds.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Perfect-fit reward (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class bins by residual magnitude: tiny residuals are dead space unless exact
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - frac);
    } else if post_residual <= 25 {
        score += 15.0;
    } else if post_residual <= 50 {
        score -= 10.0;
    } else {
        // large residual left: keep space flexible
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let rem = post_residual - next_item_size;
            // prefer leaving a "harmonic" residual (multiple of 10, or > 25)
            if rem % 10 == 0 {
                score -= 50.0;
            }
            if rem > 25 {
                score -= 25.0;
            } else {
                score += 30.0;
            }
        } else {
            // next item won't fit here: mild bonus for closing tight bins
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 80.0;
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 1.5;
        }
    }

    // Late stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it cannot fit the next item (or typical min size).
    let min_probe = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual > 0 && post_residual < min_probe {
        score += 60.0 + (min_probe - post_residual) as f64 * 3.0;
    }

    // Lookahead coupling: if post_residual exactly accommodates the next item,
    // strongly reward (perfect chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If post_residual is large enough for the next item, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: this is the only open bin that fits -> strong reward
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        // Mild preference to spread load when many bins are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (pack tightly).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Progress-aware tightening: later in the stream, prioritize near-perfect fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits exactly into the post-residual (2-step lookahead match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward tight matches.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted space that is too small for it.
            score += 5.0 * (1.0 - diff / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is close to the mean residual (balanced usage),
    // but prefer tighter-than-mean fits slightly.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize near-empty new-bin usage unless open bins are poor fits:
    // a fresh bin should only win when post_residual is large AND fitting bins are scarce.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild time-decay: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits beyond raw post_residual (non-linear tightness bonus)
    score -= 18.0 * (1.0 - post / cap);

    // Penalize dead space that the lookahead item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post > 0.0 && post < nxt {
            score += 0.6 * (nxt - post); // unusable sliver for next item
        }
        // Reward leaving exactly enough room for the next item
        if (post - nxt).abs() < 1.0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize, but less when the fit is poor in all bins
    if bin_residual == bin_capacity {
        let mut penalty = 22.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            penalty -= 26.0; // opening a bin may be the only sane choice
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 6.0; // fresh bin can host the next item too
        }
        score += penalty;
    }

    // Prefer bins whose residual deviates favorably from the mean (fill laggards)
    score += 0.12 * (bin_residual as f64 - mean_residual);

    // Late in the stream: consolidate aggressively, minimize leftover space
    score -= 8.0 * progress * (post / cap);

    // Mild preference for using bins that are already well-filled
    score -= 0.05 * (item_size as f64 / cap) * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: post_residual weighted by progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 30.0 * poly * (0.5 + progress);

    // Tight fits rewarded, scaled by stream progress
    score -= 25.0 * fit_ratio * fit_ratio * (1.0 - pr_norm) * (0.4 + 0.6 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead: if next item fits the post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 * pr_norm * progress;
    }

    // Penalize creating dead space relative to mean residual
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * (1.0 - progress) * 4.0;

    // Mean residual deviation coupling
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional fill level of the bin after placement.
    let fill = 1.0 - post / cap;

    // Reward high fill non-linearly (waste minimization).
    score -= 40.0 * fill * fill * fill;

    // Harmonic class: post_residual divisible by 10, 20, 25 -> "clean" slots
    // likely to be exactly filled by future items.
    let r = post_residual;
    if r == 0 {
        score -= 100.0; // perfect closure
    } else {
        if r % 10 == 0 { score -= 12.0; }
        if r % 20 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 8.0; }
        // Dead zone: tiny leftovers are wasted capacity.
        if r < 10 {
            score += 25.0 * (10.0 - post);
        }
        // Mid-band awkward residuals (just above small item sizes) penalized.
        if r > 60 { score += 5.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anywhere else, reward anyway.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic check: post_residual - next_item_size still clean
            let d = post_residual - next_item_size;
            if d % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; slight penalty unless this is the
            // only fitting bin (last-chance placement).
            if fitting_bins_count > 1 { score += 4.0; }
        }
    }

    // Last-chance bonus: sole fitting bin avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only prefer opening a new bin when current bin would
    // leave a very awkward residual and there are already many bins open.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 20;
        if awkward && open_bins_count > 0 && post < 20.0 {
            score += 30.0; // discourage using fresh bin for bad split
        }
        // Mild default penalty so open bins win unless clearly better.
        score += 8.0;
        // Early in stream, opening bins is cheap and builds diversity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter bins) slightly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // near-zero gaps are almost always dead space
    }

    // Reward tight fits (very small post_residual is only good if it's zero).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // relative fill quality
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 25.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless the
    // current bin's post-fit residual is terrible dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        if post_residual >= 15 {
            score += 20.0; // new bin only attractive for big leftover space
        }
    }

    // Lookahead coupling: if the next item fits in post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space that next item cannot use
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.15 * (1.0 - progress);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0; // exact 2-step chain
        }
        // penalize dead space that can't hold the next item
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin may be fine for large chains
        }
    }

    // Progress-based mild tightening: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Penalize small unusable dead space: residuals below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item + 9.0 {
        score += 25.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item is smaller/equal but doesn't fit: mild penalty for fragmenting.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have poor fits or are heavily fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins.
        let open_cost = 15.0 + 2.0 * open_bins_count as f64;
        // Discount if mean residual across open bins is small (bins nearly full).
        let mean_fill = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        score = 100.0 - item_size as f64 + open_cost - 25.0 * mean_fill;
        // Perfect-fit items (item fills a fresh bin exactly) get a big discount.
        if post_residual == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Existing bin: mild reward for choosing the fullest usable bin.
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer smaller post residual, with non-linear polynomial emphasis
    // that strengthens as the stream progresses (waste matters more later).
    let poly = norm_post * norm_post * (0.5 + 1.5 * progress) + norm_post * (0.3 + 0.7 * progress);
    let mut score = post + 60.0 * poly;

    // Reward near-perfect fits with a smooth bump (post residual close to 0 or 1..2).
    let tight = ((post - 1.0) / cap).abs();
    score -= 12.0 * (-tight * 30.0).exp() * (0.6 + 0.8 * progress);

    // Penalize dead space that no plausible future item can use:
    // if post_residual is small but nonzero relative to typical item sizes.
    if post > 0.0 {
        let dead = (post / cap) * (1.0 - (post / cap));
        score += 25.0 * dead * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual (chaining),
    // penalize smoothly otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (-gap / 25.0) * (0.5 + 0.5 * progress);
        if post < nxt {
            score += 6.0 * (1.0 - post / cap);
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 3.0;

    // New-bin candidate: make empty bins mildly attractive only when open bins
    // are mostly full (mean residual low) or progress is late.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = 35.0 + 60.0 * mean_norm * (1.0 - progress) - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near "dead zones" are penalized.
    // Dead space classes: residuals in 1..=9 are nearly unusable for items >=10.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // creates unusable sliver
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit, zero waste
    }

    // Modulo-10 harmonic ladder: residuals that are multiples of 10 remain
    // packable by the smallest item class (sizes 10,20,...).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Integer-division threshold: post_residual / 20 quantizes "half-bin" harmony.
    let half_class = post_residual / 20; // 0..=4
    score -= half_class as f64 * 6.0;

    // Lookahead coupling: penalize if post_residual can't host next item but
    // bin_residual could (wasted opportunity), reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // bonus if next item then leaves another multiple-of-10 residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else if bin_residual >= next_item_size {
            score += 18.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (residual == capacity): only attractive when current
    // fit is poor (large post_residual) or item is small and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress); // early stream: fresh bins cheap
        score += (post_residual as f64) * 0.35; // poor fit => prefer new bin
        if post_residual < 15 {
            score += 55.0; // don't open bins for near-perfect fits
        }
    }

    // Mean-residual coupling: placing into a bin below mean residual tightens
    // the distribution; placing into an already-large-residual bin is worse.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Many open bins: prefer consolidation to limit bin count.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Dead-space penalty: post_residual that is too small to be useful later.
    // Anything <= 10 (min item size) is pure waste; 11..=30 is risky.
    if post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 30 {
        score += (31.0 - post_residual as f64) * 1.5;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large and residuals
    // across open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Penalize opening new bins normally...
        score += 55.0 + 20.0 * fragmentation;
        // ...unless the item is big and open bins would be left with bad gaps.
        let would_fragment = open_bins_count > 0
            && post_residual > 0
            && post_residual <= 20;
        if would_fragment {
            score -= 70.0;
        }
        // Early in the stream, spreading load across fresh bins is cheap.
        if progress < 0.25 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to
    // discourage proliferation, encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item: post_residual exactly matches next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item can at least fit into the post-residual space
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Post-residual is dead space: too small for next item (and likely too small for anything)
    else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize unusable slivers proportionally to how close they came to fitting
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Compare against mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Late in the stream, avoid opening new bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 30.0 + 120.0 * progress;
        // But if no open bin fits at all, opening is fine
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual relative to capacity)
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize unusable dead space: small but nonzero leftover that likely nothing fits
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Perfect closure bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose leftover can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Lookahead: penalize bins whose leftover is just barely below the next item (blocked dead zone)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 25.0 + 12.0 * (1.0 - t);
        // but soften if no other bin fits at all
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild preference for consolidating into bins below mean residual (fill emptier-first candidates)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight load-balancing pressure as many bins accumulate
    score += 0.03 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer minimal post-residual, with non-linear emphasis.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Reward tight fits: quadratic coupling of fill ratio with stream progress.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Penalize dead space that becomes unusable (below min item size 1, use
    // smooth coupling with mean residual instead).
    let dead = (pr - mean_residual.min(pr)).abs();
    score += 8.0 * dead * norm_pr;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post-residual can't fit next item (smooth term).
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (gap / cap);
        } else {
            // Reward leaving space exactly usable by next item.
            score -= 5.0 * (1.0 - (gap / cap) * (gap / cap));
        }
    }

    // Prefer existing bins over opening new ones, more so late in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for bin imbalance relative to mean residual.
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean"
    // fractions of capacity (highly reusable), penalize awkward dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % 10; // modulo class on residual
    score -= match class {
        0 => 12.0, // perfectly aligned residual (e.g. 50, 40, 30)
        5 => 8.0,  // half-decade residual, still very reusable
        _ => {
            // penalize residuals in awkward classes proportionally
            let awkward = (class as f64 / 10.0).powi(2);
            4.0 * awkward
        }
    };

    // Integer-division thresholds on post_residual: tiny residuals are dead space.
    if post_residual < bin_capacity / 10 {
        score += 25.0; // nearly unusable slot
    } else if post_residual < bin_capacity / 4 {
        score += 8.0;
    } else if post_residual >= bin_capacity / 2 {
        score -= 6.0; // keeps a large flexible slot alive
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // next item fits exactly or nearly: strong reward
            let fit_quality = 1.0 - ((pr - ni) / cap).abs();
            score -= 10.0 + 10.0 * fit_quality;
            // exact harmonic match: post_residual % next_item_size == 0
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; mildly penalize tight residual that
            // will strand this bin
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are
    // heavily fragmented (high mean residual spread) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs() / cap;
        // prefer new bin when existing bins are fragmented and item is large
        score += 30.0 - 20.0 * fragmentation - 15.0 * (item_size as f64 / cap)
                 + 10.0 * progress;
    }

    // Prefer filling bins that are already committed (low residual relative to mean)
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64) / 16.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 16 {
        // Larger usable leftovers are mildly attractive.
        score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Exact match with lookahead: reserve space wisely.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If the next item would fit exactly in the post residual, slight bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 12.0;
    }
    // Avoid leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + progress);

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good packing density).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for fuller bins overall.
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: dead space penalty scaled by gap
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tighter bins relative to mean residual
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin early in the stream when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 && step_index > 0 {
        score += 150.0 + 0.5 * post_residual as f64;
    }

    // Slight progression scaling: later in stream, be more frugal with new bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize small dead space that is likely unusable later (dead-space band).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mild penalty for wasting this bin's future
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, keep score low.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more open to spreading items (open new bins);
    // later, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized as stream matures.
        score -= 60.0 * (1.0 - progress) * (1.0 - progress);
        score += 40.0 * progress;
        // If many bins already open, discourage opening yet another.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Reward using existing bins more as progress grows.
        score -= 15.0 * progress;
    }

    // Global residual coupling: prefer bins whose residual is close to the mean
    // (keep residuals balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild penalty for very large items placed into tight bins (risk of overflow elsewhere).
    if item_size > 70 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate
    // residual more since bin count dominates cost.
    let tightness_weight = 1.0 - 0.5 * progress; // decays as stream progresses
    let mut score = norm_pr * (1.0 + 2.0 * tightness_weight);

    // Penalize residual that is too small to be useful later (dead space),
    // with a smooth quadratic bowl around a "usable" residual zone.
    let usable_center = 0.35 + 0.25 * progress;
    let dead = (norm_pr - usable_center) * (norm_pr - usable_center);
    score += 3.0 * dead * norm_pr;

    // Reward near-perfect fits smoothly (small post_residual gets extra pull).
    score -= 2.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus: strongly favor using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a bin mildly, more so late in stream
    // and when open bins already exist and could fit.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 4.0 + 3.0 * openness + 2.0 * progress;
        // But if lookahead item is large and mean residual is small, soften.
        let nls = next_item_size as f64;
        if nls > 0.0 {
            score -= 2.0 * (nls / cap) * (1.0 - mean_residual / cap).max(0.0);
        }
    }

    // Lookahead synergy: reward residual that could host the next item smoothly.
    if next_item_size > 0 {
        let fit_margin = norm_pr - (next_item_size as f64 / cap);
        let synergy = 1.0 / (1.0 + (-(fit_margin * 8.0)).exp());
        score -= 1.5 * synergy * (1.0 - progress);
    }

    // Mild penalty scaled by residual relative to mean residual across bins.
    score += 0.5 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches common
    // item sizes (multiples of 10) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = pr % 10;
        if harmonic == 0 {
            score -= 8.0; // leftover aligns with the classic size grid
        } else {
            score += harmonic as f64 * 0.7; // dead space penalty
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Lookahead: reward leftovers that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 6.0 + (slack as f64).min(20.0) * 0.15;
            if post_residual == next_item_size {
                score -= 10.0; // perfect two-item chain
            }
        } else {
            score += 4.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Modulo class of item size: large items (>= half capacity) should go
    // into open bins rather than fragmenting space.
    if item_size >= bin_capacity / 2 {
        score -= 5.0;
    }
    if item_size <= bin_capacity / 5 {
        score += 2.0; // tiny items can wait for better consolidation
    }

    // Discourage spreading across too many open bins when residuals are high.
    if open_bins_count > 2 && (post_residual as f64) > mean_residual {
        score += 1.5;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing a big item then next big item in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (unusable gaps).
    let dead_threshold = (bin_capacity as f64 * 0.2).max(10.0) as u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += (dead_threshold - post_residual + 1) as f64 * 2.5;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean (balanced usage),
    // but only mildly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bins are penalized unless the item
    // is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item could exactly fill the post-residual,
    // reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the gap: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Early in the stream, be slightly more willing to open new bins
    // (keep flexibility), late in the stream pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-fit residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: residual exactly consumed by next item
        } else if post_residual > next_item_size {
            // partial match: closer match is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize proportional to wasted residual
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits (small post residual) relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 2.0 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive for very large items or near-stream end
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 50 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0; // item + next item exceed capacity -> fresh bin useful
        }
        let _ = progress;
        score += 3.0 * open_bins_count as f64; // discourage hoarding bins
    }

    // Dead-space penalty: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for blocking.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer consolidating into bins with small residuals.
    if open_bins_count > 4 {
        let rel = bin_residual as f64 / mean_residual.max(1.0);
        score += 10.0 * (rel - 1.0); // prefer below-average residual bins
    }

    // Early in stream: be pickier (leave room); late: pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline, only attractive when fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Base: post residual (lower waste preferred)
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer leaving moderate residual; late, prefer tight fits.
    let progress_coupling = (norm_pr * (1.0 - progress)) * 40.0
        + (norm_pr * norm_pr * progress) * 90.0;
    score += progress_coupling;

    // Reward near-perfect fits with a smooth superlinear bonus
    let perfect_bonus = (1.0 - norm_pr).powi(3) * 60.0;
    score -= perfect_bonus;

    // Penalize dead space that can't fit the next item (smooth sigmoid-like term)
    if nx > 0.0 {
        let unusable = ((norm_pr - nx) / (nx + 0.05)).tanh();
        score += 25.0 * (0.5 + 0.5 * unusable) * (nx / (nx + 0.2));
    }

    // Last-chance bin: strong smooth reward scaled by fit ratio
    if fitting_bins_count == 1 {
        score -= 45.0 * fit * (1.0 - norm_pr);
    }

    // Crowding effect: more open bins -> prefer using existing ones (smooth)
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= crowding * 6.0 * (1.0 - norm_pr);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let mean_norm = mean_residual / cap;
    score += 30.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // Mild preference for larger items in low-residual bins
    score += 10.0 * fit * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual modulo common item sizes (1..=100 stream)
        // Small dead space that nothing can fill is bad. Penalize residuals < 10.
        if post_residual < 10 {
            score += 60.0;
        }
        // Modulo classes: residuals congruent to 0 mod 25 or 50 are "harmonic" slots
        if post_residual % 25 == 0 {
            score -= 30.0;
        }
        if post_residual % 50 == 0 {
            score -= 20.0;
        }
        // Integer-division thresholds: how many size-10 units remain
        let units = post_residual / 10;
        score -= (units as f64) * 4.0;
        // Penalize odd/hard-to-fill classes (residual mod 10 in 1..9 wastes space)
        let rem10 = post_residual % 10;
        score += rem10 as f64 * 2.5;

        // Lookahead coupling: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size < post_residual {
                let nxt_post = post_residual - next_item_size;
                if nxt_post == 0 {
                    score -= 250.0;
                } else if nxt_post % 25 == 0 {
                    score -= 40.0;
                }
                score -= (nxt_post / 10) as f64 * 3.0;
            } else {
                // next item cannot follow here: slight penalty if residual becomes dead
                if post_residual < 10 {
                    score += 20.0;
                }
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive for large items or late stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 60.0 + 30.0 * progress;
        if item_size > threshold as u32 {
            score -= 80.0;
        } else {
            score += 120.0;
        }
        // Penalize opening new bins when many bins already open
        score += open_bins_count as f64 * 5.0;
    }

    // Tie-break toward consolidating residuals near the mean
    score -= 0.5 * (post_residual as f64 - mean_residual).abs().recip().min(5.0);
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Mild late-stream pressure to close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Dead-space penalty: small unusable gaps are costly, but post_residual == 0 is perfect.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Non-linear penalty that grows sharply for tiny gaps (wasted space).
        let dead_penalty = 40.0 / (pr + 1.0);
        // Gap too small for the smallest possible item (<=1) is pure dead space.
        if pr < 1.0 {
            score += 60.0;
        }
        score += dead_penalty;
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        score -= 30.0 + 0.5 * gap_after_next as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this gap: gap likely dead space.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    score += 0.3 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let res = bin_residual as f64;
    score -= 0.2 * (mean_residual - res);

    // New-bin candidate handling: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 140.0;
        }
        // If the item leaves a large residual in the new bin and the next item can use it,
        // opening is reasonable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    // -> this bin absorbs both items with zero dead space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly in the residual left behind
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Tight-but-fitting is good; penalize leftover slack quadratically
        score -= 25.0 - 0.35 * slack - 0.004 * slack * slack;
    }
    // Next item cannot fit here: the residual becomes pure dead space
    // unless a later item matches it. Penalize proportionally to waste.
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += 0.6 * waste + 0.01 * waste * waste;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Reward tight fits relative to the mean residual across open bins:
    // leaving far less residual than average is a good compaction.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin when decent open bins exist and
    // the current stream is not near its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let decent_open = if open_bins_count > 0 { mean_residual > item_size as f64 } else { false };
        if decent_open && progress < 0.9 {
            score += 35.0 * (1.0 - progress);
        }
        // Late in the stream, new bins are cheap to open (less future waste risk)
        if progress >= 0.9 {
            score -= 10.0;
        }
    }

    // Mild penalty for very small post-residuals that no item (min size 1..10)
    // can ever use, unless they exactly match the lookahead item.
    if post_residual > 0 && (next_item_size == 0 || post_residual != next_item_size) && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's lookahead.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly room for the next item.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / item_size.max(1) as f64 + 1.0);
        score += 6.0 + 10.0 * (1.0 - progress) * crowding.max(0.0).min(3.0);
        // New bin is attractive only if no open bin leaves a good fit.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Prefer bins with residual close to the item (best-fit flavor), scaled by global mean.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap * (1.0 + mean_residual / bin_capacity as f64);

    // Mild time-pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: reward tight fits (small post_residual), with a non-linear
    // polynomial coupling to stream progress: late in the stream, dead
    // space is penalized more aggressively (quartic growth).
    let mut score = pr as f64 * (1.0 + 0.75 * progress * progress * progress);

    // Smooth convex penalty on tiny unusable leftovers (< ~10% capacity),
    // scaled by how late we are in the stream.
    let dead = (0.12 - norm_pr).max(0.0) / 0.12;
    score += 14.0 * dead * dead * (0.4 + 0.6 * progress);

    // Reward filling a bin completely (post_residual near 0) with a
    // smooth saturating term.
    score -= 10.0 * (-norm_pr * 8.0).exp() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin, especially for large items.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * fit_ratio * (0.5 + 0.5 * progress);
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (smooth interaction between pr and next_item_size).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            // Next item won't fit: mildly penalize leaving a mid-sized gap
            // that neither closes the bin nor hosts the next item.
            score += 3.0 * (norm_pr * (1.0 - norm_pr)).max(0.0);
        }
    }

    // Prefer consolidating into bins with low average residual when the
    // stream is young (keep bins tidy for future large items); relax later.
    score += (mean_residual / cap) * (1.0 - progress) * 4.0;

    // Slight preference for keeping the number of open bins moderate.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate handling: an empty bin has pr = cap; make it
    // unattractive unless the item is large and no tight fit exists
    // (large pr already penalizes it via the base term).
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit: reward tight packing quadratically.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Harmonic class matching: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how well it fills remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            // harmonic class bonus: same modulo-10 class as item
            if next_item_size / 10 == item_size / 10 {
                score -= 5.0;
            }
        } else {
            // next item cannot use the residual: penalize small dead space that nothing fits
            score += 8.0;
        }
    }

    // Dead-space penalty: residual too small to hold the minimum item size (1..100 unknown,
    // use conservative small-item guard via modulo classes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // near-useless sliver
    }
    // Class-based dead space: penalize residuals in awkward ranges (e.g. 11..19) that few items fill
    let pr = post_residual;
    if pr >= 11 && pr <= 19 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well (i.e. this call IS the empty-bin candidate with perfect post_residual = C - item).
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; penalize opening new bins when many are open
        // with slack, reward when open bins are crowded.
        score += 15.0 + 2.0 * (open_bins_count as f64);
        // If item is small, discourage wasting a fresh bin.
        if item_size <= bin_capacity / 4 {
            score += 20.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += mean_residual * 0.3;
        // But if next item is huge and current item is huge, a fresh bin pairs them well.
        if next_item_size >= bin_capacity / 2 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight preference to reuse crowded bins (reduce open count).
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
        // Prefer bins below mean residual (consolidating slack).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Exact fit is always glorious.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: u32 = 10;
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 18.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize moderate waste proportionally, but less than dead space.
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: expensive when many bins already open.
        score += 15.0 + 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But attractive if no open bin fits well (last chance handled below).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // If next item is nearly the post residual (good chain), extra reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 5 {
        score -= 10.0;
    }

    // Slight pull toward bins with residual near mean (keep bin states balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) via non-linear dead-space penalty.
    let frag = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += 40.0 * frag;

    // 2-step lookahead: reward when the next item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fill the bin exactly
        } else if post_residual >= next_item_size {
            // next item fits here: reward, stronger the tighter the two-item fit
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit after this placement: penalize wasted residual
            score += 8.0 + 0.15 * gap;
        }
    } else {
        // Last item: only tightness matters
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tight bin) preserves slack elsewhere; reward that.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: open a fresh bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64
            || (next_item_size > 0 && post_residual < next_item_size as f64);
        if poor_fit && fitting_bins_count > 0 {
            score -= 45.0; // opening a new bin beats wasting space in a good bin
        } else if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        } else {
            score += 30.0; // an open bin fits acceptably: prefer it
        }
    }

    // Slight preference to fill older/crowded state as stream progresses.
    score += 0.01 * (open_bins_count as f64) - 0.002 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post-residual too small for the smallest plausible future item.
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item cannot fit here; slight penalty proportional to wasted potential.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more conservative (prefer filling existing bins);
    // late in the stream, tighter fits matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state: many open bins with large mean residual -> discourage new bins,
    // encourage consolidating into existing ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 0.3 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize when plenty of open bins already exist.
        score += 3.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (perfect-ish fit).
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * (slack - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: dead space matters more as the stream progresses.
    let coupling = norm_post * norm_post * (0.5 + 2.5 * progress * progress);
    score += coupling * bin_capacity as f64;

    // Perfect fit reward, amplified by progress.
    if post_residual == 0 {
        score -= 40.0 + 40.0 * progress;
    } else if post_residual < 10 {
        score -= 15.0 + 15.0 * progress;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 + 5.0 * progress;
    }

    // Penalize bins that deviate from the mean residual (encourage balanced filling).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * (10.0 + 10.0 * progress);

    // Prefer opening new bins early when fit is poor; prefer reusing bins later.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        score += 18.0 - 36.0 * progress * progress;
        // New bin attractive if item is large relative to capacity.
        score += (1.0 - norm_item) * 10.0 * (1.0 - progress);
    }

    // Mild preference to fill bins with larger fill fraction early.
    score -= (1.0 - norm_post) * (1.0 - progress) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- New-bin candidate: default to opening bins only when existing fits are poor ----
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can host the item: new bin is mandatory.
            return 0.0;
        }
        // Penalize opening a new bin; relax penalty if open bins are crowded
        // (high mean residual -> few good fits remain anywhere).
        let crowding = (mean_residual / cap).clamp(0.0, 1.0);
        return cap * 2.5 - crowding * cap * 1.2 - (fitting_bins_count as f64) * 0.5;
    }

    // ---- Base: best-fit (minimize post_residual) ----
    let mut score = post_residual as f64;

    // ---- Harmonic class term: post_residual modulo capacity/10 ----
    // Small remainders of the modular class are slightly favored, giving
    // finer granularity among near-ties in best-fit.
    let unit = (bin_capacity / 10).max(1);
    let class = (post_residual % unit) as f64;
    score += class * 0.15;

    // ---- Integer-division threshold: quarter-capacity classes ----
    // Prefer placements that leave less than a quarter of the bin free
    // (compact packing); each quarter-step of leftover adds penalty.
    let quarter = (bin_capacity / 4).max(1);
    let q = post_residual / quarter;
    score += q as f64 * 2.0;

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin stays usable for the next item: reward.
            score -= 3.0;
            // Extra reward if it fits the next item EXACTLY into a harmonic slot.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 2.0;
            }
        } else {
            // Dead space: leftover can never host the next item.
            score += post_residual as f64 * 0.5 + 5.0;
        }
    } else {
        // Last item of the stream: pure best-fit, no future to plan for.
        score -= 1.0;
    }

    // ---- Last-chance bonus: this is the only open bin that fits ----
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // ---- Stream phase: early on, be slightly more frugal with tight fits ----
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits (small waste relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio);

    // Open-bins pressure: penalize spreading across many bins slightly.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are large.
    if bin_residual == bin_capacity {
        score -= 20.0 * (mean_residual / bin_capacity as f64);
        score += 10.0;
    }

    // Progression: be slightly more conservative late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins that end nearly empty.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() <= 2.0 {
            score -= 45.0;
        } else if pr >= nxt && pr - nxt <= 10.0 {
            score -= 20.0;
        } else if pr < nxt {
            // next item cannot reuse leftover; penalize proportionally to wasted space
            let waste_ratio = pr / bin_capacity as f64;
            score += 15.0 * waste_ratio;
        }
        // If next item is large, prefer keeping roomier bins for it:
        if nxt >= 50.0 && pr < nxt {
            score += 10.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better to fill.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize the new-empty-bin candidate unless the item is large
    // (opening a fresh bin is only worthwhile for big items).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 40.0 * frac;
        // Late in the stream, discourage opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small tie-breaker: prefer bins with larger residual consumed.
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (unusable gaps hurt).
    score += 0.02 * (post_residual as f64).powi(2);

    // Reward tight fits: small post_residual gets a bonus.
    score -= 30.0 / (1.0 + post_residual as f64);

    // Lookahead: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in stream, be frugal with new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early, less late.
        score += 20.0 * (1.0 - 0.5 * progress);
        // Opening a new bin is more attractive if open bins are nearly full on average.
        score -= (mean_residual / bin_capacity as f64) * 15.0 * (1.0 - progress);
    } else {
        // Prefer filling bins with below-average residual (balance load).
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Many open bins: encourage closing them out (favor high-fill bins).
    score -= 0.1 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover, with smooth non-linear penalty on tiny residuals
    let mut score = pr as f64;
    score += 30.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Progress coupling: later in stream, penalize large residuals more (waste compounds)
    score += progress * 12.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with smooth exponential falloff
    score -= 8.0 * (-(pr * pr) / 900.0).exp();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when plenty of bins fit the item
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        // But if next item is large and this bin would be left with unusable sliver, discourage
        if next_item_size > 0 && pr < next_item_size as f64 && pr < 10.0 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - ((post_residual - next_item_size as u32) as f64) / cap);
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 18.0 * (1.0 - pr / 10.0);
    }

    // Smooth open-bins pressure: more open bins -> discourage spreading
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr;

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    score -= 3.0 * ((mean_residual - pr) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals in coarse bands (multiples of ~item granularity) are more useful.
    let r = post_residual;
    let class = r / 10; // harmonic band 0..10
    match class {
        0 => score += 60.0,            // tiny dead space: nearly unusable
        1 => score += 25.0,            // 10-19: only fits very small items
        2 => score += 10.0,            // 20-29
        3 => score -= 5.0,             // 30-39: decent
        4 | 5 => score -= 12.0,        // 40-59: good
        6 | 7 => score -= 18.0,        // 60-79: very good
        _ => score -= 8.0,             // 80-100: nearly empty (wasting a bin)
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward if the post residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= r {
            let slack = r - next_item_size;
            // Harmonic class of the slack after the lookahead item.
            if slack == 0 {
                score -= 80.0; // chains two perfect fits
            } else if slack <= 10 {
                score -= 20.0;
            } else if slack <= 30 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.15; // lookahead leaves big gap: mild penalty
            }
        } else {
            // Next item cannot fit here anyway: neutral-to-slight penalty if this
            // is our last chance bin.
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (dead space < 15).
    if fitting_bins_count == 1 && r <= 15 {
        score -= 30.0;
    }

    // New-bin candidate logic: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early or when open bins are fragmented,
        // but wasteful when this bin would be a good fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins moderately; oracle prefers filling existing bins unless
        // the alternative leaves dead space. Scale penalty with mean fragmentation.
        score += 35.0 - (mean_residual / bin_capacity as f64) * 25.0 + progress * 10.0;
        // If many bins already fit the item, opening a new one is clearly bad.
        if fitting_bins_count > 2 {
            score += 20.0 * (fitting_bins_count.min(6) as f64);
        }
    }

    // Tie-break: prefer bins whose residual was already small relative to the mean
    // (compact packing), gently.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (as long as usable).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gap: mildly penalize, since few items fit there.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: this bin becomes dead space unless residual is 0.
            if post_residual > 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // Prefer bins whose residual deviates from the mean (keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Exact-completion bonus: next item fills bin perfectly.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin early,
    // encourage it when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 * (1.0 - progress);
        if mean_residual > 0.0 && fragmentation > 0.0 {
            score += mean_residual * 0.1;
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0; // fresh bin can absorb the next item too
        }
    }

    // Slight preference for bins with residual below the mean (consolidate fullness).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Penalize very small unusable leftovers (dead space under typical min item).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, smoothly modulated by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear dead-space penalty: tiny residuals are wasted space.
    let dead = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 60.0 * dead;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 25.0 * tightness * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let gap = pr - ns;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (ns - pr) / cap;
        }
    }

    // Prefer filling bins when many bins are open relative to mean residual.
    let mean_norm = mean_residual / cap;
    score += 10.0 * mean_norm * (1.0 - norm_pr) * progress;

    // New-bin candidate: make empty bins less attractive unless residual is tiny.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by large
    // "harmonics" of the capacity are more reusable by future items.
    let cap = bin_capacity as f64;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic bonus: post_residual that is an exact divisor-multiple
    // (e.g. 0, 25, 50, 75, 100 or multiples of 20) is "friendly" space.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        if post_residual % 10 == 0 {
            score -= 3.0;
        }
        // Dead space penalty: leftover too small for the smallest plausible item.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 15.0;
        }
    }

    // Lookahead harmony: if the next item exactly fits the post_residual,
    // strongly prefer this bin (chains two placements perfectly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: mildly reward tight chaining
            score -= 10.0 * (nxt / (pr + 1.0));
            // harmonic match: next item divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 8.0 * (nxt / cap);
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate: opening a fresh bin should only win when the current
    // fit is bad. Penalize the empty bin so it loses to decent fits but wins
    // over terrible ones.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.25 * open_bins_count as f64;
    }

    // Prefer tighter fits overall: reward small post_residual relative to item.
    score -= 5.0 * (item_size as f64 / cap);

    // Slight preference to fill older/more-full bins when many bins are open.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt() * 0.1;

    // Late-stream consolidation: near the end, favor bins that keep large
    // residuals divisible by common item sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual % 5 == 0 {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or too small
    // for the next item) are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead); // tiny gap = wasted capacity
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't fit the known next item
        } else {
            score -= 5.0 * dead; // usable leftover is mildly rewarded
        }
    } else {
        // Perfect closure of a bin is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item leaves a large,
    // clean residual or existing bins would leave dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if post_residual >= 50 {
            score -= 35.0; // fresh bin with big usable space is fine
        }
    }

    // Mean-residual coupling: prefer bins below the mean residual
    // (larger items into emptier bins keeps small gaps usable).
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Late in the stream, avoid opening new bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect fit: tiny dead space
    }

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= 150.0 + (chain_waste as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item cannot chain here: penalize if post_residual is awkwardly small
        score += (post_residual as f64).min(50.0) * 0.3;
    }

    // Penalize leaving residual that is far from the mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer filling already-open bins over opening new ones,
    // more so late in the stream or when many bins are open
    if bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count as f64) * 2.0;
    } else {
        // New-bin candidate: only attractive if current bin would leave big waste
        score += (item_size as f64) * 0.1;
    }

    // Penalize new bins early when few bins exist
    if bin_residual == bin_capacity {
        score += 60.0 - (step_index as f64 / total_items.max(1) as f64) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

