        // Many alternatives: be pickier about waste
        score += 0.5 * post_residual as f64 * 0.1;
    }

    // Global residual pressure: if mean residual is high, prefer filling fuller bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: late in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, especially late and when alternatives exist
        let mut new_bin_penalty = 15.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0;
        }
        // Allow new bins early when stream is long and current bins are fragmented
        if progress < 0.3 && mean_residual > 40.0 {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for bin count growth pressure
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = base * base * (1.0 - progress) + base * (0.5 + 0.5 * progress);

    // Penalize small dead space (unusable slivers) with a smooth term
    let dead = if pr > 0.0 { (cap / (pr + 1.0)).sqrt() * 0.5 } else { 0.0 };

    // Lookahead synergy: reward if next item fits the post residual
    let lookahead = if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit = if pr >= ns { 1.0 } else { (pr / ns).min(1.0) };
        -fit * (ns / cap) * 8.0
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer using a unique fitting bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Mild pressure toward consolidating into fewer bins as stream progresses
    let consolidation = -0.02 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Alignment with mean residual: prefer bins near the mean residual
    let mean_align = -((pr - mean_residual) / cap).abs() * 0.5;

    let mut score = poly * 10.0 + dead + lookahead + last_chance + consolidation + mean_align;
    // New-bin candidate: discourage opening new bins unless post residual is large
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity split into 10 classes.
    let class = (post_residual / 10) as f64;

    // Reward tight fits: lower class (smaller residual) gets a subtraction.
    score -= (10.0 - class) * 4.0;

    // Dead-space penalty: residual in awkward zone (1..10) is nearly unusable
    // since items are >= 1 but typically larger; penalize non-zero small residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Modulo-3 / modulo-5 harmonic coupling between post_residual and next item.
    if next_item_size > 0 {
        let m = post_residual % 10;
        let nm = next_item_size % 10;
        if m == nm {
            score -= 6.0; // same harmonic class => likely future fit
        }
        if post_residual >= next_item_size {
            score -= 8.0; // next item also fits here: strong reward
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // next item won't fit: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage when
    // existing bins have decent residual and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 - 20.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // next item needs a fresh bin anyway
        }
    }

    // Prefer bins with residual close to the item size (fractional capacity match).
    let frac = (bin_residual as f64 / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
    score += (frac - (post_residual as f64 / bin_capacity as f64)).abs() * 0.0;

    // Small tie-breaker toward fewer open bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;

    // Perfect fit: overwhelming preference
    if post_residual == 0 {
        score -= 1000.0;
    }

    if is_new_bin {
        // Opening cost: base + fragmentation pressure (more open bins) +
        // end-of-stream pressure (late new bins are wasteful) + high mean
        // residual means existing bins are underfilled, penalize fragmentation.
        score += 8.0
            + open_bins_count as f64 * 1.2
            + progress * 12.0
            + mean_residual * 0.04;

        // If no open bin can hold the item, the new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Strict dead-space avoidance: small nonzero gaps are likely unusable.
        // Nonlinear: the smaller the gap, the harsher the penalty.
        if post_residual > 0 && post_residual <= 8 {
            score += 24.0 - post as f64 * 1.5; // gap 1 -> +22.5 ... gap 8 -> +12
        }

        // Lookahead coupling (k=2): a gap the next item cannot use is
        // dead space for the immediate future; a gap that reserves the
        // next item is rewarded.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.6;
            } else {
                score -= 4.0;
            }
        }

        // Last-chance bin: using it avoids opening a new bin entirely.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }

        // Consolidation pressure: with many open bins, favor filling them
        // over spreading items out.
        score -= (open_bins_count as f64).min(12.0) * 0.4;

        // Tighter-than-average bins are valuable; small nudge toward them.
        if mean_residual > post {
            score -= (mean_residual - post) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // post_residual can still host the next item: mild reward scaled by slack
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Penalize tiny dead space (unusable for items >= 1 but likely < 10 in practice)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize unless it gives a
    // perfect lookahead match or current open bins have very fragmented residuals.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if !perfect {
            let fragmentation = (mean_residual - post_residual as f64).abs();
            score += 20.0 + 10.0 * (1.0 - fragmentation / bin_capacity as f64) + 15.0 * (1.0 - progress);
        } else {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual is below mean (tighter bins) to preserve large residuals
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward near-perfect fits (dead-space suppression).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small-but-nonzero dead space superlinearly.
        let waste = post / cap;
        score += 40.0 * waste * waste;
    }

    // Lookahead: reward if the next item fits into the post residual,
    // penalize if the next item nearly fits (wasted opportunity).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 25.0 * (nxt / cap);
        } else if nxt <= post + 20.0 {
            score += 15.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: heavily reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when all open bins are quite full
    // or when many bins already exist and fits would be sloppy.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        let tight_penalty = (post_residual as f64) * 0.5;
        // Base cost of a new bin, discounted when open bins are crowded.
        score = 55.0 - 30.0 * avg_fullness + tight_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if fitting_bins_count == 1 {
            score += 80.0; // an open bin is the last chance: keep it available
        }
    }

    // Early in the stream, be more willing to spread items (keeps flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (1.0 - post / cap);

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr * pr / cap;
    let coupling = norm_pr * (1.0 - norm_pr) * (pr + 10.0);
    let mut score = base - 0.8 * coupling * (1.0 + progress);
    if post_residual == 0 {
        score -= 50.0;
    }
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - nx / cap) * (1.0 + progress);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }
    if fitting_bins_count <= 1 {
        score -= 20.0;
    }
    let mean_gap = (mean_residual - pr) / cap;
    score += 4.0 * mean_gap * mean_gap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets via integer division
    let item_class = item_size * 4 / bin_capacity; // 0..3 (small, mid, large, huge)
    let next_class = if next_item_size == 0 { 255 } else { next_item_size * 4 / bin_capacity };

    // Perfect fit reward (post_residual in low harmonic classes)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // distributionally items < 20 are rare): penalize awkward leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-10 harmonic band on post_residual: leftovers that are multiples of 10
    // are more reusable (items often align to decades).
    let post_mod = post_residual % 10;
    if post_mod == 0 && post_residual > 0 {
        score -= 15.0;
    } else {
        score += post_mod as f64 * 1.5;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // Extra reward if the chain continues: next item leaves a decade-aligned leftover
        let chain_left = post_residual - next_item_size;
        if chain_left % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: mild penalty proportional to class mismatch
        let class_gap = (next_class as i32 - item_class as i32).abs() as f64;
        score += class_gap * 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large (would leave little usable space anyway) or no tight fit exists.
    if bin_residual == bin_capacity {
        // Baseline neutral score ~ item leaves full freedom
        score = 0.5 * (bin_capacity - item_size) as f64;
        // Prefer new bin for huge items (class 3): they pair poorly with existing fill
        if item_class >= 3 {
            score -= 30.0;
        }
        // Late in the stream, discourage opening new bins (consolidation phase)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
        // Many open bins with slack: discourage new bins
        if mean_residual > item_size as f64 * 2.0 && open_bins_count > 2 {
            score += 40.0;
        }
    }

    // Mild preference for fuller bins overall (best-fit flavor scaled by harmonic class)
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (1.0 + item_class as f64 * 0.25);

    // Early stream: allow more bins for flexibility; late stream: pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap too small to hold even the smallest item is pure waste.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            // Small gap: usable only for tiny items; penalize proportionally.
            score += 25.0 * (1.0 - post_residual as f64 / 20.0);
        } else {
            // Larger gaps still degrade, but less steeply.
            score += 8.0 * (20.0_f64.min(post_residual as f64) / 20.0 - 1.0).abs() * 0.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would leave this bin's residual stranded, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tighter bins.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the current bin's residual would be wasted anyway.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 + desperation * 30.0;
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to item size (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Mean-residual coupling: placing into a bin below mean residual spreads load evenly.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match between post_residual and next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            // Perfect setup: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual as f64 >= next {
            // Next item fits here too; reward closeness of the match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement; penalize dead space,
            // more strongly when the leftover is small (hard to reuse).
            let waste = post_residual as f64;
            score += 15.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the
    // current fit is poor (large post_residual relative to mean residual)
    // or no other bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        if next_item_size > 0 {
            // A fresh bin is attractive if the item is large (tight fit expected)
            // or the next item is large.
            let it = item_size as f64 / bin_capacity as f64;
            let nx = next_item_size as f64 / bin_capacity as f64;
            if it + nx >= 0.95 {
                score -= 35.0;
            }
        }
        if item_size as f64 / bin_capacity as f64 >= 0.7 {
            score -= 20.0;
        }
    } else {
        // Reward placing into bins whose residual is above the mean (use slack
        // where it is abundant), penalize squeezing bins tighter than average.
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Progress pressure: late in the stream, avoid opening unnecessary bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full fills (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Perfect chain: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Penalize leaving a residual that the next item cannot use.
            score += 4.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good alternatives exist or the stream is late (fewer chances to fill it).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0 + 15.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64).sqrt();
        }
        // Early stream: opening bins is cheaper (future items can fill them).
        new_bin_penalty -= 12.0 * (1.0 - progress);
        // If open bins have large mean residual, prefer reusing them.
        new_bin_penalty += (mean_residual - post_residual as f64).max(0.0) * 0.3;
        score += new_bin_penalty;
    }

    // Reward filling bins that are already mostly full (close them out).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill_ratio * fill_ratio * (0.5 + progress);

    // Mild penalty for proliferating open bins when many already fit the item.
    if open_bins_count > 4 && fitting_bins_count > 2 {
        score += 1.5;
    }

    // Slight preference for bins below mean residual (balance the pool).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: reward tight fills (small post_residual), non-linearly
    let mut score = pr as f64 * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of tightness with stream progress
    let tight = fit_ratio * fit_ratio;
    score -= 12.0 * tight * (0.4 + 0.6 * progress);

    // Penalize dead space that grows with progress (less room to fix later)
    score += 6.0 * norm_pr * norm_pr * progress * (1.0 + progress);

    // Last-chance bonus: smooth sigmoid-like factor on fitting_bins_count
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.3 * (open_bins_count as f64) * norm_pr * (1.0 - progress);

    // New-bin candidate: prefer only when existing bins are all poorly fitting
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - fit_ratio.min(1.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "divisible-friendly" the leftover is.
    // Leftovers divisible by common item sizes (2,4,5,10,20,25,50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonicity = 0.0f64;
        if pr % 2 == 0 { harmonicity += 1.0; }
        if pr % 4 == 0 { harmonicity += 1.0; }
        if pr % 5 == 0 { harmonicity += 1.5; }
        if pr % 10 == 0 { harmonicity += 2.0; }
        if pr % 20 == 0 { harmonicity += 2.0; }
        if pr % 25 == 0 { harmonicity += 1.5; }
        if pr % 50 == 0 { harmonicity += 2.5; }
        score -= harmonicity * 2.5;

        // Dead space penalty: tiny leftovers (1..=9) are nearly unusable for items >=10.
        if pr < 10 {
            score += 60.0 - pr as f64 * 4.0;
        } else if pr < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item exactly / at all?
    if next_item_size > 0 {
        if next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 15.0; // next item will perfectly consume this bin
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin; leftover becomes dead weight
            score += (next_item_size - pr) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin; item_size large -> fresh bin more sensible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + item_size as f64 * 0.4 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Slight pressure against hoarding many open bins with scattered residuals.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.6;
    }

    // Prefer bins tighter than the mean residual (less wasted).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead: perfect next-item match ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: next item fills this bin completely -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize proportional to mismatch, scaled by item size
            score += diff * (0.3 + 0.4 * next_item_size as f64 / 100.0);
            // If next item can still fit after this placement, mild reward
            if post_residual >= next_item_size {
                score -= 5.0;
            }
        }
    }

    // --- Dead-space penalty: tiny unusable leftover ---
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect fill now
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += 0.5 * (mean_residual - bin_residual as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate: penalize unless current fit is poor ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only good if item is large and no tight fit exists
        score += 15.0 + 0.2 * item_size as f64;
        if item_size >= 60 {
            score -= 25.0;
        }
    }

    // --- Late-stream pressure: consolidate as stream ends ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 {
        score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            score -= 0.3 * next_item_size as f64 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: purely minimize waste.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.25 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else (large item, small residual) or late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.5
            || (fitting_bins_count <= 1 && post_residual < 20);
        if poor_fit {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 25.0 + 15.0 * (1.0 - progress);
        }
    }

    // Mild penalty when this bin's residual is far above the mean (hoarding space).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Early in stream: slight preference to consolidate into fewer bins.
    if open_bins_count > 0 && progress < 0.3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let isn = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), non-linearly
    let mut score = pr * (1.0 + 1.5 * prn * prn);

    // Smooth coupling with stream progress: late in the stream, penalize wasted space more
    score += 30.0 * prn * prn * progress;

    // Dead-space penalty: residuals too small for any item (below min size 1 handled smoothly)
    let dead = if pr < 10.0 { (10.0 - pr) * 2.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose post_residual fits the next item (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 12.0 * snug * (1.0 - progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // Mild penalty when many bins compete and this fit is mediocre
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0) * prn;
    }

    // Prefer bins below mean residual (consolidate large holes)
    score += 3.0 * (pr - mean_residual) / cap;

    // Slight preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Small item into large hole: discourage wasteful pairing early
    score += 6.0 * isn * (1.0 - isn) * prn * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large-gap" classes are penalized (dead space), small leftovers rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic bucket 0..=10
    let class_penalty = match class {
        0 => -6.0,          // near-perfect fit
        1 => -3.0,          // very good fit
        2 => -1.0,
        3 => 0.0,
        4 => 1.5,
        5 => 3.0,           // half-full leftover: moderately wasteful
        6 => 2.0,
        7 => 2.5,
        8 => 3.5,
        9 => 4.5,
        _ => 0.0,           // empty/new bin handled below
    };
    score += class_penalty;

    // Modulo-3 harmonic texture: leftover divisible by 3 pairs well with
    // many small item sizes; slight reward.
    if pr % 3 == 0 && pr > 0 {
        score -= 1.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 0.5;
    }

    // Lookahead: strongly reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic decay of reward with slack size
            score -= 4.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here; penalize proportionally
            score += 2.0 + (next_item_size - pr) as f64 / 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: neutral baseline slightly above a decent fit,
    // so we only open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score = cap * 0.45 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 3.0; // big next item: fresh bin is attractive
        }
    }

    // Late in the stream: consolidate harder into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 2.0;
    }

    // Mild tie-break toward bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps that are too small to be useful are heavily penalized.
    // Treat gaps below a "usable threshold" as wasted space.
    let usable_threshold = 20.0f64.min(next_item_size as f64);
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit bonus: small post_residual relative to item size is good
    score -= (item_size as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new bin if the item would leave a large awkward gap in existing bins
        if (post_residual as f64) > 60.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        // Fewer open bins and many items left -> opening new bin is less costly
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones (lower post_residual favored implicitly)
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item could use the post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
    }

    // Mean residual coupling: prefer bins deviating from mean in the tight direction
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly/near-exactly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // perfect follow-up match gets strongest reward
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to overshoot
        let over = (next_item_size - post_residual) as f64;
        score += over * 0.6;
    }
    // Penalize dead space relative to mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.35;
    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: penalize unless post_residual is large enough to host a future item
    if bin_residual == bin_capacity {
        // opening new bin is attractive when current open bins have poor fits
        let poor_fit = if fitting_bins_count > 0 { 0.0 } else { 20.0 };
        score += 15.0 - poor_fit;
    }
    // Late in stream: prefer tight packing, minimize residual harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        // Opening a new bin costs one bin; make it competitive only if
        // the best alternative would leave large unusable gaps.
        score = 0.5 * (bin_capacity as f64) + 0.2 * poor_fit;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage spreading.
        score += 0.5 * open_bins_count as f64;
    }

    // Global pressure: when mean residual across open bins is low, prefer
    // packing tightly into whatever fits (avoid opening new bins).
    if mean_residual < item_size as f64 {
        score -= 10.0;
    }

    // Mild preference for fuller bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = fitting_bins_count as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1
    let base = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Progress-dependent shaping: later in the stream, tight fits (small residual) are prized more.
    let tightness = (1.0 - pr_norm).powi(3);
    let progress_reward = -tightness * (40.0 + 60.0 * progress);

    // Penalize post-residuals that are dead space: neither large nor zero.
    let dead = pr_norm * (1.0 - pr_norm) * 4.0; // peaks at 0.5
    let dead_penalty = dead * 30.0 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -25.0 * (1.0 - (next_item_size as f64) / cap)
    } else if next_item_size > 0 {
        10.0
    } else {
        0.0
    };

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    let scarcity = if fitting_bins_count == 1 { -35.0 } else { -5.0 / fit };

    // Slight preference to keep mean residual balanced.
    let balance = (mean_residual - pr).abs() * 0.15;

    let mut score = base + progress_reward + dead_penalty + lookahead + scarcity + balance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits strongly
    score -= 40.0 * (1.0 - pr / cap);

    // Dead-space penalty for small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class: post_residual divisible structure (gcd-like classes mod 10)
    let class = (post_residual % 10) as f64;
    score += 0.8 * class;

    // Perfect-fill classes: post_residual in {0, 20, 25, 50} are reusable sizes
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual == 20 || post_residual == 25 || post_residual == 50 {
        score -= 8.0;
    }

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Harmonic bonus if next item divides post_residual exactly
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 35.0;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / cap);

    // Fragmentation pressure: many open bins with high mean residual
    score += 0.3 * open_bins_count as f64;
    score -= 0.2 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // even the smallest plausible item are pure waste — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are already well used
    // (residual below mean) to consolidate filling.
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits into this bin's post-residual, reward;
    // if post-residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // New-bin candidate: only attractive when nothing fits well or stream
    // is early with few open bins; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let base = 25.0 + 20.0 * progress + 8.0 * open_bins_count as f64;
        score += base - 30.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item; penalize dead space that the next item
    // cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item still fits here: reward tight two-item packing.
            let slack_after_two = post_residual - next_item_size;
            score -= 12.0 + (slack_after_two as f64).min(30.0) * 0.3;
        } else {
            // Next item will not fit in the leftover: penalize proportionally.
            let unusable = (next_item_size - post_residual) as f64;
            score += unusable * 0.25;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Perfect closure: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Very small dead space is nearly closed: strong reward.
        score -= 10.0;
    } else if post_residual < 20 {
        // Small dead space below the minimum item size: mild reward.
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it enables a much better
    // long-term layout, e.g. early in the stream or when mean residual
    // across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 8.0 + fragmentation * 0.2 - progress * 6.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    score -= tight;

    // Lookahead synergy: strongly reward bins whose post-residual can still
    // host the next item; penalize creating dead space that blocks it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 100.0) * 4.0;
        } else {
            // Dead space relative to next item: penalize proportionally to waste.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += waste * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when open bins
    // have poor fits. Scale slightly with stream progress (early on, open
    // freely; late, consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 25.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // If nothing fits anywhere, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        return score;
    }

    // Prefer bins below the mean residual slightly (balance load) when many
    // bins are open; when few bins are open, prefer filling the fullest.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    if open_bins_count > 4 {
        score -= dev * 3.0;
    } else {
        score += dev * 3.0;
    }

    // Mild consolidation pressure late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, smoothly damped by progress
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Non-linear polynomial coupling of post residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 30.0 * coupling;

    // Penalize tiny dead space (unusable slivers) with smooth quartic term
    if pr > 0.0 {
        let tiny = 1.0 - (pr / cap).min(1.0);
        score += 8.0 * tiny * tiny * tiny * tiny;
    }

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr) * progress * (1.0 - norm_pr);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing ones
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Lookahead: if next item fits exactly into post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 10.0 * fit_quality * fit_quality;
    }

    // New-bin candidate: penalize mildly unless current bins are very fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score = 0.5 * cap + 40.0 * fragmentation * progress;
    }

    // Mean residual interaction: bins deviating below mean residual are better targets
    score += 5.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item classes (multiples of 10) are more reusable than odd residues.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            2 | 4 | 6 | 8 => 3.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;
    }

    // Dead-space penalty: tiny leftovers that no future item (min size 1,
    // but typical classes >= 10) can use.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin unless the item is large (would leave a
    // large, reusable residue) or the current stream is late.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Large items pack well into fresh bins; small items should reuse.
        let new_bin_penalty = 20.0 + 60.0 * (1.0 - item_frac);
        score += new_bin_penalty;
        // Late in the stream, waste matters less; allow new bins more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        // If many open bins already, consolidating is better than expanding.
        score += 2.0 * (open_bins_count as f64).min(20.0);
    } else {
        // Prefer tighter existing bins: smaller residual before placement
        // means better fill; nudge selection toward best-fit.
        score += 0.05 * (bin_residual as f64 - post_residual as f64);
        // Reward bins that are already relatively full.
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 8.0 * fill;
    }

    // Mean residual context: when the average open-bin residual is small,
    // this bin's leftover is comparatively precious; scale reward.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 1.0 {
            score -= 6.0 * (1.0 - ratio);
        } else {
            score += 4.0 * (ratio - 1.0).min(2.0);
        }
    }

    // Integer-division threshold: leftovers in the band [10, 25) are prime
    // targets for small items; leftovers above half capacity indicate a
    // poor fit for a large item — penalize.
    if pr >= 10 && pr < 25 {
        score -= 8.0;
    }
    if pr > 50 && bin_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward when post_residual still fits the lookahead item (k=2 synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size >= item_size {
        // bin would be dead for the next item while a better bin might exist
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor filling existing),
    // but for the empty new-bin candidate (residual == capacity) add pressure to avoid sprawl.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // early stream: opening bins is cheap
        score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to how badly it misses
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Penalize tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than average residual (fill crowded bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight bias toward opening new bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual < 10 {
        score -= 8.0; // perfect closure is excellent
    } else if post_residual < 25 {
        score += 3.0; // small awkward gap
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // extra reward for exact-ish chain fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            score += 2.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin mildly attractive only late in the stream
    // or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = (open_bins_count as f64 / 10.0).min(1.0);
        score += 12.0 - 6.0 * progress - 4.0 * crowd;
        // But if the item is large relative to capacity, prefer a fresh bin sooner.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Global pressure: when mean residual across open bins is high, prefer filling
    // existing bins rather than spreading items out.
    score -= 0.05 * mean_residual;

    // Slight preference for bins with residual close to the item (best-fit core).
    score += 0.02 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, slightly super-linear to punish dead space
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth progress coupling: later in stream, tolerate residual more (keep bins tight)
    score *= 1.0 - 0.25 * progress + 0.35 * progress * progress;

    // Next-item lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * progress;
    }

    // Many open bins: prefer filling existing ones over spreading
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual deviation: prefer bins whose residual differs from mean (diversity of sizes)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score -= 5.0 * dev * (1.0 - dev);

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose residual lies in
    // "usable" residue classes (multiples of 10, 20, 25) are more likely to
    // host future items drawn from an unknown but quantized-ish stream.
    let pr = post_residual;
    let usable = if pr == 0 {
        3.0 // perfect fill: best possible outcome
    } else if pr % 50 == 0 {
        2.0
    } else if pr % 25 == 0 {
        1.5
    } else if pr % 10 == 0 {
        1.0
    } else if pr % 5 == 0 {
        0.5
    } else {
        0.0
    };
    score -= 6.0 * usable;

    // Penalize tiny dead space that is too small for the smallest plausible
    // item (min size 1..10 band): residual in 1..=9 is wasted space.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, mildly penalize (dead space ahead).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // harmonic class of the leftover after the lookahead item
            let lft = pr - next_item_size;
            let bonus = if lft == 0 { 2.0 } else if lft % 10 == 0 { 1.0 } else if lft % 5 == 0 { 0.5 } else { 0.0 };
            score -= 10.0 * bonus;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (opening fresh bins for big items preserves flexibility).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 18.0 * frac;
        // discourage hoarding many open bins
        score += 2.0 * open_bins_count as f64;
    } else {
        // prefer tighter existing bins: reward small pre-residual
        score += 0.15 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Progress-aware tightening: late in the stream, prefer near-perfect fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * usable;

    // Mean-residual context: if this bin's residual is far below the mean,
    // it is unusually tight -> favor it.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (items >= 1, but small gaps < 10 are pure waste)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post) * 8.0;
    }

    // Reward tight fits strongly: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Moderate reward for gaps that still fit the lookahead item (keeps
    // flexibility for the next arrival).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 10.0; // gap becomes unusable for the known next item
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (cap / 8.0);
    score += pressure * (1.0 - progress) * 4.0;

    // New-bin candidate: make the empty bin attractive only when the item
    // leaves a large, versatile residual and no good fit exists among open
    // bins (mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual >= item_size as f64;
        if mean_fit {
            // An open bin can take it reasonably; make new bin unattractive.
            score += 25.0 + mean_residual * 0.3;
        } else {
            // Prefer a fresh bin; large leftover stays versatile.
            score -= 20.0;
        }
    }

    // Mild preference for bins with larger residuals among open bins when
    // everything else is close (keeps small residuals for small items).
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post-fit residual
    // exactly accommodates the next item, penalize dead space the next item cannot use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: residual consumed exactly by next item.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.35;
        } else {
            // Dead space for the lookahead item: penalize the unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.55;
        }
    } else {
        // Last item in stream: pure tight-fit preference.
        score -= 10.0;
    }

    // Reward tight fits overall (small post_residual is good, but lookahead dominates).
    score -= (bin_residual - post_residual) as f64 * 0.10;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slightly favor bins with residual below the mean (consolidating fuller bins),
    // which keeps large residuals available for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate: make opening a new bin mildly unattractive by default,
    // but allow it when the current bin would leave a large unusable residual
    // relative to the lookahead need.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // An empty bin wastes capacity for a chainable fit; discourage.
            score += 18.0;
        }
    }

    // Mild stream-progression pressure: early on, be conservative about spreading;
    // later, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    // Penalize leaving residuals in the awkward 1..10 dead-zone range after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear in fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill * fill;

    // Penalize small dead space that nothing (min size 1..) can reuse later,
    // but only mildly since items can be as small as 1 here.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits: reward proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty for fragmenting
            score += 3.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidation
    // into bins below mean residual (larger items) to balance residuals.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }
    if open_bins_count as f64 > (step_index as f64).max(1.0) * 0.9 {
        // too many bins relative to progress: encourage filling existing ones
        score -= 6.0;
    }

    // Time horizon: early in the stream, keep residuals flexible (penalize very
    // small post residuals slightly); late in stream, squeeze bins hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual < 15 {
        score += 5.0;
    }
    if progress > 0.7 {
        score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // but if this bin is the last chance and the item is huge relative to residual,
        // opening fresh may be fine — reduce penalty when item is large.
        score -= 0.2 * item_size as f64;
        // if many bins are open and mean residual is small, opening new is cheap
        if mean_residual < 20.0 && open_bins_count > 3 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;

    // Base: post residual, with non-linear polynomial shaping by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr) - 3.0 * norm_pr * (1.0 - norm_pr) * cap;

    // Penalize large dead space quadratically, modulated by progress.
    score += 0.02 * pr * pr / cap;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 8.0 * (1.0 - norm_pr).powi(2) * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= 6.0 * fits * (1.0 - gap);
        score += 4.0 * (1.0 - fits) * nxt / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Mild penalty when many bins are open and this fit is loose.
    score += 0.05 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    // Mean residual deviation: prefer bins near mean residual to balance load.
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Slight preference against new bins early, stronger late if fit is decent.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: small dead space is bad; classify post_residual into
    // "unusable" classes via integer division thresholds.
    let dead = post_residual as f64;
    if post_residual > 0 {
        // Items are 1..=100, so residuals <= min next item size are dead-ish.
        let unusable = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        // Modulo-class penalty: residuals in awkward bands (e.g. 1..10, 11..20)
        let class = (post_residual / 10) % 4; // harmonic band class 0..3
        let band_penalty = match class {
            0 => 30.0, // tiny slivers: worst
            1 => 15.0,
            2 => 5.0,
            _ => 0.0,
        };
        score += unusable * 40.0 + band_penalty;
        // Non-linear dead-space amplification
        score += (dead / bin_capacity as f64).powi(2) * 50.0;
    }

    // Last-chance bin: strongly prefer using it (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad,
    // but reward opening when current item is small and stream is early (save big bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 35.0;
        // If item is large (> half), filling a fresh bin is efficient
        if item_size > bin_capacity / 2 { new_bin_score -= 25.0; }
        // If next item is large and this item is small, keep fresh bins for pairing
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && item_size <= bin_capacity / 3 {
            new_bin_score -= 20.0;
        }
        // Late in stream: consolidate, discourage new bins
        new_bin_score += progress * 25.0;
        // Many open bins already: discourage more
        new_bin_score += open_bins_count as f64 * 2.0;
        score += new_bin_score;
    }

    // Prefer bins tighter than average (good fit relative to fleet)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead harmony: if next item exactly fills this bin after current placement,
    // big reward (perfect 2-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // residual can still host next item: mild reward proportional to leftover
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fitting the next item too (lookahead harmony).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bins pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when it avoids bad dead space
    // (i.e., current item would leave a tiny gap in every open bin).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            // Forced: no open bin fits.
            score -= 200.0;
        } else if post_residual < 10 || (next_item_size > 0 && next_item_size <= item_size) {
            // Opening fresh is fine: item is large relative to next, or tiny gaps otherwise.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff * 0.25);
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: this bin absorbs both items exactly
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Reward tight fits overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize dead space relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        score += 40.0 - poor_fit * 0.2;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 35.0; // fresh bin can host both items cleanly
        }
        // Late in the stream, discourage spawning extra bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    score
}
